INSERT INTO public.quiz_questions
  (slug, tier, module, body, difficulty, question, options, answer, explanation, reference, is_published)
VALUES
  ('const-art-001', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «نظام الحكم بالمغرب نظام ملكية دستورية، ديمقراطية برلمانية واجتماعية»؟', '["الفصل 1", "الفصل 2", "الفصل 3", "الفصل 4"]'::jsonb, 0, 'الفصل 1 من دستور 2011 ينص على: «نظام الحكم بالمغرب نظام ملكية دستورية، ديمقراطية برلمانية واجتماعية. يقوم النظام الدستوري للمملكة على أساس فصل السلط، وتوازنها وتعاونها، والديمقراطية المواطنة والتشاركية، وعلى مبادئ الحكامة الجيدة، وربط المسؤولية بالمحاسبة. تستند الأمة في حياتها العامة على ثوابت جامعة، تتمثل في الدين الإسلامي السمح، والوحدة الوطنية متعددة الروافد، والملكية الدستورية، والاختيار الديمقراطي. التنظيم الترابي للمملكة تنظيم لا مركزي، يقوم على الجهوية المتقدمة.»', 'دستور 2011، الفصل 1', true),
  ('const-art-002', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «السيادة للأمة، تمارسها مباشرة بالاستفتاء، وبصفة غير مباشرة بواسطة ممثليها»؟', '["الفصل 1", "الفصل 2", "الفصل 3", "الفصل 4"]'::jsonb, 1, 'الفصل 2 من دستور 2011 ينص على: «السيادة للأمة، تمارسها مباشرة بالاستفتاء، وبصفة غير مباشرة بواسطة ممثليها. تختار الأمة ممثليها في المؤسسات المنتخبة بالاقتراع الحر والنزيه والمنتظم.»', 'دستور 2011، الفصل 2', true),
  ('const-art-003', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «الإسلام دين الدولة، والدولة تضمن لكل واحد حرية ممارسة شؤونه الدينية»؟', '["الفصل 2", "الفصل 3", "الفصل 4", "الفصل 5"]'::jsonb, 1, 'الفصل 3 من دستور 2011 ينص على: «الإسلام دين الدولة، والدولة تضمن لكل واحد حرية ممارسة شؤونه الدينية.»', 'دستور 2011، الفصل 3', true),
  ('const-art-004', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «علم المملكة هو اللواء الأحمر الذي تتوسطه نجمة خضراء خماسية الفروع»؟', '["الفصل 3", "الفصل 4", "الفصل 5", "الفصل 6"]'::jsonb, 1, 'الفصل 4 من دستور 2011 ينص على: «علم المملكة هو اللواء الأحمر الذي تتوسطه نجمة خضراء خماسية الفروع. شعار المملكة: الله، الوطن، الملك.»', 'دستور 2011، الفصل 4', true),
  ('const-art-005', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تظل العربية اللغة الرسمية للدولة. وتعمل الدولة على حمايتها وتطويرها، وتنمية استعمالها. تعد الأمازيغية أيضا لغة رسمية للدولة، باعتبارها رصيدا مشتركا لجميع المغاربة بدون استثناء. يحدد قانون تنظيمي مراحل تفعيل الطابع الرسمي للأمازيغية، وكيفيات إدماجها في مجال»؟', '["الفصل 4", "الفصل 5", "الفصل 6", "الفصل 7"]'::jsonb, 1, 'الفصل 5 من دستور 2011 ينص على: «تظل العربية اللغة الرسمية للدولة. وتعمل الدولة على حمايتها وتطويرها، وتنمية استعمالها. تعد الأمازيغية أيضا لغة رسمية للدولة، باعتبارها رصيدا مشتركا لجميع المغاربة بدون استثناء. يحدد قانون تنظيمي مراحل تفعيل الطابع الرسمي للأمازيغية، وكيفيات إدماجها في مجال التعليم، وفي مجالات الحياة العامة ذات الأولوية، وذلك لكي تتمكن من القيام مستقبلا بوظيفتها، بصفتها لغة رسمية. تعمل الدولة على صيانة الحسانية، باعتبارها جزءا لا يتجزأ من الهوية الثقافية المغربية الموحدة، وعلى حماية اللهجات والتعبيرات الثقافية المستعملة في المغرب، وتسهر على انسجام السياسة اللغوية والثقافية الوطنية، وعلى تعلم وإتقان اللغات الأجنبية الأكثر تداولا في العالم؛ باعتبارها وسائل للتواصل والانخراط والتفاعل مع مجتمع المعرفة، والانفتاح على مختلف الثقافات، وعلى حضارة العصر. يُحدَث مجلس وطني للغات والثقافة المغربية، مهمته، على وجه الخصوص، حماية وتنمية اللغتين العربية والأمازيغية، ومختلف التعبيرات الثقافية المغربية باعتبارها تراثا أصيلا وإبداعا معاصرا. ويضم كل المؤسسات المعنية بهذه المجالات. ويحدد قانون تنظيمي صلاحياته وتركيبته وكيفيات سيره.»', 'دستور 2011، الفصل 5', true),
  ('const-art-006', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «القانون هو أسمى تعبير عن إرادة الأمة. والجميع، أشخاصا ذاتيين أو اعتباريين، بما فيهم السلطات العمومية، متساوون أمامه، وملزمون بالامتثال له. تعمل السلطات العمومية على توفير الظروف التي تمكن من تعميم الطابع الفعلي لحرية المواطنات والمواطنين، والمساواة بينهم، ومن»؟', '["الفصل 5", "الفصل 6", "الفصل 7", "الفصل 8"]'::jsonb, 1, 'الفصل 6 من دستور 2011 ينص على: «القانون هو أسمى تعبير عن إرادة الأمة. والجميع، أشخاصا ذاتيين أو اعتباريين، بما فيهم السلطات العمومية، متساوون أمامه، وملزمون بالامتثال له. تعمل السلطات العمومية على توفير الظروف التي تمكن من تعميم الطابع الفعلي لحرية المواطنات والمواطنين، والمساواة بينهم، ومن مشاركتهم في الحياة السياسية والاقتصادية والثقافية والاجتماعية. تعتبر دستورية القواعد القانونية، وتراتبيتها، ووجوب نشرها، مبادئ ملزمة. ليس للقانون أثر رجعي.»', 'دستور 2011، الفصل 6', true),
  ('const-art-007', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تعمل الأحزاب السياسية على تأطير المواطنات والمواطنين وتكوينهم السياسي، وتعزيز انخراطهم في الحياة الوطنية، وفي تدبير الشأن العام، وتساهم في التعبير عن إرادة الناخبين، والمشاركة في ممارسة السلطة، على أساس التعددية والتناوب، بالوسائل الديمقراطية، وفي نطاق»؟', '["الفصل 6", "الفصل 7", "الفصل 8", "الفصل 9"]'::jsonb, 1, 'الفصل 7 من دستور 2011 ينص على: «تعمل الأحزاب السياسية على تأطير المواطنات والمواطنين وتكوينهم السياسي، وتعزيز انخراطهم في الحياة الوطنية، وفي تدبير الشأن العام، وتساهم في التعبير عن إرادة الناخبين، والمشاركة في ممارسة السلطة، على أساس التعددية والتناوب، بالوسائل الديمقراطية، وفي نطاق المؤسسات الدستورية. تُؤسس الأحزاب وتُمارس أنشطتها بحرية، في نطاق احترام الدستور والقانون. نظام الحزب الوحيد نظام غير مشروع. لا يجوز أن تؤسس الأحزاب السياسية على أساس ديني أو لغوي أو عرقي أو جهوي، وبصفة عامة، على أي أساس من التمييز أو المخالفة لحقوق الإنسان. ولا يجوز أن يكون هدفها المساس بالدين الإسلامي، أو بالنظام الملكي، أو المبادئ الدستورية، أو الأسس الديمقراطية، أو الوحدة الوطنية أو الترابية للمملكة. يجب أن يكون تنظيم الأحزاب السياسية وتسييرها مطابقا للمبادئ الديمقراطية. يحدد قانون تنظيمي، في إطار المبادئ المشار إليها في هذا الفصل، القواعد المتعلقة، بصفة خاصة، بتأسيس الأحزاب السياسية، وأنشطتها ومعايير تخويلها الدعم المالي للدولة، وكذا كيفيات مراقبة تمويلها.»', 'دستور 2011، الفصل 7', true),
  ('const-art-008', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تساهم المنظمات النقابية للأُجراء، والغرف المهنية، والمنظمات المهنية للمشغلين، في الدفاع عن الحقوق والمصالح الاجتماعية والاقتصادية للفئات التي تمثلها، وفي النهوض بها»؟', '["الفصل 7", "الفصل 8", "الفصل 9", "الفصل 10"]'::jsonb, 1, 'الفصل 8 من دستور 2011 ينص على: «تساهم المنظمات النقابية للأُجراء، والغرف المهنية، والمنظمات المهنية للمشغلين، في الدفاع عن الحقوق والمصالح الاجتماعية والاقتصادية للفئات التي تمثلها، وفي النهوض بها. ويتم تأسيسها وممارسة أنشطتها بحرية، في نطاق احترام الدستور والقانون. يجب أن تكون هياكل هذه المنظمات وتسييرها مطابقة للمبادئ الديمقراطية. تعمل السلطات العمومية على تشجيع المفاوضة الجماعية، وعلى إبرام اتفاقيات الشغل الجماعية، وفق الشروط التي ينص عليها القانون. يحدد القانون، بصفة خاصة، القواعد المتعلقة بتأسيس المنظمات النقابية وأنشطتها، وكذا معايير تخويلها الدعم المالي للدولة، وكيفيات مراقبة تمويلها.»', 'دستور 2011، الفصل 8', true),
  ('const-art-009', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «لا يمكن حل الأحزاب السياسية والمنظمات النقابية أو توقيفها من لدن السلطات العمومية، إلا بمقتضى مقرر قضائي»؟', '["الفصل 8", "الفصل 9", "الفصل 10", "الفصل 11"]'::jsonb, 1, 'الفصل 9 من دستور 2011 ينص على: «لا يمكن حل الأحزاب السياسية والمنظمات النقابية أو توقيفها من لدن السلطات العمومية، إلا بمقتضى مقرر قضائي.»', 'دستور 2011، الفصل 9', true),
  ('const-art-010', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يضمن الدستور للمعارضة البرلمانية مكانة تخولها حقوقا، من شأنها تمكينها من النهوض بمهامها، على الوجه الأكمل، في العمل البرلماني والحياة السياسية»؟', '["الفصل 9", "الفصل 10", "الفصل 11", "الفصل 12"]'::jsonb, 1, 'الفصل 10 من دستور 2011 ينص على: «يضمن الدستور للمعارضة البرلمانية مكانة تخولها حقوقا، من شأنها تمكينها من النهوض بمهامها، على الوجه الأكمل، في العمل البرلماني والحياة السياسية. ويضمن الدستور، بصفة خاصة، للمعارضة الحقوق التالية: حرية الرأي والتعبير والاجتماع؛ حيزا زمنيا في وسائل الإعلام العمومية يتناسب مع تمثيليتها؛ الاستفادة من التمويل العمومي وفق مقتضيات القانون؛ المشاركة الفعلية في مسطرة التشريع، لا سيما عن طريق تسجيل مقترحات قوانين بجدول أعمال مجلسي البرلمان؛ المشاركة الفعلية في مراقبة العمل الحكومي، لا سيما عن طريق ملتمس الرقابة، ومساءلة الحكومة، والأسئلة الشفوية الموجهة للحكومة، واللجان النيابية لتقصي الحقائق؛ المساهمة في اقتراح المترشحين وفي انتخاب أعضاء المحكمة الدستورية؛ تمثيلية ملائمة في الأنشطة الداخلية لمجلسي البرلمان؛ رئاسة اللجنة المكلفة بالتشريع بمجلس النواب؛ التوفر على وسائل ملائمة للنهوض بمهامها المؤسسية؛ المساهمة الفاعلة في الدبلوماسية البرلمانية، للدفاع عن القضايا العادلة للوطن ومصالحه الحيوية؛ المساهمة في تأطير وتمثيل المواطنات والمواطنين، من خلال الأحزاب المكونة لها، طبقا لأحكام الفصل 7 من هذا الدستور؛ ممارسة السلطة عن طريق التناوب الديمقراطي، محليا وجهويا ووطنيا، في نطاق أحكام الدستور. يجب على فرق المعارضة المساهمة في العمل البرلماني بكيفية فعالة وبناءة. تحدد كيفيات ممارسة فرق المعارضة لهذه الحقوق، حسب الحالة، بموجب قوانين تنظيمية أو قوانين أو بمقتضى النظام الداخلي لكل مجلس من مجلسي البرلمان.»', 'دستور 2011، الفصل 10', true),
  ('const-art-011', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «الانتخابات الحرة والنزيهة والشفافة هي أساس مشروعية التمثيل الديمقراطي»؟', '["الفصل 10", "الفصل 11", "الفصل 12", "الفصل 13"]'::jsonb, 1, 'الفصل 11 من دستور 2011 ينص على: «الانتخابات الحرة والنزيهة والشفافة هي أساس مشروعية التمثيل الديمقراطي. السلطات العمومية ملزمة بالحياد التام إزاء المترشحين، وبعدم التمييز بينهم. يحدد القانون القواعد التي تضمن الاستفادة، على نحو منصف، من وسائل الإعلام العمومية، والممارسة الكاملة للحريات والحقوق الأساسية، المرتبطة بالحمالات الانتخابية، وبعمليات التصويت. وتسهر السلطات المختصة بتنظيم الانتخابات على تطبيقها. يحدد القانون شروط وكيفيات الملاحظة المستقلة والمحايدة للانتخابات، طبقا للمعايير المتعارف عليها دوليا. كل شخص خالف المقتضيات والقواعد المتعلقة بنزاهة وصدق وشفافية العمليات الانتخابية، يعاقب على ذلك بمقتضى القانون. تتخذ السلطات العمومية الوسائل الكفيلة بالنهوض بمشاركة المواطنات والمواطنين في الانتخابات.»', 'دستور 2011، الفصل 11', true),
  ('const-art-012', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تُؤسس جمعيات المجتمع المدني والمنظمات غير الحكومية وتمارس أنشطتها بحرية، في نطاق احترام الدستور والقانون»؟', '["الفصل 11", "الفصل 12", "الفصل 13", "الفصل 14"]'::jsonb, 1, 'الفصل 12 من دستور 2011 ينص على: «تُؤسس جمعيات المجتمع المدني والمنظمات غير الحكومية وتمارس أنشطتها بحرية، في نطاق احترام الدستور والقانون. لا يمكن حل هذه الجمعيات والمنظمات أو توقيفها من لدن السلطات العمومية، إلا بمقتضى مقرر قضائي. تُساهم الجمعيات المهتمة بقضايا الشأن العام، والمنظمات غير الحكومية، في إطار الديمقراطية التشاركية، في إعداد قرارات ومشاريع لدى المؤسسات المنتخبة والسلطات العمومية، وكذا في تفعيلها وتقييمها. وعلى هذه المؤسسات والسلطات تنظيم هذه المشاركة، طبق شروط وكيفيات يحددها القانون. يجب أن يكون تنظيم الجمعيات والمنظمات غير الحكومية وتسييرها مطابقا للمبادئ الديمقراطية.»', 'دستور 2011، الفصل 12', true),
  ('const-art-013', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تعمل السلطات العمومية على إحداث هيئات للتشاور، قصد إشراك مختلف الفاعلين الاجتماعيين، في إعداد السياسات العمومية وتفعيلها وتنفيذها وتقييمها»؟', '["الفصل 12", "الفصل 13", "الفصل 14", "الفصل 15"]'::jsonb, 1, 'الفصل 13 من دستور 2011 ينص على: «تعمل السلطات العمومية على إحداث هيئات للتشاور، قصد إشراك مختلف الفاعلين الاجتماعيين، في إعداد السياسات العمومية وتفعيلها وتنفيذها وتقييمها.»', 'دستور 2011، الفصل 13', true),
  ('const-art-014', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «للمواطنات والمواطنين، ضمن شروط وكيفيات يحددها قانون تنظيمي، الحق في تقديم ملتمسات في مجال التشريع»؟', '["الفصل 13", "الفصل 14", "الفصل 15", "الفصل 16"]'::jsonb, 1, 'الفصل 14 من دستور 2011 ينص على: «للمواطنات والمواطنين، ضمن شروط وكيفيات يحددها قانون تنظيمي، الحق في تقديم ملتمسات في مجال التشريع.»', 'دستور 2011، الفصل 14', true),
  ('const-art-015', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «للمواطنات والمواطنين الحق في تقديم عرائض إلى السلطات العمومية»؟', '["الفصل 14", "الفصل 15", "الفصل 16", "الفصل 17"]'::jsonb, 1, 'الفصل 15 من دستور 2011 ينص على: «للمواطنات والمواطنين الحق في تقديم عرائض إلى السلطات العمومية. ويحدد قانون تنظيمي شروط وكيفيات ممارسة هذا الحق.»', 'دستور 2011، الفصل 15', true),
  ('const-art-016', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تعمل المملكة المغربية على حماية الحقوق والمصالح المشروعة للمواطنات والمواطنين المغاربة المقيمين في الخارج، في إطار احترام القانون الدولي والقوانين الجاري بها العمل في بلدان الاستقبال»؟', '["الفصل 15", "الفصل 16", "الفصل 17", "الفصل 18"]'::jsonb, 1, 'الفصل 16 من دستور 2011 ينص على: «تعمل المملكة المغربية على حماية الحقوق والمصالح المشروعة للمواطنات والمواطنين المغاربة المقيمين في الخارج، في إطار احترام القانون الدولي والقوانين الجاري بها العمل في بلدان الاستقبال. كما تحرص على الحفاظ على الوشائج الإنسانية معهم، ولا سيما الثقافية منها، وتعمل على تنميتها وصيانة هويتهم الوطنية. تسهر الدولة على تقوية مساهمتهم في تنمية وطنهم المغرب، وكذا على تمتين أواصر الصداقة والتعاون مع حكومات ومجتمعات البلدان المقيمين بها أو التي يعتبرون من مواطنيها.»', 'دستور 2011، الفصل 16', true),
  ('const-art-017', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يتمتع المغاربة المقيمون في الخارج بحقوق المواطنة كاملة، بما فيها حق التصويت والترشيح في الانتخابات»؟', '["الفصل 16", "الفصل 17", "الفصل 18", "الفصل 19"]'::jsonb, 1, 'الفصل 17 من دستور 2011 ينص على: «يتمتع المغاربة المقيمون في الخارج بحقوق المواطنة كاملة، بما فيها حق التصويت والترشيح في الانتخابات. ويمكنهم تقديم ترشيحاتهم للانتخابات على مستوى اللوائح والدوائر الانتخابية، المحلية والجهوية والوطنية. ويحدد القانون المعايير الخاصة بالأهلية للانتخاب وحالات التنافي. كما يحدد شروط وكيفيات الممارسة الفعلية لحق التصويت وحق الترشيح، انطلاقا من بلدان الإقامة.»', 'دستور 2011، الفصل 17', true),
  ('const-art-018', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تعمل السلطات العمومية على ضمان أوسع مشاركة ممكنة للمغاربة المقيمين في الخارج، في المؤسسات الاستشارية، وهيئات الحكامة الجيدة، التي يحدثها الدستور أو القانون»؟', '["الفصل 17", "الفصل 18", "الفصل 19", "الفصل 20"]'::jsonb, 1, 'الفصل 18 من دستور 2011 ينص على: «تعمل السلطات العمومية على ضمان أوسع مشاركة ممكنة للمغاربة المقيمين في الخارج، في المؤسسات الاستشارية، وهيئات الحكامة الجيدة، التي يحدثها الدستور أو القانون. الباب الثاني: الحريات والحقوق الأساسية»', 'دستور 2011، الفصل 18', true),
  ('const-art-019', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يتمتع الرجل والمرأة، على قدم المساواة، بالحقوق والحريات المدنية والسياسية والاقتصادية والاجتماعية والثقافية والبيئية، الواردة في هذا الباب من الدستور، وفي مقتضياته الأخرى، وكذا في الاتفاقيات والمواثيق الدولية، كما صادق عليها المغرب، وكل ذلك في نطاق أحكام»؟', '["الفصل 18", "الفصل 19", "الفصل 20", "الفصل 21"]'::jsonb, 1, 'الفصل 19 من دستور 2011 ينص على: «يتمتع الرجل والمرأة، على قدم المساواة، بالحقوق والحريات المدنية والسياسية والاقتصادية والاجتماعية والثقافية والبيئية، الواردة في هذا الباب من الدستور، وفي مقتضياته الأخرى، وكذا في الاتفاقيات والمواثيق الدولية، كما صادق عليها المغرب، وكل ذلك في نطاق أحكام الدستور وثوابت المملكة وقوانينها. تسعى الدولة إلى تحقيق مبدأ المناصفة بين الرجال والنساء. وتُحدث لهذه الغاية، هيئة للمناصفة ومكافحة كل أشكال التمييز.»', 'دستور 2011، الفصل 19', true),
  ('const-art-020', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «الحق في الحياة هو أول الحقوق لكل إنسان. ويحمي القانون هذا الحق»؟', '["الفصل 19", "الفصل 20", "الفصل 21", "الفصل 22"]'::jsonb, 1, 'الفصل 20 من دستور 2011 ينص على: «الحق في الحياة هو أول الحقوق لكل إنسان. ويحمي القانون هذا الحق.»', 'دستور 2011، الفصل 20', true),
  ('const-art-021', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «لكل فرد الحق في سلامة شخصه وأقربائه، وحماية ممتلكاته»؟', '["الفصل 20", "الفصل 21", "الفصل 22", "الفصل 23"]'::jsonb, 1, 'الفصل 21 من دستور 2011 ينص على: «لكل فرد الحق في سلامة شخصه وأقربائه، وحماية ممتلكاته. تضمن السلطات العمومية سلامة السكان، وسلامة التراب الوطني، في إطار احترام الحريات والحقوق الأساسية المكفولة للجميع.»', 'دستور 2011، الفصل 21', true),
  ('const-art-022', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «لا يجوز المس بالسلامة الجسدية أو المعنوية لأي شخص، في أي ظرف، ومن قبل أي جهة كانت، خاصة أو عامة»؟', '["الفصل 21", "الفصل 22", "الفصل 23", "الفصل 24"]'::jsonb, 1, 'الفصل 22 من دستور 2011 ينص على: «لا يجوز المس بالسلامة الجسدية أو المعنوية لأي شخص، في أي ظرف، ومن قبل أي جهة كانت، خاصة أو عامة. لا يجوز لأحد أن يعامل الغير، تحت أي ذريعة، معاملة قاسية أو لا إنسانية أو مهينة أو حاطة بالكرامة الإنسانية. ممارسة التعذيب بكافة أشكاله، ومن قبل أي أحد، جريمة يعاقب عليها القانون.»', 'دستور 2011، الفصل 22', true),
  ('const-art-023', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «لا يجوز إلقاء القبض على أي شخص أو اعتقاله أو متابعته أو إدانته، إلا في الحالات وطبقا للإجراءات التي ينص عليها القانون»؟', '["الفصل 22", "الفصل 23", "الفصل 24", "الفصل 25"]'::jsonb, 1, 'الفصل 23 من دستور 2011 ينص على: «لا يجوز إلقاء القبض على أي شخص أو اعتقاله أو متابعته أو إدانته، إلا في الحالات وطبقا للإجراءات التي ينص عليها القانون. الاعتقال التعسفي أو السري والاختفاء القسري، من أخطر الجرائم، وتعرض مقترفيها لأقسى العقوبات. يجب إخبار كل شخص تم اعتقاله، على الفور وبكيفية يفهمها، بدواعي اعتقاله وبحقوقه، ومن بينها حقه في التزام الصمت. ويحق له الاستفادة، في أقرب وقت ممكن، من مساعدة قانونية، ومن إمكانية الاتصال بأقربائه، طبقا للقانون. قرينة البراءة والحق في محاكمة عادلة مضمونان. يتمتع كل شخص معتقل بحقوق أساسية، وبظروف اعتقال إنسانية. ويمكنه أن يستفيد من برامج للتكوين وإعادة الإدماج. يُحظَر كل تحريض على العنصرية أو الكراهية أو العنف. يُعاقب القانون على جريمة الإبادة وغيرها من الجرائم ضد الإنسانية، وجرائم الحرب، وكافة الانتهاكات الجسيمة والممنهجة لحقوق الإنسان.»', 'دستور 2011، الفصل 23', true),
  ('const-art-024', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «لكل شخص الحق في حماية حياته الخاصة. لا تنتهك حرمة المنزل. ولا يمكن القيام بأي تفتيش إلا وفق الشروط والإجراءات التي ينص عليها القانون. لا تنتهك سرية الاتصالات الشخصية، كيفما كان شكلها. ولا يمكن الترخيص بالاطلاع على مضمونها أو نشرها، كلا أو بعضا، أو باستعمالها»؟', '["الفصل 23", "الفصل 24", "الفصل 25", "الفصل 26"]'::jsonb, 1, 'الفصل 24 من دستور 2011 ينص على: «لكل شخص الحق في حماية حياته الخاصة. لا تنتهك حرمة المنزل. ولا يمكن القيام بأي تفتيش إلا وفق الشروط والإجراءات التي ينص عليها القانون. لا تنتهك سرية الاتصالات الشخصية، كيفما كان شكلها. ولا يمكن الترخيص بالاطلاع على مضمونها أو نشرها، كلا أو بعضا، أو باستعمالها ضد أي كان، إلا بأمر قضائي، ووفق الشروط والكيفيات التي ينص عليها القانون. حرية التنقل عبر التراب الوطني والاستقرار فيه، والخروج منه، والعودة إليه، مضمونة للجميع وفق القانون.»', 'دستور 2011، الفصل 24', true),
  ('const-art-025', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «حرية الفكر والرأي والتعبير مكفولة بكل أشكالها»؟', '["الفصل 24", "الفصل 25", "الفصل 26", "الفصل 27"]'::jsonb, 1, 'الفصل 25 من دستور 2011 ينص على: «حرية الفكر والرأي والتعبير مكفولة بكل أشكالها. حرية الإبداع والنشر والعرض في مجالات الأدب والفن والبحث العلمي والتقني مضمونة.»', 'دستور 2011، الفصل 25', true),
  ('const-art-026', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تدعم السلطات العمومية بالوسائل الملائمة، تنمية الإبداع الثقافي والفني، والبحث العلمي والتقني والنهوض بالرياضة»؟', '["الفصل 25", "الفصل 26", "الفصل 27", "الفصل 28"]'::jsonb, 1, 'الفصل 26 من دستور 2011 ينص على: «تدعم السلطات العمومية بالوسائل الملائمة، تنمية الإبداع الثقافي والفني، والبحث العلمي والتقني والنهوض بالرياضة. كما تسعى لتطوير تلك المجالات وتنظيمها، بكيفية مستقلة، وعلى أسس ديمقراطية ومهنية مضبوطة.»', 'دستور 2011، الفصل 26', true),
  ('const-art-027', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «للمواطنات والمواطنين حق الحصول على المعلومات، الموجودة في حوزة الإدارة العمومية، والمؤسسات المنتخبة، والهيئات المكلفة بمهام المرفق العام»؟', '["الفصل 26", "الفصل 27", "الفصل 28", "الفصل 29"]'::jsonb, 1, 'الفصل 27 من دستور 2011 ينص على: «للمواطنات والمواطنين حق الحصول على المعلومات، الموجودة في حوزة الإدارة العمومية، والمؤسسات المنتخبة، والهيئات المكلفة بمهام المرفق العام. لا يمكن تقييد الحق في المعلومة إلا بمقتضى القانون، بهدف حماية كل ما يتعلق بالدفاع الوطني، وحماية أمن الدولة الداخلي والخارجي، والحياة الخاصة للأفراد، وكذا الوقاية من المس بالحريات والحقوق الأساسية المنصوص عليها في هذا الدستور، وحماية مصادر المعلومات والمجالات التي يحددها القانون بدقة.»', 'دستور 2011، الفصل 27', true),
  ('const-art-028', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «حرية الصحافة مضمونة، ولا يمكن تقييدها بأي شكل من أشكال الرقابة القبلية»؟', '["الفصل 27", "الفصل 28", "الفصل 29", "الفصل 30"]'::jsonb, 1, 'الفصل 28 من دستور 2011 ينص على: «حرية الصحافة مضمونة، ولا يمكن تقييدها بأي شكل من أشكال الرقابة القبلية. للجميع الحق في التعبير، ونشر الأخبار والأفكار والآراء، بكل حرية، ومن غير قيد، عدا ما ينص عليه القانون صراحة. تشجع السلطات العمومية على تنظيم قطاع الصحافة، بكيفية مستقلة، وعلى أسس ديمقراطية، وعلى وضع القواعد القانونية والأخلاقية المتعلقة به. يحدد القانون قواعد تنظيم وسائل الإعلام العمومية ومراقبتها. ويضمن الاستفادة من هذه الوسائل، مع احترام التعددية اللغوية والثقافية والسياسية للمجتمع المغربي. وتسهر الهيئة العليا للاتصال السمعي البصري على احترام هذه التعددية، وفق أحكام الفصل 165 من هذا الدستور.»', 'دستور 2011، الفصل 28', true),
  ('const-art-029', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «حريات الاجتماع والتجمهر والتظاهر السلمي، وتأسيس الجمعيات، والانتماء النقابي والسياسي مضمونة»؟', '["الفصل 28", "الفصل 29", "الفصل 30", "الفصل 31"]'::jsonb, 1, 'الفصل 29 من دستور 2011 ينص على: «حريات الاجتماع والتجمهر والتظاهر السلمي، وتأسيس الجمعيات، والانتماء النقابي والسياسي مضمونة. ويحدد القانون شروط ممارسة هذه الحريات. حق الإضراب مضمون. ويحدد قانون تنظيمي شروط وكيفيات ممارسته.»', 'دستور 2011، الفصل 29', true),
  ('const-art-030', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «لكل مواطنة ومواطن، الحق في التصويت، وفي الترشح للانتخابات، شرط بلوغ سن الرشد القانونية، والتمتع بالحقوق المدنية والسياسية»؟', '["الفصل 29", "الفصل 30", "الفصل 31", "الفصل 32"]'::jsonb, 1, 'الفصل 30 من دستور 2011 ينص على: «لكل مواطنة ومواطن، الحق في التصويت، وفي الترشح للانتخابات، شرط بلوغ سن الرشد القانونية، والتمتع بالحقوق المدنية والسياسية. وينص القانون على مقتضيات من شأنها تشجيع تكافؤ الفرص بين النساء والرجال في ولوج الوظائف الانتخابية. التصويت حق شخصي وواجب وطني. يتمتع الأجانب بالحريات الأساسية المعترف بها للمواطنات والمواطنين المغاربة، وفق القانون. ويمكن للأجانب المقيمين بالمغرب المشاركة في الانتخابات المحلية، بمقتضى القانون أو تطبيقا لاتفاقيات دولية أو ممارسات المعاملة بالمثل. يحدد القانون شروط تسليم الأشخاص المتابعين أو المدانين لدول أجنبية، وكذا شروط منح حق اللجوء.»', 'دستور 2011، الفصل 30', true),
  ('const-art-031', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تعمل الدولة والمؤسسات العمومية والجماعات الترابية، على تعبئة كل الوسائل المتاحة، لتيسير أسباب استفادة المواطنات والمواطنين، على قدم المساواة، من الحق في: العلاج والعناية الصحية؛ الحماية الاجتماعية والتغطية الصحية، والتضامن التعاضدي أو المنظم من لدن الدولة»؟', '["الفصل 30", "الفصل 31", "الفصل 32", "الفصل 33"]'::jsonb, 1, 'الفصل 31 من دستور 2011 ينص على: «تعمل الدولة والمؤسسات العمومية والجماعات الترابية، على تعبئة كل الوسائل المتاحة، لتيسير أسباب استفادة المواطنات والمواطنين، على قدم المساواة، من الحق في: العلاج والعناية الصحية؛ الحماية الاجتماعية والتغطية الصحية، والتضامن التعاضدي أو المنظم من لدن الدولة؛ الحصول على تعليم عصري ميسر الولوج وذي جودة؛ التنشئة على التشبث بالهوية المغربية، والثوابت الوطنية الراسخة؛ التكوين المهني والاستفادة من التربية البدنية والفنية؛ السكن اللائق؛ الشغل والدعم من طرف السلطات العمومية في البحث عن منصب شغل، أو في التشغيل الذاتي؛ ولوج الوظائف العمومية حسب الاستحقاق؛ الحصول على الماء والعيش في بيئة سليمة؛ التنمية المستدامة.»', 'دستور 2011، الفصل 31', true),
  ('const-art-032', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «الأسرة القائمة على علاقة الزواج الشرعي هي الخلية الأساسية للمجتمع»؟', '["الفصل 31", "الفصل 32", "الفصل 33", "الفصل 34"]'::jsonb, 1, 'الفصل 32 من دستور 2011 ينص على: «الأسرة القائمة على علاقة الزواج الشرعي هي الخلية الأساسية للمجتمع. تعمل الدولة على ضمان الحماية الحقوقية والاجتماعية والاقتصادية للأسرة، بمقتضى القانون، بما يضمن وحدتها واستقرارها والمحافظة عليها. تسعى الدولة لتوفير الحماية القانونية، والاعتبار الاجتماعي والمعنوي لجميع الأطفال، بكيفية متساوية، بصرف النظر عن وضعيتهم العائلية. التعليم الأساسي حق للطفل وواجب على الأسرة والدولة. يحدث مجلس استشاري للأسرة والطفولة.»', 'دستور 2011، الفصل 32', true),
  ('const-art-033', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «على السلطات العمومية اتخاذ التدابير الملائمة لتحقيق ما يلي: توسيع وتعميم مشاركة الشباب في التنمية الاجتماعية والاقتصادية والثقافية والسياسية للبلاد؛ مساعدة الشباب على الاندماج في الحياة النشيطة والجمعوية، وتقديم المساعدة لأولئك الذين تعترضهم صعوبة في التكيف»؟', '["الفصل 32", "الفصل 33", "الفصل 34", "الفصل 35"]'::jsonb, 1, 'الفصل 33 من دستور 2011 ينص على: «على السلطات العمومية اتخاذ التدابير الملائمة لتحقيق ما يلي: توسيع وتعميم مشاركة الشباب في التنمية الاجتماعية والاقتصادية والثقافية والسياسية للبلاد؛ مساعدة الشباب على الاندماج في الحياة النشيطة والجمعوية، وتقديم المساعدة لأولئك الذين تعترضهم صعوبة في التكيف المدرسي أو الاجتماعي أو المهني؛ تيسير ولوج الشباب للثقافة والعلم والتكنولوجيا، والفن والرياضة والأنشطة الترفيهية، مع توفير الظروف المواتية لتفتق طاقاتهم الخلاقة والإبداعية في كل هذه المجالات. يُحدث مجلس استشاري للشباب والعمل الجمعوي، من أجل تحقيق هذه الأهداف.»', 'دستور 2011، الفصل 33', true),
  ('const-art-034', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تقوم السلطات العمومية بوضع وتفعيل سياسات موجهة إلى الأشخاص والفئات من ذوي الاحتياجات الخاصة»؟', '["الفصل 33", "الفصل 34", "الفصل 35", "الفصل 36"]'::jsonb, 1, 'الفصل 34 من دستور 2011 ينص على: «تقوم السلطات العمومية بوضع وتفعيل سياسات موجهة إلى الأشخاص والفئات من ذوي الاحتياجات الخاصة. ولهذا الغرض، تسهر خصوصا على ما يلي: معالجة الأوضاع الهشة لفئات من النساء والأمهات، وللأطفال والأشخاص المسنين والوقاية منها؛ إعادة تأهيل الأشخاص الذين يعانون من إعاقة جسدية، أو حسية حركية، أو عقلية، وإدماجهم في الحياة الاجتماعية والمدنية، وتيسير تمتعهم بالحقوق والحريات المعترف بها للجميع.»', 'دستور 2011، الفصل 34', true),
  ('const-art-035', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يضمن القانون حق الملكية. ويمكن الحد من نطاقها وممارستها بموجب القانون، إذا اقتضت ذلك متطلبات التنمية الاقتصادية والاجتماعية للبلاد. ولا يمكن نزع الملكية إلا في الحالات ووفق الإجراءات التي ينص عليها القانون. تضمن الدولة حرية المبادرة والمقاولة، والتنافس الحر»؟', '["الفصل 34", "الفصل 35", "الفصل 36", "الفصل 37"]'::jsonb, 1, 'الفصل 35 من دستور 2011 ينص على: «يضمن القانون حق الملكية. ويمكن الحد من نطاقها وممارستها بموجب القانون، إذا اقتضت ذلك متطلبات التنمية الاقتصادية والاجتماعية للبلاد. ولا يمكن نزع الملكية إلا في الحالات ووفق الإجراءات التي ينص عليها القانون. تضمن الدولة حرية المبادرة والمقاولة، والتنافس الحر. كما تعمل على تحقيق تنمية بشرية مستدامة، من شأنها تعزيز العدالة الاجتماعية، والحفاظ على الثروات الطبيعية الوطنية، وعلى حقوق الأجيال القادمة. تسهر الدولة على ضمان تكافؤ الفرص للجميع، والرعاية الخاصة للفئات الاجتماعية الأقل حظا.»', 'دستور 2011، الفصل 35', true),
  ('const-art-036', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يعاقب القانون على المخالفات المتعلقة بحالات تنازع المصالح، وعلى استغلال التسريبات المخلة بالتنافس النزيه، وكل مخالفة ذات طابع مالي»؟', '["الفصل 35", "الفصل 36", "الفصل 37", "الفصل 38"]'::jsonb, 1, 'الفصل 36 من دستور 2011 ينص على: «يعاقب القانون على المخالفات المتعلقة بحالات تنازع المصالح، وعلى استغلال التسريبات المخلة بالتنافس النزيه، وكل مخالفة ذات طابع مالي. على السلطات العمومية الوقاية، طبقا للقانون، من كل أشكال الانحراف المرتبطة بنشاط الإدارات والهيئات العمومية، وباستعمال الأموال الموجودة تحت تصرفها، وبإبرام الصفقات العمومية وتدبيرها، والزجر عن هذه الانحرافات. يعاقب القانون على الشطط في استغلال مواقع النفوذ والامتياز، ووضعيات الاحتكار والهيمنة، وباقي الممارسات المخالفة لمبادئ المنافسة الحرة والمشروعة في العلاقات الاقتصادية. تحدث هيئة وطنية للنزاهة والوقاية من الرشوة ومحاربتها.»', 'دستور 2011، الفصل 36', true),
  ('const-art-037', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «على جميع المواطنات والمواطنين احترام الدستور والتقيد بالقانون»؟', '["الفصل 36", "الفصل 37", "الفصل 38", "الفصل 39"]'::jsonb, 1, 'الفصل 37 من دستور 2011 ينص على: «على جميع المواطنات والمواطنين احترام الدستور والتقيد بالقانون. ويتعين عليهم ممارسة الحقوق والحريات التي يكفلها الدستور بروح المسؤولية والمواطنة الملتزمة، التي تتلازم فيها ممارسة الحقوق بالنهوض بأداء الواجبات.»', 'دستور 2011، الفصل 37', true),
  ('const-art-038', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يُساهم كل المواطنات والمواطنين في الدفاع عن الوطن ووحدته الترابية تجاه أي عدوان أو تهديد»؟', '["الفصل 37", "الفصل 38", "الفصل 39", "الفصل 40"]'::jsonb, 1, 'الفصل 38 من دستور 2011 ينص على: «يُساهم كل المواطنات والمواطنين في الدفاع عن الوطن ووحدته الترابية تجاه أي عدوان أو تهديد.»', 'دستور 2011، الفصل 38', true),
  ('const-art-039', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «على الجميع أن يتحمل، كل على قدر استطاعته، التكاليف العمومية، التي للقانون وحده إحداثها وتوزيعها، وفق الإجراءات المنصوص عليها في هذا الدستور»؟', '["الفصل 38", "الفصل 39", "الفصل 40", "الفصل 41"]'::jsonb, 1, 'الفصل 39 من دستور 2011 ينص على: «على الجميع أن يتحمل، كل على قدر استطاعته، التكاليف العمومية، التي للقانون وحده إحداثها وتوزيعها، وفق الإجراءات المنصوص عليها في هذا الدستور.»', 'دستور 2011، الفصل 39', true),
  ('const-art-040', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «على الجميع أن يتحمل، بصفة تضامنية، وبشكل يتناسب مع الوسائل التي يتوفرون عليها، التكاليف التي تتطلبها تنمية البلاد، وكذا تلك الناتجة عن الأعباء الناجمة عن الآفات والكوارث الطبيعية التي تصيب البلاد»؟', '["الفصل 39", "الفصل 40", "الفصل 41", "الفصل 42"]'::jsonb, 1, 'الفصل 40 من دستور 2011 ينص على: «على الجميع أن يتحمل، بصفة تضامنية، وبشكل يتناسب مع الوسائل التي يتوفرون عليها، التكاليف التي تتطلبها تنمية البلاد، وكذا تلك الناتجة عن الأعباء الناجمة عن الآفات والكوارث الطبيعية التي تصيب البلاد. الباب الثالث: الملكية»', 'دستور 2011، الفصل 40', true),
  ('const-art-041', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «الملك، أمير المؤمنين وحامي حمى الملة والدين، والضامن لحرية ممارسة الشؤون الدينية»؟', '["الفصل 40", "الفصل 41", "الفصل 42", "الفصل 43"]'::jsonb, 1, 'الفصل 41 من دستور 2011 ينص على: «الملك، أمير المؤمنين وحامي حمى الملة والدين، والضامن لحرية ممارسة الشؤون الدينية. يرأس الملك، أمير المؤمنين، المجلس العلمي الأعلى، الذي يتولى دراسة القضايا التي يعرضها عليه. ويعتبر المجلس الجهة الوحيدة المؤهلة لإصدار الفتاوى التي تعتمد رسميا، في شأن المسائل المحالة إليه، استنادا إلى مبادئ وأحكام الدين الإسلامي الحنيف، ومقاصده السمحة. تحدد اختصاصات المجلس وتأليفه وكيفيات سيره بظهير. يمارس الملك الصلاحيات الدينية المتعلقة بإمارة المؤمنين، والمخولة له حصريا، بمقتضى هذا الفصل، بواسطة ظهائر.»', 'دستور 2011، الفصل 41', true),
  ('const-art-042', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «الملك رئيس الدولة، وممثلها الأسمى، ورمز وحدة الأمة، وضامن دوام الدولة واستمرارها، والحكم الأسمى بين مؤسساتها، يسهر على احترام الدستور، وحسن سير المؤسسات الدستورية، وعلى صيانة الاختيار الديمقراطي، وحقوق وحريات المواطنات والمواطنين والجماعات، وعلى احترام»؟', '["الفصل 41", "الفصل 42", "الفصل 43", "الفصل 44"]'::jsonb, 1, 'الفصل 42 من دستور 2011 ينص على: «الملك رئيس الدولة، وممثلها الأسمى، ورمز وحدة الأمة، وضامن دوام الدولة واستمرارها، والحكم الأسمى بين مؤسساتها، يسهر على احترام الدستور، وحسن سير المؤسسات الدستورية، وعلى صيانة الاختيار الديمقراطي، وحقوق وحريات المواطنات والمواطنين والجماعات، وعلى احترام التعهدات الدولية للمملكة. الملك هو ضامن استقلال البلاد وحوزة المملكة في دائرة حدودها الحقة. يمارس الملك هذه المهام، بمقتضى ظهائر، من خلال السلطات المخولة له صراحة بنص الدستور. توقع الظهائر بالعطف من قبل رئيس الحكومة، ماعدا تلك المنصوص عليها في الفصول 41 و44 (الفقرة الثانية) و47 (الفقرتان الأولى والسادسة) و51 و57 و59 و130 (الفقرتان الأولى والرابعة) و174.»', 'دستور 2011، الفصل 42', true),
  ('const-art-043', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «إن عرش المغرب وحقوقه الدستورية تنتقل بالوراثة إلى الولد الذكر الأكبر سنا من ذرية جلالة الملك محمد السادس، ثم إلى ابنه الأكبر سنا وهكذا ما تعاقبوا، ما عدا إذا عين الملك قيد حياته خلفا له ولدا آخر من أبنائه غير الولد الأكبر سنا، فإن لم يكن ولد ذكر من ذرية»؟', '["الفصل 42", "الفصل 43", "الفصل 44", "الفصل 45"]'::jsonb, 1, 'الفصل 43 من دستور 2011 ينص على: «إن عرش المغرب وحقوقه الدستورية تنتقل بالوراثة إلى الولد الذكر الأكبر سنا من ذرية جلالة الملك محمد السادس، ثم إلى ابنه الأكبر سنا وهكذا ما تعاقبوا، ما عدا إذا عين الملك قيد حياته خلفا له ولدا آخر من أبنائه غير الولد الأكبر سنا، فإن لم يكن ولد ذكر من ذرية الملك، فالمُلك ينتقل إلى أقرب أقربائه من جهة الذكور، ثم إلى ابنه طبق الترتيب والشروط السابقة الذكر.»', 'دستور 2011، الفصل 43', true),
  ('const-art-044', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يعتبر الملك غير بالغ سن الرشد قبل نهاية السنة الثامنة عشرة من عمره»؟', '["الفصل 43", "الفصل 44", "الفصل 45", "الفصل 46"]'::jsonb, 1, 'الفصل 44 من دستور 2011 ينص على: «يعتبر الملك غير بالغ سن الرشد قبل نهاية السنة الثامنة عشرة من عمره. وإلى أن يبلغ سن الرشد، يمارس مجلس الوصاية اختصاصات العرش وحقوقه الدستورية، باستثناء ما يتعلق منها بمراجعة الدستور. ويعمل مجلس الوصاية كهيئة استشارية بجانب الملك حتى يدرك تمام السنة العشرين من عمره. يرأس مجلس الوصاية رئيس المحكمة الدستورية، ويتركب، بالإضافة إلى رئيسه، من رئيس الحكومة، ورئيس مجلس النواب، ورئيس مجلس المستشارين، والرئيس المنتدب للمجلس الأعلى للسلطة القضائية، والأمين العام للمجلس العلمي الأعلى، وعشر شخصيات يعينهم الملك بمحض اختياره. قواعد سير مجلس الوصاية تحدد بقانون تنظيمي.»', 'دستور 2011، الفصل 44', true),
  ('const-art-045', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «للملك قائمة مدنية»؟', '["الفصل 44", "الفصل 45", "الفصل 46", "الفصل 47"]'::jsonb, 1, 'الفصل 45 من دستور 2011 ينص على: «للملك قائمة مدنية.»', 'دستور 2011، الفصل 45', true),
  ('const-art-046', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «شخص الملك لا تنتهك حرمته، وللملك واجب التوقير والاحترام»؟', '["الفصل 45", "الفصل 46", "الفصل 47", "الفصل 48"]'::jsonb, 1, 'الفصل 46 من دستور 2011 ينص على: «شخص الملك لا تنتهك حرمته، وللملك واجب التوقير والاحترام.»', 'دستور 2011، الفصل 46', true),
  ('const-art-047', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يعين الملك رئيس الحكومة من الحزب السياسي الذي تصدر انتخابات أعضاء مجلس النواب، وعلى أساس نتائجها»؟', '["الفصل 46", "الفصل 47", "الفصل 48", "الفصل 49"]'::jsonb, 1, 'الفصل 47 من دستور 2011 ينص على: «يعين الملك رئيس الحكومة من الحزب السياسي الذي تصدر انتخابات أعضاء مجلس النواب، وعلى أساس نتائجها. ويعين أعضاء الحكومة باقتراح من رئيسها. للملك، بمبادرة منه، بعد استشارة رئيس الحكومة، أن يعفي عضوا أو أكثر من أعضاء الحكومة من مهامهم. ولرئيس الحكومة أن يطلب من الملك إعفاء عضو أو أكثر، من أعضاء الحكومة. ولرئيس الحكومة أن يطلب من الملك إعفاء عضو أو أكثر، من أعضاء الحكومة، بناء على استقالتهم الفردية أو الجماعية. يترتب عن استقالة رئيس الحكومة إعفاء الحكومة بكاملها من لدن الملك. تواصل الحكومة المنتهية مهامها تصريف الأمور الجارية إلى غاية تشكيل الحكومة الجديدة.»', 'دستور 2011، الفصل 47', true),
  ('const-art-048', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يرأس الملك المجلس الوزاري، الذي يتألف من رئيس الحكومة والوزراء»؟', '["الفصل 47", "الفصل 48", "الفصل 49", "الفصل 50"]'::jsonb, 1, 'الفصل 48 من دستور 2011 ينص على: «يرأس الملك المجلس الوزاري، الذي يتألف من رئيس الحكومة والوزراء. ينعقد المجلس الوزاري بمبادرة من الملك، أو بطلب من رئيس الحكومة. للملك أن يفوض لرئيس الحكومة، بناء على جدول أعمال محدد، رئاسة مجلس وزاري.»', 'دستور 2011، الفصل 48', true),
  ('const-art-049', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يتداول المجلس الوزاري في القضايا والنصوص التالية: التوجهات الاستراتيجية لسياسة الدولة؛ مشاريع مراجعة الدستور؛ مشاريع القوانين التنظيمية؛ التوجهات العامة لمشروع قانون المالية؛ مشاريع القوانين - الإطار المشار إليها في الفصل 71 (الفقرة الثانية) من هذا الدستور»؟', '["الفصل 48", "الفصل 49", "الفصل 50", "الفصل 51"]'::jsonb, 1, 'الفصل 49 من دستور 2011 ينص على: «يتداول المجلس الوزاري في القضايا والنصوص التالية: التوجهات الاستراتيجية لسياسة الدولة؛ مشاريع مراجعة الدستور؛ مشاريع القوانين التنظيمية؛ التوجهات العامة لمشروع قانون المالية؛ مشاريع القوانين - الإطار المشار إليها في الفصل 71 (الفقرة الثانية) من هذا الدستور؛ مشروع قانون العفو العام؛ مشاريع النصوص المتعلقة بالمجال العسكري؛ إعلان حالة الحصار؛ إشهار الحرب؛ مشروع المرسوم المشار إليه في الفصل 104 من هذا الدستور؛ التعيين باقتراح من رئيس الحكومة، وبمبادرة من الوزير المعني، في الوظائف المدنية التالية: والي بنك المغرب، والسفراء والولاة والعمال، والمسؤولين عن الإدارات المكلفة بالأمن الداخلي، والمسؤولين عن المؤسسات والمقاولات العمومية الاستراتيجية. وتحدد بقانون تنظيمي لائحة هذه المؤسسات والمقاولات الاستراتيجية.»', 'دستور 2011، الفصل 49', true),
  ('const-art-050', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يصدر الملك الأمر بتنفيذ القانون خلال الثلاثين يوما التالية لإحالته إلى الحكومة بعد تمام الموافقة عليه»؟', '["الفصل 49", "الفصل 50", "الفصل 51", "الفصل 52"]'::jsonb, 1, 'الفصل 50 من دستور 2011 ينص على: «يصدر الملك الأمر بتنفيذ القانون خلال الثلاثين يوما التالية لإحالته إلى الحكومة بعد تمام الموافقة عليه. ينشر القانون الذي صدر الأمر بتنفيذه، بالجريدة الرسمية للمملكة، خلال أجل أقصاه شهر ابتداء من تاريخ ظهير إصداره.»', 'دستور 2011، الفصل 50', true),
  ('const-art-051', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «للملك حق حل مجلسي البرلمان أو أحدهما بظهير، طبق الشروط المبينة في الفصول 96 و97 و98»؟', '["الفصل 50", "الفصل 51", "الفصل 52", "الفصل 53"]'::jsonb, 1, 'الفصل 51 من دستور 2011 ينص على: «للملك حق حل مجلسي البرلمان أو أحدهما بظهير، طبق الشروط المبينة في الفصول 96 و97 و98.»', 'دستور 2011، الفصل 51', true),
  ('const-art-052', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «للملك أن يخاطب الأمة والبرلمان، ويتلى خطابه أمام كلا المجلسين، ولا يمكن أن يكون مضمونه موضوع أي نقاش داخلهما»؟', '["الفصل 51", "الفصل 52", "الفصل 53", "الفصل 54"]'::jsonb, 1, 'الفصل 52 من دستور 2011 ينص على: «للملك أن يخاطب الأمة والبرلمان، ويتلى خطابه أمام كلا المجلسين، ولا يمكن أن يكون مضمونه موضوع أي نقاش داخلهما.»', 'دستور 2011، الفصل 52', true),
  ('const-art-053', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «الملك هو القائد الأعلى للقوات المسلحة الملكية»؟', '["الفصل 52", "الفصل 53", "الفصل 54", "الفصل 55"]'::jsonb, 1, 'الفصل 53 من دستور 2011 ينص على: «الملك هو القائد الأعلى للقوات المسلحة الملكية. وله حق التعيين في الوظائف العسكرية، كما له أن يفوض لغيره ممارسة هذا الحق.»', 'دستور 2011، الفصل 53', true),
  ('const-art-054', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يُحدث مجلس أعلى للأمن، بصفته هيئة للتشاور بشأن استراتيجيات الأمن الداخلي والخارجي للبلاد، وتدبير حالات الأزمات، والسهر أيضا على مأسسة ضوابط الحكامة الأمنية الجيدة»؟', '["الفصل 53", "الفصل 54", "الفصل 55", "الفصل 56"]'::jsonb, 1, 'الفصل 54 من دستور 2011 ينص على: «يُحدث مجلس أعلى للأمن، بصفته هيئة للتشاور بشأن استراتيجيات الأمن الداخلي والخارجي للبلاد، وتدبير حالات الأزمات، والسهر أيضا على مأسسة ضوابط الحكامة الأمنية الجيدة. يرأس الملك هذا المجلس، وله أن يفوض لرئيس الحكومة صلاحية رئاسة اجتماع لهذا المجلس، على أساس جدول أعمال محدد. يضم المجلس الأعلى للأمن في تركيبته، علاوة على رئيس الحكومة، ورئيس مجلس النواب، ورئيس مجلس المستشارين، والرئيس المنتدب للمجلس الأعلى للسلطة القضائية، الوزراء المكلفين بالداخلية، والشؤون الخارجية، والعدل، وإدارة الدفاع الوطني، وكذا المسؤولين عن الإدارات الأمنية، وضباط سامين بالقوات المسلحة الملكية، وكل شخصية أخرى يُعتبر حضورها مفيدا لأشغال المجلس. ويحدد نظام داخلي للمجلس قواعد تنظيمه وتسييره.»', 'دستور 2011، الفصل 54', true),
  ('const-art-055', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يعتمد الملك السفراء لدى الدول الأجنبية والمنظمات الدولية، ولديه يُعتمد السفراء وممثلو المنظمات الدولية»؟', '["الفصل 54", "الفصل 55", "الفصل 56", "الفصل 57"]'::jsonb, 1, 'الفصل 55 من دستور 2011 ينص على: «يعتمد الملك السفراء لدى الدول الأجنبية والمنظمات الدولية، ولديه يُعتمد السفراء وممثلو المنظمات الدولية. يوقع الملك على المعاهدات ويصادق عليها، غير أنه لا يصادق على معاهدات السلم أو الاتحاد، أو التي تهم رسم الحدود، ومعاهدات التجارة، أو تلك التي يترتب عليها تكاليف تلزم مالية الدولة، أو يستلزم تطبيقها اتخاذ تدابير تشريعية، أو تتعلق بحقوق وحريات المواطنات والمواطنين، العامة أو الخاصة، إلا بعد الموافقة عليها بقانون. للملك أن يعرض على البرلمان كل معاهدة أو اتفاقية أخرى قبل المصادقة عليها. إذا صرحت المحكمة الدستورية، إثر إحالة الملك، أو رئيس الحكومة، أو رئيس مجلس النواب، أو رئيس مجلس المستشارين، أو سدس أعضاء المجلس الأول، أو ربع أعضاء المجلس الثاني، الأمر إليها، أن التزاما دوليا يتضمن بندا يخالف الدستور، فإن المصادقة على هذا الالتزام لا تقع إلا بعد مراجعة الدستور.»', 'دستور 2011، الفصل 55', true),
  ('const-art-056', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يرأس الملك المجلس الأعلى للسلطة القضائية»؟', '["الفصل 55", "الفصل 56", "الفصل 57", "الفصل 58"]'::jsonb, 1, 'الفصل 56 من دستور 2011 ينص على: «يرأس الملك المجلس الأعلى للسلطة القضائية.»', 'دستور 2011، الفصل 56', true),
  ('const-art-057', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يوافق الملك بظهير على تعيين القضاة من قبل المجلس الأعلى للسلطة القضائية»؟', '["الفصل 56", "الفصل 57", "الفصل 58", "الفصل 59"]'::jsonb, 1, 'الفصل 57 من دستور 2011 ينص على: «يوافق الملك بظهير على تعيين القضاة من قبل المجلس الأعلى للسلطة القضائية.»', 'دستور 2011، الفصل 57', true),
  ('const-art-058', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يمارس الملك حق العفو»؟', '["الفصل 57", "الفصل 58", "الفصل 59", "الفصل 60"]'::jsonb, 1, 'الفصل 58 من دستور 2011 ينص على: «يمارس الملك حق العفو.»', 'دستور 2011، الفصل 58', true),
  ('const-art-059', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «إذا كانت حوزة التراب الوطني مهددة، أو وقع من الأحداث ما يعرقل السير العادي للمؤسسات الدستورية، أمكن للملك أن يُعلن حالة الاستثناء بظهير، بعد استشارة كل من رئيس الحكومة، ورئيس مجلس النواب، ورئيس مجلس المستشارين، ورئيس المحكمة الدستورية، وتوجيه خطاب إلى الأمة»؟', '["الفصل 58", "الفصل 59", "الفصل 60", "الفصل 61"]'::jsonb, 1, 'الفصل 59 من دستور 2011 ينص على: «إذا كانت حوزة التراب الوطني مهددة، أو وقع من الأحداث ما يعرقل السير العادي للمؤسسات الدستورية، أمكن للملك أن يُعلن حالة الاستثناء بظهير، بعد استشارة كل من رئيس الحكومة، ورئيس مجلس النواب، ورئيس مجلس المستشارين، ورئيس المحكمة الدستورية، وتوجيه خطاب إلى الأمة. ويُخول الملك بذلك صلاحية اتخاذ الإجراءات التي يفرضها الدفاع عن الوحدة الترابية، ويقتضيها الرجوع، في أقرب الآجال، إلى السير العادي للمؤسسات الدستورية. لا يحل البرلمان أثناء ممارسة السلطات الاستثنائية. تبقى الحريات والحقوق الأساسية المنصوص عليها في هذا الدستور مضمونة. تُرفع حالة الاستثناء بمجرد انتفاء الأسباب التي دعت إليها، وباتخاذ الإجراءات الشكلية المقررة لإعلانها. الباب الرابع: السلطة التشريعية تنظيم البرلمان»', 'دستور 2011، الفصل 59', true),
  ('const-art-060', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يتكون البرلمان من مجلسين، مجلس النواب ومجلس المستشارين؛ ويستمد أعضاؤه نيابتهم من الأمة، وحقهم في التصويت حق شخصي لا يمكن تفويضه»؟', '["الفصل 59", "الفصل 60", "الفصل 61", "الفصل 62"]'::jsonb, 1, 'الفصل 60 من دستور 2011 ينص على: «يتكون البرلمان من مجلسين، مجلس النواب ومجلس المستشارين؛ ويستمد أعضاؤه نيابتهم من الأمة، وحقهم في التصويت حق شخصي لا يمكن تفويضه. المعارضة مكون أساسي في المجلسين، وتشارك في وظيفتي التشريع والمراقبة، طبقا لما هو منصوص عليه خاصة في هذا الباب.»', 'دستور 2011، الفصل 60', true),
  ('const-art-061', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يجرد من صفة عضو في أحد المجلسين، كل من تخلى عن انتمائه السياسي الذي ترشح باسمه للانتخابات، أو عن الفريق أو المجموعة البرلمانية التي ينتمي إليها»؟', '["الفصل 60", "الفصل 61", "الفصل 62", "الفصل 63"]'::jsonb, 1, 'الفصل 61 من دستور 2011 ينص على: «يجرد من صفة عضو في أحد المجلسين، كل من تخلى عن انتمائه السياسي الذي ترشح باسمه للانتخابات، أو عن الفريق أو المجموعة البرلمانية التي ينتمي إليها. وتصرح المحكمة الدستورية بشغور المقعد، بناء على إحالة من رئيس المجلس الذي يعنيه الأمر، وذلك وفق أحكام النظام الداخلي للمجلس المعني، الذي يحدد أيضا آجال ومسطرة الإحالة على المحكمة الدستورية.»', 'دستور 2011، الفصل 61', true),
  ('const-art-062', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «ينتخب أعضاء مجلس النواب بالاقتراع العام المباشر لمدة خمس سنوات، وتنتهي عضويتهم عند افتتاح دورة أكتوبر من السنة الخامسة التي تلي انتخاب المجلس»؟', '["الفصل 61", "الفصل 62", "الفصل 63", "الفصل 64"]'::jsonb, 1, 'الفصل 62 من دستور 2011 ينص على: «ينتخب أعضاء مجلس النواب بالاقتراع العام المباشر لمدة خمس سنوات، وتنتهي عضويتهم عند افتتاح دورة أكتوبر من السنة الخامسة التي تلي انتخاب المجلس. يبين قانون تنظيمي عدد أعضاء مجلس النواب، ونظام انتخابهم، ومبادئ التقسيم الانتخابي، وشروط القابلية للانتخاب، وحالات التنافي، وقواعد الحد من الجمع بين الانتدابات، ونظام المنازعات الانتخابية. يُنتخب رئيس مجلس النواب وأعضاء المكتب، ورؤساء اللجان الدائمة ومكاتبها، في مستهل الفترة النيابية، ثم في سنتها الثالثة عند دورة أبريل لما تبقى من الفترة المذكورة. يُنتخب أعضاء المكتب على أساس التمثيل النسبي لكل فريق.»', 'دستور 2011، الفصل 62', true),
  ('const-art-063', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يتكون مجلس المستشارين من 90 عضوا على الأقل، و120 عضوا على الأكثر، ينتخبون بالاقتراع العام غير المباشر، لمدة ست سنوات، على أساس التوزيع التالي: ثلاثة أخماس الأعضاء يمثلون الجماعات الترابية، يتوزعون بين جهات المملكة بالتناسب مع عدد سكانها، ومع مراعاة الإنصاف»؟', '["الفصل 62", "الفصل 63", "الفصل 64", "الفصل 65"]'::jsonb, 1, 'الفصل 63 من دستور 2011 ينص على: «يتكون مجلس المستشارين من 90 عضوا على الأقل، و120 عضوا على الأكثر، ينتخبون بالاقتراع العام غير المباشر، لمدة ست سنوات، على أساس التوزيع التالي: ثلاثة أخماس الأعضاء يمثلون الجماعات الترابية، يتوزعون بين جهات المملكة بالتناسب مع عدد سكانها، ومع مراعاة الإنصاف بين الجهات. ينتخب المجلس الجهوي على مستوى كل جهة، من بين أعضائه، الثلث المخصص للجهة من هذا العدد. وينتخب الثلثان المتبقيان من قبل هيئة ناخبة تتكون على مستوى الجهة، من أعضاء المجالس الجماعية ومجالس العمالات والأقاليم؛ خمسان من الأعضاء تنتخبهم، في كل جهة، هيئات ناخبة تتألف من المنتخبين في الغرف المهنية، وفي المنظمات المهنية للمشغلين الأكثر تمثيلية، وأعضاء تنتخبهم على الصعيد الوطني، هيئة ناخبة مكونة من ممثلي المأجورين. ويبين قانون تنظيمي عدد أعضاء مجلس المستشارين، ونظام انتخابهم، وعدد الأعضاء الذين تنتخبهم كل هيأة ناخبة، وتوزيع المقاعد على الجهات، وشروط القابلية للانتخاب، وحالات التنافي، وقواعد الحد من الجمع بين الانتدابات، ونظام المنازعات الانتخابية. يُنتخب رئيس مجلس المستشارين وأعضاء المكتب، ورؤساء اللجان الدائمة ومكاتبها، في مستهل الفترة النيابية، ثم عند انتصاف الولاية التشريعية للمجلس. ينتخب أعضاء المكتب على أساس التمثيل النسبي لكل فريق.»', 'دستور 2011، الفصل 63', true),
  ('const-art-064', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «لا يمكن متابعة أي عضو من أعضاء البرلمان، ولا البحث عنه، ولا إلقاء القبض عليه، ولا اعتقاله، ولا محاكمته بمناسبة إبدائه لرأي أو قيامه بتصويت خلال مزاولته لمهامه، ما عدا إذا كان الرأي المعبر عنه يجادل في النظام الملكي أو الدين الإسلامي، أو يتضمن ما يخل بالاحترام»؟', '["الفصل 63", "الفصل 64", "الفصل 65", "الفصل 66"]'::jsonb, 1, 'الفصل 64 من دستور 2011 ينص على: «لا يمكن متابعة أي عضو من أعضاء البرلمان، ولا البحث عنه، ولا إلقاء القبض عليه، ولا اعتقاله، ولا محاكمته بمناسبة إبدائه لرأي أو قيامه بتصويت خلال مزاولته لمهامه، ما عدا إذا كان الرأي المعبر عنه يجادل في النظام الملكي أو الدين الإسلامي، أو يتضمن ما يخل بالاحترام الواجب للملك.»', 'دستور 2011، الفصل 64', true),
  ('const-art-065', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يعقد البرلمان جلساته أثناء دورتين في السنة، ويرأس الملك افتتاح الدورة الأولى، التي تبتدئ يوم الجمعة الثانية من شهر أكتوبر، وتُفتتح الدورة الثانية يوم الجمعة الثانية من شهر أبريل»؟', '["الفصل 64", "الفصل 65", "الفصل 66", "الفصل 67"]'::jsonb, 1, 'الفصل 65 من دستور 2011 ينص على: «يعقد البرلمان جلساته أثناء دورتين في السنة، ويرأس الملك افتتاح الدورة الأولى، التي تبتدئ يوم الجمعة الثانية من شهر أكتوبر، وتُفتتح الدورة الثانية يوم الجمعة الثانية من شهر أبريل. إذا استمرت جلسات البرلمان أربعة أشهر على الأقل في كل دورة، جاز ختم الدورة بمرسوم.»', 'دستور 2011، الفصل 65', true),
  ('const-art-066', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يمكن جمع البرلمان في دورة استثنائية، إما بمرسوم، أو بطلب من ثلث أعضاء مجلس النواب، أو بأغلبية أعضاء مجلس المستشارين»؟', '["الفصل 65", "الفصل 66", "الفصل 67", "الفصل 68"]'::jsonb, 1, 'الفصل 66 من دستور 2011 ينص على: «يمكن جمع البرلمان في دورة استثنائية، إما بمرسوم، أو بطلب من ثلث أعضاء مجلس النواب، أو بأغلبية أعضاء مجلس المستشارين. تعقد دورة البرلمان الاستثنائية على أساس جدول أعمال محدد، وعندما تتم المناقشة في القضايا التي يتضمنها جدول الأعمال، تُختم الدورة بمرسوم.»', 'دستور 2011، الفصل 66', true),
  ('const-art-067', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «للوزراء أن يحضروا جلسات كلا المجلسين واجتماعات لجانهما، ويمكنهم أن يستعينوا بمندوبين يعينونهم لهذا الغرض»؟', '["الفصل 66", "الفصل 67", "الفصل 68", "الفصل 69"]'::jsonb, 1, 'الفصل 67 من دستور 2011 ينص على: «للوزراء أن يحضروا جلسات كلا المجلسين واجتماعات لجانهما، ويمكنهم أن يستعينوا بمندوبين يعينونهم لهذا الغرض. علاوة على اللجان الدائمة المشار إليها في الفقرة السابقة، يجوز أن تشكل بمبادرة من الملك، أو بطلب من ثلث أعضاء مجلس النواب، أو ثلث أعضاء مجلس المستشارين، لجان نيابية لتقصي الحقائق، يُناط بها جمع المعلومات المتعلقة بوقائع معينة، أو بتدبير المصالح أو المؤسسات والمقاولات العمومية، وإطلاع المجلس الذي شكلها على نتائج أعمالها. ولا يجوز تكوين لجان لتقصي الحقائق في وقائع تكون موضوع متابعات قضائية، ما دامت هذه المتابعات جارية؛ وتنتهي مهمة كل لجنة لتقصي الحقائق، سبق تكوينها، فور فتح تحقيق قضائي في الوقائع التي اقتضت تشكيلها. لجان تقصي الحقائق مؤقتة بطبيعتها، وتنتهي أعمالها بإيداع تقريرها لدى مكتب المجلس المعني، وعند الاقتضاء، بإحالته إلى القضاء من قبل رئيس هذا المجلس. تخصص جلسة عمومية داخل المجلس المعني لمناقشة تقارير لجان تقصي الحقائق. يحدد قانون تنظيمي طريقة تسيير هذه اللجان.»', 'دستور 2011، الفصل 67', true),
  ('const-art-068', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «جلسات مجلسي البرلمان عمومية، وينشر محضر مناقشات الجلسات العامة برمته في الجريدة الرسمية للبرلمان»؟', '["الفصل 67", "الفصل 68", "الفصل 69", "الفصل 70"]'::jsonb, 1, 'الفصل 68 من دستور 2011 ينص على: «جلسات مجلسي البرلمان عمومية، وينشر محضر مناقشات الجلسات العامة برمته في الجريدة الرسمية للبرلمان. لكل من المجلسين أن يعقد اجتماعات سرية، بطلب من رئيس الحكومة، أو بطلب من ثلث أعضائه. جلسات لجان البرلمان سرية، ويحدد النظام الداخلي لمجلسي البرلمان الحالات والضوابط التي يمكن أن تنعقد فيها اللجان بصفة علنية. يعقد البرلمان جلسات مشتركة بمجلسيه، وعلى وجه الخصوص، في الحالات التالية: افتتاح الملك للدورة التشريعية في الجمعة الثانية من شهر أكتوبر، والاستماع إلى الخطب الملكية الموجهة للبرلمان؛ المصادقة على مراجعة الدستور وفق أحكام الفصل 174؛ الاستماع إلى التصريحات التي يقدمها رئيس الحكومة؛ عرض مشروع قانون المالية السنوي؛ الاستماع إلى خطب رؤساء الدول والحكومات الأجنبية. كما يمكن لرئيس الحكومة أن يطلب من رئيسي مجلسي النواب والمستشارين عقد اجتماعات مشتركة للبرلمان، للاستماع إلى بيانات تتعلق بقضايا تكتسي طابعا وطنيا هاما. تنعقد الاجتماعات المشتركة برئاسة رئيس مجلس النواب، ويحدد النظام الداخلي للمجلسين كيفيات وضوابط انعقادها. علاوة على الجلسات المشتركة، يمكن للجان الدائمة للبرلمان، أن تعقد اجتماعات مشتركة للاستماع إلى بيانات تتعلق بقضايا تكتسي طابعا وطنيا هاما، وذلك وفق ضوابط يحددها النظامان الداخليان للمجلسين.»', 'دستور 2011، الفصل 68', true),
  ('const-art-069', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يضع كل من المجلسين نظامه الداخلي ويقره بالتصويت، إلا أنه لا يجوز العمل به إلا بعد أن تصرح المحكمة الدستورية بمطابقته لأحكام هذا الدستور»؟', '["الفصل 68", "الفصل 69", "الفصل 70", "الفصل 71"]'::jsonb, 1, 'الفصل 69 من دستور 2011 ينص على: «يضع كل من المجلسين نظامه الداخلي ويقره بالتصويت، إلا أنه لا يجوز العمل به إلا بعد أن تصرح المحكمة الدستورية بمطابقته لأحكام هذا الدستور. يتعين على المجلسين، في وضعهما لنظاميهما الداخليين، مراعاة تناسقهما وتكاملهما، ضمانا لنجاعة العمل البرلماني. يحدد النظام الداخلي بصفة خاصة: قواعد تأليف وتسيير الفرق والمجموعات البرلمانية والانتساب إليها، والحقوق الخاصة المعترف بها لفرق المعارضة؛ واجبات الأعضاء في المشاركة الفعلية في أعمال اللجان والجلسات العامة، والجزاءات المطبقة في حالة الغياب؛ عدد اللجان الدائمة واختصاصها وتنظيمها، مع تخصيص رئاسة لجنة أو لجنتين للمعارضة، على الأقل، مع مراعاة مقتضيات الفصل 10 من هذا الدستور. سلطات البرلمان»', 'دستور 2011، الفصل 69', true),
  ('const-art-070', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يمارس البرلمان السلطة التشريعية. يصوت البرلمان على القوانين، ويراقب عمل الحكومة، ويقيم السياسات العمومية. للقانون أن يأذن للحكومة أن تتخذ في ظرف من الزمن محدود، ولغاية معينة، بمقتضى مراسيم تدابير يختص القانون عادة باتخاذها، ويجري العمل بهذه المراسيم بمجرد»؟', '["الفصل 69", "الفصل 70", "الفصل 71", "الفصل 72"]'::jsonb, 1, 'الفصل 70 من دستور 2011 ينص على: «يمارس البرلمان السلطة التشريعية. يصوت البرلمان على القوانين، ويراقب عمل الحكومة، ويقيم السياسات العمومية. للقانون أن يأذن للحكومة أن تتخذ في ظرف من الزمن محدود، ولغاية معينة، بمقتضى مراسيم تدابير يختص القانون عادة باتخاذها، ويجري العمل بهذه المراسيم بمجرد نشرها. غير أنه يجب عرضها على البرلمان بقصد المصادقة، عند انتهاء الأجل الذي حدده قانون الإذن بإصدارها، ويبطل قانون الإذن إذا ما وقع حل مجلسي البرلمان أو أحدهما.»', 'دستور 2011، الفصل 70', true),
  ('const-art-071', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يختص القانون، بالإضافة إلى المواد المسندة إليه صراحة بفصول أخرى من الدستور، بالتشريع في الميادين التالية: الحقوق والحريات الأساسية المنصوص عليها في التصدير، وفي فصول أخرى من هذا الدستور؛ نظام الأسرة والحالة المدنية؛ مبادئ وقواعد المنظومة الصحية؛ نظام الوسائط»؟', '["الفصل 70", "الفصل 71", "الفصل 72", "الفصل 73"]'::jsonb, 1, 'الفصل 71 من دستور 2011 ينص على: «يختص القانون، بالإضافة إلى المواد المسندة إليه صراحة بفصول أخرى من الدستور، بالتشريع في الميادين التالية: الحقوق والحريات الأساسية المنصوص عليها في التصدير، وفي فصول أخرى من هذا الدستور؛ نظام الأسرة والحالة المدنية؛ مبادئ وقواعد المنظومة الصحية؛ نظام الوسائط السمعية البصرية والصحافة بمختلف أشكالها؛ العفو العام؛ الجنسية ووضعية الأجانب؛ تحديد الجرائم والعقوبات الجارية عليها؛ التنظيم القضائي وإحداث أصناف جديدة من المحاكم؛ المسطرة المدنية والمسطرة الجنائية؛ نظام السجون؛ النظام الأساسي العام للوظيفة العمومية؛ الضمانات الأساسية الممنوحة للموظفين المدنيين والعسكريين؛ نظام مصالح وقوات حفظ الأمن؛ نظام الجماعات الترابية ومبادئ تحديد دوائرها الترابية؛ النظام الانتخابي للجماعات الترابية ومبادئ تقطيع الدوائر الانتخابية؛ النظام الضريبي، ووعاء الضرائب، ومقدارها وطرق تحصيلها؛ النظام القانوني لإصدار العملة ونظام البنك المركزي؛ نظام الجمارك؛ نظام الالتزامات المدنية والتجارية، وقانون الشركات والتعاونيات؛ الحقوق العينية وأنظمة الملكية العقارية العمومية والخاصة والجماعية؛ نظام النقل؛ علاقات الشغل، والضمان الاجتماعي، وحوادث الشغل، والأمراض المهنية؛ نظام الأبناك وشركات التأمين والتعاضديات؛ نظام تكنولوجيا المعلومات والاتصالات؛ التعمير وإعداد التراب؛ القواعد المتعلقة بتدبير البيئة وحماية الموارد الطبيعية والتنمية المستدامة؛ نظام المياه والغابات والصيد؛ تحديد التوجهات والتنظيم العام لميادين التعليم والبحث العلمي والتكوين المهني؛ إحداث المؤسسات العمومية وكل شخص اعتباري من أشخاص القانون العام؛ تأميم المنشآت ونظام الخوصصة. للبرلمان، بالإضافة إلى الميادين المشار إليها في الفقرة السابقة، صلاحية التصويت على قوانين تضع إطارا للأهداف الأساسية لنشاط الدولة، في الميادين الاقتصادية والاجتماعية والبيئية والثقافية.»', 'دستور 2011، الفصل 71', true),
  ('const-art-072', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يختص المجال التنظيمي بالمواد التي لا يشملها اختصاص القانون»؟', '["الفصل 71", "الفصل 72", "الفصل 73", "الفصل 74"]'::jsonb, 1, 'الفصل 72 من دستور 2011 ينص على: «يختص المجال التنظيمي بالمواد التي لا يشملها اختصاص القانون.»', 'دستور 2011، الفصل 72', true),
  ('const-art-073', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يمكن تغيير النصوص التشريعية من حيث الشكل بمرسوم، بعد موافقة المحكمة الدستورية، إذا كان مضمونها يدخل في مجال من المجالات التي تمارس فيها السلطة التنظيمية اختصاصها»؟', '["الفصل 72", "الفصل 73", "الفصل 74", "الفصل 75"]'::jsonb, 1, 'الفصل 73 من دستور 2011 ينص على: «يمكن تغيير النصوص التشريعية من حيث الشكل بمرسوم، بعد موافقة المحكمة الدستورية، إذا كان مضمونها يدخل في مجال من المجالات التي تمارس فيها السلطة التنظيمية اختصاصها.»', 'دستور 2011، الفصل 73', true),
  ('const-art-074', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يمكن الإعلان لمدة ثلاثين يوما عن حالة الحصار، بمقتضى ظهير يوقعه بالعطف رئيس الحكومة، ولا يمكن تمديد هذا الأجل إلا بالقانون»؟', '["الفصل 73", "الفصل 74", "الفصل 75", "الفصل 76"]'::jsonb, 1, 'الفصل 74 من دستور 2011 ينص على: «يمكن الإعلان لمدة ثلاثين يوما عن حالة الحصار، بمقتضى ظهير يوقعه بالعطف رئيس الحكومة، ولا يمكن تمديد هذا الأجل إلا بالقانون.»', 'دستور 2011، الفصل 74', true),
  ('const-art-075', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يصدر قانون المالية، الذي يودع بالأسبقية لدى مجلس النواب، بالتصويت من قبل البرلمان، وذلك طبق الشروط المنصوص عليها في قانون تنظيمي؛ ويحدد هذا القانون التنظيمي طبيعة المعلومات والوثائق والمعطيات الضرورية لتعزيز المناقشة البرلمانية حول مشروع قانون المالية»؟', '["الفصل 74", "الفصل 75", "الفصل 76", "الفصل 77"]'::jsonb, 1, 'الفصل 75 من دستور 2011 ينص على: «يصدر قانون المالية، الذي يودع بالأسبقية لدى مجلس النواب، بالتصويت من قبل البرلمان، وذلك طبق الشروط المنصوص عليها في قانون تنظيمي؛ ويحدد هذا القانون التنظيمي طبيعة المعلومات والوثائق والمعطيات الضرورية لتعزيز المناقشة البرلمانية حول مشروع قانون المالية. يصوت البرلمان مرة واحدة على نفقات التجهيز التي يتطلبها، في مجال التنمية، إنجاز المخططات التنموية الاستراتيجية، والبرامج متعددة السنوات، التي تعدها الحكومة وتطلع عليها البرلمان، وعندما يوافق على تلك النفقات، يستمر مفعول الموافقة تلقائيا على النفقات طيلة مدة هذه المخططات والبرامج، وللحكومة وحدها الصلاحية لتقديم مشاريع قوانين ترمي إلى تغيير ما تمت الموافقة عليه في الإطار المذكور. إذا لم يتم في نهاية السنة المالية التصويت على قانون المالية أو لم يصدر الأمر بتنفيذه، بسبب إحالته إلى المحكمة الدستورية، تطبيقا للفصل 132 من الدستور، فإن الحكومة تفتح بمرسوم الاعتمادات اللازمة لسير المرافق العمومية، والقيام بالمهام المنوطة بها، على أساس ما هو مقترح في الميزانية المعروضة على الموافقة. ويسترسل العمل، في هذه الحالة، باستخلاص المداخيل طبقا للمقتضيات التشريعية والتنظيمية الجارية عليها، باستثناء المداخيل المقترح إلغاؤها في مشروع قانون المالية؛ أما المداخيل التي ينص المشروع المذكور على تخفيض مقدارها، فتُستخلص على أساس المقدار الجديد المقترح.»', 'دستور 2011، الفصل 75', true),
  ('const-art-076', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تعرض الحكومة سنويا على البرلمان، قانون التصفية المتعلق بتنفيذ قانون المالية، خلال السنة الثانية التي تلي سنة تنفيذ هذا القانون»؟', '["الفصل 75", "الفصل 76", "الفصل 77", "الفصل 78"]'::jsonb, 1, 'الفصل 76 من دستور 2011 ينص على: «تعرض الحكومة سنويا على البرلمان، قانون التصفية المتعلق بتنفيذ قانون المالية، خلال السنة الثانية التي تلي سنة تنفيذ هذا القانون. ويتضمن قانون التصفية حصيلة ميزانيات التجهيز التي انتهت مدة نفاذها.»', 'دستور 2011، الفصل 76', true),
  ('const-art-077', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يسهر البرلمان والحكومة على الحفاظ على توازن مالية الدولة»؟', '["الفصل 76", "الفصل 77", "الفصل 78", "الفصل 79"]'::jsonb, 1, 'الفصل 77 من دستور 2011 ينص على: «يسهر البرلمان والحكومة على الحفاظ على توازن مالية الدولة. وللحكومة أن ترفض، بعد بيان الأسباب، المقترحات والتعديلات التي يتقدم بها أعضاء البرلمان، إذا كان قبولها يؤدي بالنسبة لقانون المالية إلى تخفيض الموارد العمومية، أو إلى إحداث تكليف عمومي، أو الزيادة في تكليف موجود. ممارسة السلطة التشريعية»', 'دستور 2011، الفصل 77', true),
  ('const-art-078', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «لرئيس الحكومة ولأعضاء البرلمان على السواء حق التقدم باقتراح القوانين»؟', '["الفصل 77", "الفصل 78", "الفصل 79", "الفصل 80"]'::jsonb, 1, 'الفصل 78 من دستور 2011 ينص على: «لرئيس الحكومة ولأعضاء البرلمان على السواء حق التقدم باقتراح القوانين. تودع مشاريع القوانين بالأسبقية لدى مكتب مجلس النواب، غير أن مشاريع القوانين المتعلقة، على وجه الخصوص، بالجماعات الترابية وبالتنمية الجهوية، وبالقضايا الاجتماعية، تودع بالأسبقية لدى مكتب مجلس المستشارين.»', 'دستور 2011، الفصل 78', true),
  ('const-art-079', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «للحكومة أن تدفع بعدم قبول كل مقترح أو تعديل لا يدخل في مجال القانون»؟', '["الفصل 78", "الفصل 79", "الفصل 80", "الفصل 81"]'::jsonb, 1, 'الفصل 79 من دستور 2011 ينص على: «للحكومة أن تدفع بعدم قبول كل مقترح أو تعديل لا يدخل في مجال القانون. كل خلاف في هذا الشأن تبت فيه المحكمة الدستورية، في أجل ثمانية أيام، بطلب من أحد رئيسي المجلسين، أو من رئيس الحكومة.»', 'دستور 2011، الفصل 79', true),
  ('const-art-080', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تحال مشاريع ومقترحات القوانين لأجل النظر فيها على اللجان التي يستمر عملها خلال الفترات الفاصلة بين الدورات»؟', '["الفصل 79", "الفصل 80", "الفصل 81", "الفصل 82"]'::jsonb, 1, 'الفصل 80 من دستور 2011 ينص على: «تحال مشاريع ومقترحات القوانين لأجل النظر فيها على اللجان التي يستمر عملها خلال الفترات الفاصلة بين الدورات.»', 'دستور 2011، الفصل 80', true),
  ('const-art-081', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يمكن للحكومة أن تصدر، خلال الفترة الفاصلة بين الدورات، وباتفاق مع اللجان التي يعنيها الأمر في كلا المجلسين، مراسيم قوانين، يجب عرضها بقصد المصادقة عليها من طرف البرلمان، خلال دورته العادية الموالية»؟', '["الفصل 80", "الفصل 81", "الفصل 82", "الفصل 83"]'::jsonb, 1, 'الفصل 81 من دستور 2011 ينص على: «يمكن للحكومة أن تصدر، خلال الفترة الفاصلة بين الدورات، وباتفاق مع اللجان التي يعنيها الأمر في كلا المجلسين، مراسيم قوانين، يجب عرضها بقصد المصادقة عليها من طرف البرلمان، خلال دورته العادية الموالية. يودع مشروع المرسوم بقانون لدى مكتب مجلس النواب، وتناقشه بالتتابع اللجان المعنية في كلا المجلسين بغية التوصل داخل أجل ستة أيام، إلى قرار مشترك بينهما في شأنه. وإذا لم يحصل هذا الاتفاق، فإن القرار يرجع إلى اللجنة المعنية في مجلس النواب.»', 'دستور 2011، الفصل 81', true),
  ('const-art-082', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يضع مكتب كل من مجلسي البرلمان جدول أعماله»؟', '["الفصل 81", "الفصل 82", "الفصل 83", "الفصل 84"]'::jsonb, 1, 'الفصل 82 من دستور 2011 ينص على: «يضع مكتب كل من مجلسي البرلمان جدول أعماله. ويتضمن هذا الجدول مشاريع القوانين ومقترحات القوانين، بالأسبقية ووفق الترتيب الذي تحدده الحكومة. يخصص يوم واحد على الأقل في الشهر لدراسة مقترحات القوانين، ومن بينها تلك المقدمة من قبل المعارضة.»', 'دستور 2011، الفصل 82', true),
  ('const-art-083', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «لأعضاء مجلسي البرلمان وللحكومة حق التعديل»؟', '["الفصل 82", "الفصل 83", "الفصل 84", "الفصل 85"]'::jsonb, 1, 'الفصل 83 من دستور 2011 ينص على: «لأعضاء مجلسي البرلمان وللحكومة حق التعديل. وللحكومة، بعد افتتاح المناقشة، أن تعارض في بحث كل تعديل لم يُعرض من قبل على اللجنة التي يعنيها الأمر. يبت المجلس المعروض عليه النص، بتصويت واحد، في النص المتناقش فيه، كله أو بعضه إذا ما طلبت الحكومة ذلك، مع الاقتصار على التعديلات المقترحة أو المقبولة من قبلها. وبإمكان المجلس المعني بالأمر أن يعترض على هذه المسطرة بأغلبية أعضائه.»', 'دستور 2011، الفصل 83', true),
  ('const-art-084', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يتداول مجلسا البرلمان بالتتابع في كل مشروع أو مقترح قانون، بغية التوصل إلى المصادقة على نص واحد؛ ويتداول مجلس النواب بالأسبقية، وعلى التوالي، في مشاريع القوانين، وفي مقترحات القوانين التي قدمت بمبادرة من أعضائه، ويتداول مجلس المستشارين بدوره بالأسبقية، وعلى»؟', '["الفصل 83", "الفصل 84", "الفصل 85", "الفصل 86"]'::jsonb, 1, 'الفصل 84 من دستور 2011 ينص على: «يتداول مجلسا البرلمان بالتتابع في كل مشروع أو مقترح قانون، بغية التوصل إلى المصادقة على نص واحد؛ ويتداول مجلس النواب بالأسبقية، وعلى التوالي، في مشاريع القوانين، وفي مقترحات القوانين التي قدمت بمبادرة من أعضائه، ويتداول مجلس المستشارين بدوره بالأسبقية، وعلى التوالي، في مشاريع القوانين، وكذا في مقترحات القوانين التي هي من مبادرة أعضائه؛ ويتداول كل مجلس في النص الذي صوت عليه المجلس الآخر في الصيغة التي أحيل بها إليه. ويعود لمجلس النواب التصويت النهائي على النص الذي تم البت فيه، ولا يقع هذا التصويت إلا بالأغلبية المطلقة لأعضائه الحاضرين، إذا تعلق الأمر بنص يخص الجماعات الترابية، والمجالات ذات الصلة بالتنمية الجهوية والشؤون الاجتماعية.»', 'دستور 2011، الفصل 84', true),
  ('const-art-085', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «لا يتم التداول في مشاريع ومقترحات القوانين التنظيمية من قبل مجلس النواب، إلا بعد مضي عشرة أيام على وضعها لدى مكتبه، ووفق المسطرة المشار إليها في الفصل 84، وتتم المصادقة عليها نهائيا بالأغلبية المطلقة للأعضاء الحاضرين من المجلس المذكور؛ غير أنه إذا تعلق الأمر»؟', '["الفصل 84", "الفصل 85", "الفصل 86", "الفصل 87"]'::jsonb, 1, 'الفصل 85 من دستور 2011 ينص على: «لا يتم التداول في مشاريع ومقترحات القوانين التنظيمية من قبل مجلس النواب، إلا بعد مضي عشرة أيام على وضعها لدى مكتبه، ووفق المسطرة المشار إليها في الفصل 84، وتتم المصادقة عليها نهائيا بالأغلبية المطلقة للأعضاء الحاضرين من المجلس المذكور؛ غير أنه إذا تعلق الأمر بمشروع أو بمقترح قانون تنظيمي يخص مجلس المستشارين أو الجماعات الترابية، فإن التصويت يتم بأغلبية أعضاء مجلس النواب. يجب أن يتم إقرار القوانين التنظيمية المتعلقة بمجلس المستشارين، باتفاق بين مجلسي البرلمان، على نص موحد. لا يمكن إصدار الأمر بتنفيذ القوانين التنظيمية، إلا بعد أن تصرح المحكمة الدستورية بمطابقتها للدستور.»', 'دستور 2011، الفصل 85', true),
  ('const-art-086', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تعرض مشاريع القوانين التنظيمية المنصوص عليها في هذا الدستور وجوبا قصد المصادقة عليها من قبل البرلمان، في أجل لا يتعدى مدة الولاية التشريعية الأولى التي تلي صدور الأمر بتنفيذ هذا الدستور»؟', '["الفصل 85", "الفصل 86", "الفصل 87", "الفصل 88"]'::jsonb, 1, 'الفصل 86 من دستور 2011 ينص على: «تعرض مشاريع القوانين التنظيمية المنصوص عليها في هذا الدستور وجوبا قصد المصادقة عليها من قبل البرلمان، في أجل لا يتعدى مدة الولاية التشريعية الأولى التي تلي صدور الأمر بتنفيذ هذا الدستور. الباب الخامس: السلطة التنفيذية»', 'دستور 2011، الفصل 86', true),
  ('const-art-087', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تتألف الحكومة من رئيس الحكومة والوزراء، ويمكن أن تضم كتابا للدولة»؟', '["الفصل 86", "الفصل 87", "الفصل 88", "الفصل 89"]'::jsonb, 1, 'الفصل 87 من دستور 2011 ينص على: «تتألف الحكومة من رئيس الحكومة والوزراء، ويمكن أن تضم كتابا للدولة. يُحدد قانون تنظيمي، خاصة، القواعد المتعلقة بتنظيم وتسيير أشغال الحكومة والوضع القانوني لأعضائها. ويحدد هذا القانون التنظيمي أيضا حالات التنافي مع الوظيفة الحكومية، وقواعد الحد من الجمع بين المناصب، والقواعد الخاصة بتصريف الحكومة المنتهية مهامها للأمور الجارية.»', 'دستور 2011، الفصل 87', true),
  ('const-art-088', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «بعد تعيين الملك لأعضاء الحكومة، يتقدم رئيس الحكومة أمام مجلسي البرلمان مجتمعين، ويعرض البرنامج الذي يعتزم تطبيقه»؟', '["الفصل 87", "الفصل 88", "الفصل 89", "الفصل 90"]'::jsonb, 1, 'الفصل 88 من دستور 2011 ينص على: «بعد تعيين الملك لأعضاء الحكومة، يتقدم رئيس الحكومة أمام مجلسي البرلمان مجتمعين، ويعرض البرنامج الذي يعتزم تطبيقه. ويجب أن يتضمن هذا البرنامج الخطوط الرئيسية للعمل الذي تنوي الحكومة القيام به في مختلف مجالات النشاط الوطني، وبالأخص في ميادين السياسة الاقتصادية والاجتماعية والبيئية والثقافية والخارجية. يكون البرنامج المشار إليه أعلاه، موضوع مناقشة أمام كلا المجلسين، يعقبها تصويت في مجلس النواب. تعتبر الحكومة منصبة بعد حصولها على ثقة مجلس النواب، المعبر عنها بتصويت الأغلبية المطلقة للأعضاء الذين يتألف منهم، لصالح البرنامج الحكومي.»', 'دستور 2011، الفصل 88', true),
  ('const-art-089', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تمارس الحكومة السلطة التنفيذية. تعمل الحكومة، تحت سلطة رئيسها، على تنفيذ البرنامج الحكومي وعلى ضمان تنفيذ القوانين. والإدارة موضوعة تحت تصرفها، كما تمارس الإشراف والوصاية على المؤسسات والمقاولات العمومية»؟', '["الفصل 88", "الفصل 89", "الفصل 90", "الفصل 91"]'::jsonb, 1, 'الفصل 89 من دستور 2011 ينص على: «تمارس الحكومة السلطة التنفيذية. تعمل الحكومة، تحت سلطة رئيسها، على تنفيذ البرنامج الحكومي وعلى ضمان تنفيذ القوانين. والإدارة موضوعة تحت تصرفها، كما تمارس الإشراف والوصاية على المؤسسات والمقاولات العمومية.»', 'دستور 2011، الفصل 89', true),
  ('const-art-090', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يمارس رئيس الحكومة السلطة التنظيمية، ويمكن أن يفوض بعض سلطه إلى الوزراء»؟', '["الفصل 89", "الفصل 90", "الفصل 91", "الفصل 92"]'::jsonb, 1, 'الفصل 90 من دستور 2011 ينص على: «يمارس رئيس الحكومة السلطة التنظيمية، ويمكن أن يفوض بعض سلطه إلى الوزراء. تحمل المقررات التنظيمية الصادرة عن رئيس الحكومة التوقيع بالعطف من لدن الوزراء المكلفين بتنفيذها.»', 'دستور 2011، الفصل 90', true),
  ('const-art-091', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يعين رئيس الحكومة في الوظائف المدنية في الإدارات العمومية، وفي الوظائف السامية في المؤسسات والمقاولات العمومية، دون إخلال بأحكام الفصل 49 من هذا الدستور»؟', '["الفصل 90", "الفصل 91", "الفصل 92", "الفصل 93"]'::jsonb, 1, 'الفصل 91 من دستور 2011 ينص على: «يعين رئيس الحكومة في الوظائف المدنية في الإدارات العمومية، وفي الوظائف السامية في المؤسسات والمقاولات العمومية، دون إخلال بأحكام الفصل 49 من هذا الدستور. يمكن لرئيس الحكومة تفويض هذه السلطة.»', 'دستور 2011، الفصل 91', true),
  ('const-art-092', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يتداول مجلس الحكومة، تحت رئاسة رئيس الحكومة، في القضايا والنصوص التالية: السياسة العامة للدولة قبل عرضها على المجلس الوزاري؛ السياسات العمومية؛ السياسات القطاعية؛ طلب الثقة من مجلس النواب، قصد مواصلة الحكومة تحمل مسؤوليتها؛ القضايا الراهنة المرتبطة بحقوق»؟', '["الفصل 91", "الفصل 92", "الفصل 93", "الفصل 94"]'::jsonb, 1, 'الفصل 92 من دستور 2011 ينص على: «يتداول مجلس الحكومة، تحت رئاسة رئيس الحكومة، في القضايا والنصوص التالية: السياسة العامة للدولة قبل عرضها على المجلس الوزاري؛ السياسات العمومية؛ السياسات القطاعية؛ طلب الثقة من مجلس النواب، قصد مواصلة الحكومة تحمل مسؤوليتها؛ القضايا الراهنة المرتبطة بحقوق الإنسان وبالنظام العام؛ مشاريع القوانين، ومن بينها مشروع قانون المالية، قبل إيداعها بمكتب مجلس النواب، دون إخلال بالأحكام الواردة في الفصل 49 من هذا الدستور؛ مراسيم القوانين؛ مشاريع المراسيم التنظيمية؛ مشاريع المراسيم المشار إليها في الفصول 65 (الفقرة الثانية) و66 و70 (الفقرة الثالثة) من هذا الدستور؛ المعاهدات والاتفاقيات الدولية قبل عرضها على المجلس الوزاري؛ تعيين الكتاب العامين، ومديري الإدارات المركزية بالإدارات العمومية، ورؤساء الجامعات والعمداء، ومديري المدارس والمؤسسات العليا. وللقانون التنظيمي المشار إليه في الفصل 49 من هذا الدستور، أن يتمم لائحة الوظائف التي يتم التعيين فيها في مجلس الحكومة. ويحدد هذا القانون التنظيمي، على وجه الخصوص، مبادئ ومعايير التعيين في هذه الوظائف، لا سيما منها مبادئ تكافؤ الفرص والاستحقاق والكفاءة والشفافية. يطلع رئيس الحكومة الملك على خلاصات مداولات مجلس الحكومة.»', 'دستور 2011، الفصل 92', true),
  ('const-art-093', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «الوزراء مسؤولون عن تنفيذ السياسة الحكومية كل في القطاع المكلف به، وفي إطار التضامن الحكومي»؟', '["الفصل 92", "الفصل 93", "الفصل 94", "الفصل 95"]'::jsonb, 1, 'الفصل 93 من دستور 2011 ينص على: «الوزراء مسؤولون عن تنفيذ السياسة الحكومية كل في القطاع المكلف به، وفي إطار التضامن الحكومي. يقوم الوزراء بأداء المهام المسندة إليهم من قبل رئيس الحكومة، ويطلعون مجلس الحكومة على ذلك. يمكن للوزراء أن يفوضوا جزءا من اختصاصاتهم إلى كتاب الدولة.»', 'دستور 2011، الفصل 93', true),
  ('const-art-094', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «أعضاء الحكومة مسؤولون جنائيا أمام محاكم المملكة، عما يرتكبون من جنايات وجنح، أثناء ممارستهم لمهامهم»؟', '["الفصل 93", "الفصل 94", "الفصل 95", "الفصل 96"]'::jsonb, 1, 'الفصل 94 من دستور 2011 ينص على: «أعضاء الحكومة مسؤولون جنائيا أمام محاكم المملكة، عما يرتكبون من جنايات وجنح، أثناء ممارستهم لمهامهم. يُحدد القانون المسطرة المتعلقة بهذه المسؤولية. الباب السادس: العلاقات بين السلط العلاقة بين الملك والسلطة التشريعية»', 'دستور 2011، الفصل 94', true),
  ('const-art-095', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «للملك أن يطلب من كلا مجلسي البرلمان أن يقرأ قراءة جديدة كل مشروع أو مقترح قانون»؟', '["الفصل 94", "الفصل 95", "الفصل 96", "الفصل 97"]'::jsonb, 1, 'الفصل 95 من دستور 2011 ينص على: «للملك أن يطلب من كلا مجلسي البرلمان أن يقرأ قراءة جديدة كل مشروع أو مقترح قانون. تُطلب القراءة الجديدة بخطاب، ولا يمكن أن ترفض هذه القراءة الجديدة.»', 'دستور 2011، الفصل 95', true),
  ('const-art-096', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «للملك، بعد استشارة رئيس المحكمة الدستورية وإخبار رئيس الحكومة ورئيس مجلس النواب، ورئيس مجلس المستشارين، أن يحل بظهير المجلسين معا أو أحدهما»؟', '["الفصل 95", "الفصل 96", "الفصل 97", "الفصل 98"]'::jsonb, 1, 'الفصل 96 من دستور 2011 ينص على: «للملك، بعد استشارة رئيس المحكمة الدستورية وإخبار رئيس الحكومة ورئيس مجلس النواب، ورئيس مجلس المستشارين، أن يحل بظهير المجلسين معا أو أحدهما. يقع الحل بعد خطاب يوجهه الملك إلى الأمة.»', 'دستور 2011، الفصل 96', true),
  ('const-art-097', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يتم انتخاب البرلمان الجديد أو المجلس الجديد في ظرف شهرين على الأكثر بعد تاريخ الحل»؟', '["الفصل 96", "الفصل 97", "الفصل 98", "الفصل 99"]'::jsonb, 1, 'الفصل 97 من دستور 2011 ينص على: «يتم انتخاب البرلمان الجديد أو المجلس الجديد في ظرف شهرين على الأكثر بعد تاريخ الحل.»', 'دستور 2011، الفصل 97', true),
  ('const-art-098', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «إذا وقع حل أحد المجلسين، فلا يمكن حل المجلس الذي يليه إلا بعد مضي سنة على انتخابه، ما عدا في حالة تعذر توفر أغلبية حكومية داخل مجلس النواب الجديد»؟', '["الفصل 97", "الفصل 98", "الفصل 99", "الفصل 100"]'::jsonb, 1, 'الفصل 98 من دستور 2011 ينص على: «إذا وقع حل أحد المجلسين، فلا يمكن حل المجلس الذي يليه إلا بعد مضي سنة على انتخابه، ما عدا في حالة تعذر توفر أغلبية حكومية داخل مجلس النواب الجديد.»', 'دستور 2011، الفصل 98', true),
  ('const-art-099', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يتم اتخاذ قرار إشهار الحرب داخل المجلس الوزاري، طبقا للفصل 49 من هذا الدستور، وبعد إحاطة البرلمان علما بذلك من لدن الملك»؟', '["الفصل 98", "الفصل 99", "الفصل 100", "الفصل 101"]'::jsonb, 1, 'الفصل 99 من دستور 2011 ينص على: «يتم اتخاذ قرار إشهار الحرب داخل المجلس الوزاري، طبقا للفصل 49 من هذا الدستور، وبعد إحاطة البرلمان علما بذلك من لدن الملك. العلاقات بين السلطتين التشريعية والتنفيذية»', 'دستور 2011، الفصل 99', true),
  ('const-art-100', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تُخصص بالأسبقية جلسة في كل أسبوع لأسئلة أعضاء مجلسي البرلمان وأجوبة الحكومة»؟', '["الفصل 99", "الفصل 100", "الفصل 101", "الفصل 102"]'::jsonb, 1, 'الفصل 100 من دستور 2011 ينص على: «تُخصص بالأسبقية جلسة في كل أسبوع لأسئلة أعضاء مجلسي البرلمان وأجوبة الحكومة. تُدلي الحكومة بجوابها خلال العشرين يوما الموالية لإحالة السؤال إليها. تُقدم الأجوبة على الأسئلة المتعلقة بالسياسة العامة من قبل رئيس الحكومة، وتخصص لهذه الأسئلة جلسة واحدة كل شهر، وتُقدم الأجوبة عنها أمام المجلس الذي يعنيه الأمر خلال الثلاثين يوما الموالية لإحالة الأسئلة إلى رئيس الحكومة.»', 'دستور 2011، الفصل 100', true),
  ('const-art-101', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يعرض رئيس الحكومة أمام البرلمان الحصيلة المرحلية لعمل الحكومة، إما بمبادرة منه، أو بطلب من ثلث أعضاء مجلس النواب، أو من أغلبية أعضاء مجلس المستشارين»؟', '["الفصل 100", "الفصل 101", "الفصل 102", "الفصل 103"]'::jsonb, 1, 'الفصل 101 من دستور 2011 ينص على: «يعرض رئيس الحكومة أمام البرلمان الحصيلة المرحلية لعمل الحكومة، إما بمبادرة منه، أو بطلب من ثلث أعضاء مجلس النواب، أو من أغلبية أعضاء مجلس المستشارين. تُخصص جلسة سنوية من قبل البرلمان لمناقشة السياسات العمومية وتقييمها.»', 'دستور 2011، الفصل 101', true),
  ('const-art-102', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يمكن للجان المعنية في كلا المجلسين أن تطلب الاستماع إلى مسؤولي الإدارات والمؤسسات والمقاولات العمومية، بحضور الوزراء المعنيين، وتحت مسؤوليتهم»؟', '["الفصل 101", "الفصل 102", "الفصل 103", "الفصل 104"]'::jsonb, 1, 'الفصل 102 من دستور 2011 ينص على: «يمكن للجان المعنية في كلا المجلسين أن تطلب الاستماع إلى مسؤولي الإدارات والمؤسسات والمقاولات العمومية، بحضور الوزراء المعنيين، وتحت مسؤوليتهم.»', 'دستور 2011، الفصل 102', true),
  ('const-art-103', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يمكن لرئيس الحكومة أن يربط، لدى مجلس النواب، مواصلة الحكومة تحمل مسؤوليتها بتصويت يمنح الثقة بشأن تصريح يدلي به في موضوع السياسة العامة، أو بشأن نص يطلب الموافقة عليه»؟', '["الفصل 102", "الفصل 103", "الفصل 104", "الفصل 105"]'::jsonb, 1, 'الفصل 103 من دستور 2011 ينص على: «يمكن لرئيس الحكومة أن يربط، لدى مجلس النواب، مواصلة الحكومة تحمل مسؤوليتها بتصويت يمنح الثقة بشأن تصريح يدلي به في موضوع السياسة العامة، أو بشأن نص يطلب الموافقة عليه. لا يمكن سحب الثقة من الحكومة، أو رفض النص، إلا بالأغلبية المطلقة للأعضاء الذين يتألف منهم مجلس النواب. لا يقع التصويت إلا بعد مضي ثلاثة أيام كاملة على تاريخ طرح مسألة الثقة. يؤدي سحب الثقة إلى استقالة الحكومة استقالة جماعية.»', 'دستور 2011، الفصل 103', true),
  ('const-art-104', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يمكن لرئيس الحكومة حل مجلس النواب، بعد استشارة الملك ورئيس المجلس، ورئيس المحكمة الدستورية، بمرسوم يتخذ في مجلس وزاري»؟', '["الفصل 103", "الفصل 104", "الفصل 105", "الفصل 106"]'::jsonb, 1, 'الفصل 104 من دستور 2011 ينص على: «يمكن لرئيس الحكومة حل مجلس النواب، بعد استشارة الملك ورئيس المجلس، ورئيس المحكمة الدستورية، بمرسوم يتخذ في مجلس وزاري. يقدم رئيس الحكومة أمام مجلس النواب تصريحا يتضمن، بصفة خاصة، دوافع قرار الحل وأهدافه.»', 'دستور 2011، الفصل 104', true),
  ('const-art-105', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «لمجلس النواب أن يعارض في مواصلة الحكومة تحمل مسؤوليتها، بالتصويت على ملتمس للرقابة؛ ولا يقبل هذا الملتمس إلا إذا وقعه على الأقل خُمس الأعضاء الذين يتألف منهم المجلس»؟', '["الفصل 104", "الفصل 105", "الفصل 106", "الفصل 107"]'::jsonb, 1, 'الفصل 105 من دستور 2011 ينص على: «لمجلس النواب أن يعارض في مواصلة الحكومة تحمل مسؤوليتها، بالتصويت على ملتمس للرقابة؛ ولا يقبل هذا الملتمس إلا إذا وقعه على الأقل خُمس الأعضاء الذين يتألف منهم المجلس. لا تصح الموافقة على ملتمس الرقابة من قبل مجلس النواب، إلا بتصويت الأغلبية المطلقة للأعضاء الذين يتألف منهم. لا يقع التصويت إلا بعد مضي ثلاثة أيام كاملة على إيداع الملتمس؛ وتؤدي الموافقة على ملتمس الرقابة إلى استقالة الحكومة استقالة جماعية. إذا وقعت موافقة مجلس النواب على ملتمس الرقابة، فلا يقبل بعد ذلك تقديم أي ملتمس رقابة أمامه، طيلة سنة.»', 'دستور 2011، الفصل 105', true),
  ('const-art-106', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «لمجلس المستشارين أن يُسائل الحكومة بواسطة ملتمس يوقعه على الأقل خُمس أعضائه؛ ولا يقع التصويت عليه، بعد مضي ثلاثة أيام كاملة على إيداعه، إلا بالأغلبية المطلقة لأعضاء هذا المجلس»؟', '["الفصل 105", "الفصل 106", "الفصل 107", "الفصل 108"]'::jsonb, 1, 'الفصل 106 من دستور 2011 ينص على: «لمجلس المستشارين أن يُسائل الحكومة بواسطة ملتمس يوقعه على الأقل خُمس أعضائه؛ ولا يقع التصويت عليه، بعد مضي ثلاثة أيام كاملة على إيداعه، إلا بالأغلبية المطلقة لأعضاء هذا المجلس. يبعث رئيس مجلس المستشارين، على الفور، بنص ملتمس المساءلة إلى رئيس الحكومة؛ ولهذا الأخير أجل ستة أيام ليعرض أمام هذا المجلس جواب الحكومة، يتلوه نقاش لا يعقبه تصويت. الباب السابع: السلطة القضائية استقلال القضاء»', 'دستور 2011، الفصل 106', true),
  ('const-art-107', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «السلطة القضائية مستقلة عن السلطة التشريعية وعن السلطة التنفيذية»؟', '["الفصل 106", "الفصل 107", "الفصل 108", "الفصل 109"]'::jsonb, 1, 'الفصل 107 من دستور 2011 ينص على: «السلطة القضائية مستقلة عن السلطة التشريعية وعن السلطة التنفيذية. الملك هو الضامن لاستقلال السلطة القضائية.»', 'دستور 2011، الفصل 107', true),
  ('const-art-108', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «لا يعزل قضاة الأحكام ولا ينقلون إلا بمقتضى القانون»؟', '["الفصل 107", "الفصل 108", "الفصل 109", "الفصل 110"]'::jsonb, 1, 'الفصل 108 من دستور 2011 ينص على: «لا يعزل قضاة الأحكام ولا ينقلون إلا بمقتضى القانون.»', 'دستور 2011، الفصل 108', true),
  ('const-art-109', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يمنع كل تدخل في القضايا المعروضة على القضاء؛ ولا يتلقى القاضي بشأن مهمته القضائية أي أوامر أو تعليمات، ولا يخضع لأي ضغط»؟', '["الفصل 108", "الفصل 109", "الفصل 110", "الفصل 111"]'::jsonb, 1, 'الفصل 109 من دستور 2011 ينص على: «يمنع كل تدخل في القضايا المعروضة على القضاء؛ ولا يتلقى القاضي بشأن مهمته القضائية أي أوامر أو تعليمات، ولا يخضع لأي ضغط. يجب على القاضي، كلما اعتبر أن استقلاله مهدد، أن يحيل الأمر إلى المجلس الأعلى للسلطة القضائية. يعد كل إخلال من القاضي بواجب الاستقلال والتجرد خطأ مهنيا جسيما، بصرف النظر عن المتابعات القضائية المحتملة. يعاقب القانون كل من حاول التأثير على القاضي بكيفية غير مشروعة.»', 'دستور 2011، الفصل 109', true),
  ('const-art-110', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «لا يلزم قضاة الأحكام إلا بتطبيق القانون. ولا تصدر أحكام القضاء إلا على أساس التطبيق العادل للقانون. يجب على قضاة النيابة العامة تطبيق القانون. كما يتعين عليهم الالتزام بالتعليمات الكتابية القانونية الصادرة عن السلطة التي يتبعون لها»؟', '["الفصل 109", "الفصل 110", "الفصل 111", "الفصل 112"]'::jsonb, 1, 'الفصل 110 من دستور 2011 ينص على: «لا يلزم قضاة الأحكام إلا بتطبيق القانون. ولا تصدر أحكام القضاء إلا على أساس التطبيق العادل للقانون. يجب على قضاة النيابة العامة تطبيق القانون. كما يتعين عليهم الالتزام بالتعليمات الكتابية القانونية الصادرة عن السلطة التي يتبعون لها.»', 'دستور 2011، الفصل 110', true),
  ('const-art-111', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «للقضاة الحق في حرية التعبير، بما يتلاءم مع واجب التحفظ والأخلاقيات القضائية»؟', '["الفصل 110", "الفصل 111", "الفصل 112", "الفصل 113"]'::jsonb, 1, 'الفصل 111 من دستور 2011 ينص على: «للقضاة الحق في حرية التعبير، بما يتلاءم مع واجب التحفظ والأخلاقيات القضائية. يمكن للقضاة الانخراط في جمعيات، أو إنشاء جمعيات مهنية، مع احترام واجبات التجرد واستقلال القضاء، وطبقا للشروط المنصوص عليها في القانون. يُمنع على القضاة الانخراط في الأحزاب السياسية والمنظمات النقابية.»', 'دستور 2011، الفصل 111', true),
  ('const-art-112', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يُحدد النظام الأساسي للقضاة بقانون تنظيمي»؟', '["الفصل 111", "الفصل 112", "الفصل 113", "الفصل 114"]'::jsonb, 1, 'الفصل 112 من دستور 2011 ينص على: «يُحدد النظام الأساسي للقضاة بقانون تنظيمي. المجلس الأعلى للسلطة القضائية»', 'دستور 2011، الفصل 112', true),
  ('const-art-113', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يسهر المجلس الأعلى للسلطة القضائية على تطبيق الضمانات الممنوحة للقضاة، ولا سيما فيما يخص استقلالهم وتعيينهم وترقيتهم وتقاعدهم وتأديبهم»؟', '["الفصل 112", "الفصل 113", "الفصل 114", "الفصل 115"]'::jsonb, 1, 'الفصل 113 من دستور 2011 ينص على: «يسهر المجلس الأعلى للسلطة القضائية على تطبيق الضمانات الممنوحة للقضاة، ولا سيما فيما يخص استقلالهم وتعيينهم وترقيتهم وتقاعدهم وتأديبهم. يضع المجلس الأعلى للسلطة القضائية، بمبادرة منه، تقارير حول وضعية القضاء ومنظومة العدالة، ويُصدر التوصيات الملائمة بشأنها. يُصدر المجلس الأعلى للسلطة القضائية، بطلب من الملك أو الحكومة أو البرلمان، آراء مفصلة حول كل مسألة تتعلق بالعدالة مع مراعاة مبدإ فصل السلط.»', 'دستور 2011، الفصل 113', true),
  ('const-art-114', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تكون المقررات المتعلقة بالوضعيات الفردية، الصادرة عن المجلس الأعلى للسلطة القضائية قابلة للطعن بسبب الشطط في استعمال السلطة، أمام أعلى هيئة قضائية إدارية بالمملكة»؟', '["الفصل 113", "الفصل 114", "الفصل 115", "الفصل 116"]'::jsonb, 1, 'الفصل 114 من دستور 2011 ينص على: «تكون المقررات المتعلقة بالوضعيات الفردية، الصادرة عن المجلس الأعلى للسلطة القضائية قابلة للطعن بسبب الشطط في استعمال السلطة، أمام أعلى هيئة قضائية إدارية بالمملكة.»', 'دستور 2011، الفصل 114', true),
  ('const-art-115', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يرأس الملك المجلس الأعلى للسلطة القضائية، ويتألف هذا المجلس من: الرئيس الأول لمحكمة النقض، رئيسا منتدبا؛ الوكيل العام للملك لدى محكمة النقض؛ رئيس الغرفة الأولى بمحكمة النقض؛ أربعة ممثلين لقضاة محاكم الاستئناف، ينتخبهم هؤلاء القضاة من بينهم؛ ستة ممثلين لقضاة»؟', '["الفصل 114", "الفصل 115", "الفصل 116", "الفصل 117"]'::jsonb, 1, 'الفصل 115 من دستور 2011 ينص على: «يرأس الملك المجلس الأعلى للسلطة القضائية، ويتألف هذا المجلس من: الرئيس الأول لمحكمة النقض، رئيسا منتدبا؛ الوكيل العام للملك لدى محكمة النقض؛ رئيس الغرفة الأولى بمحكمة النقض؛ أربعة ممثلين لقضاة محاكم الاستئناف، ينتخبهم هؤلاء القضاة من بينهم؛ ستة ممثلين لقضاة محاكم أول درجة، ينتخبهم هؤلاء القضاة من بينهم؛ ويجب ضمان تمثيلية النساء القاضيات من بين الأعضاء العشرة المنتخبين، بما يتناسب مع حضورهن داخل السلك القضائي؛ الوسيط؛ رئيس المجلس الوطني لحقوق الإنسان؛ خمس شخصيات يعينها الملك، مشهود لها بالكفاءة والتجرد والنزاهة، والعطاء المتميز في سبيل استقلال القضاء وسيادة القانون؛ من بينهم عضو يقترحه الأمين العام للمجلس العلمي الأعلى.»', 'دستور 2011، الفصل 115', true),
  ('const-art-116', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يعقد المجلس الأعلى للسلطة القضائية دورتين في السنة على الأقل»؟', '["الفصل 115", "الفصل 116", "الفصل 117", "الفصل 118"]'::jsonb, 1, 'الفصل 116 من دستور 2011 ينص على: «يعقد المجلس الأعلى للسلطة القضائية دورتين في السنة على الأقل. يتوفر المجلس الأعلى للسلطة القضائية على الاستقلال الإداري والمالي. يساعد المجلس الأعلى للسلطة القضائية، في المادة التأديبية، قضاة مفتشون من ذوي الخبرة. يُحدد بقانون تنظيمي انتخاب وتنظيم وسير المجلس الأعلى للسلطة القضائية، والمعايير المتعلقة بتدبير الوضعية المهنية للقضاة، ومسطرة التأديب. يراعي المجلس الأعلى للسلطة القضائية، في القضايا التي تهم قضاة النيابة العامة، تقارير التقييم المقدمة من قبل السلطة التي يتبعون لها. حقوق المتقاضين وقواعد سير العدالة»', 'دستور 2011، الفصل 116', true),
  ('const-art-117', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يتولى القاضي حماية حقوق الأشخاص والجماعات وحرياتهم وأمنهم القضائي، وتطبيق القانون»؟', '["الفصل 116", "الفصل 117", "الفصل 118", "الفصل 119"]'::jsonb, 1, 'الفصل 117 من دستور 2011 ينص على: «يتولى القاضي حماية حقوق الأشخاص والجماعات وحرياتهم وأمنهم القضائي، وتطبيق القانون.»', 'دستور 2011، الفصل 117', true),
  ('const-art-118', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «حق التقاضي مضمون لكل شخص للدفاع عن حقوقه وعن مصالحه التي يحميها القانون»؟', '["الفصل 117", "الفصل 118", "الفصل 119", "الفصل 120"]'::jsonb, 1, 'الفصل 118 من دستور 2011 ينص على: «حق التقاضي مضمون لكل شخص للدفاع عن حقوقه وعن مصالحه التي يحميها القانون. كل قرار اتخذ في المجال الإداري، سواء كان تنظيميا أو فرديا، يُمكن الطعن فيه أمام الهيئة القضائية الإدارية المختصة.»', 'دستور 2011، الفصل 118', true),
  ('const-art-119', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يعتبر كل مشتبه فيه أو متهم بارتكاب جريمة بريئا، إلى أن تثبت إدانته بمقرر قضائي مكتسب لقوة الشيء المقضي به»؟', '["الفصل 118", "الفصل 119", "الفصل 120", "الفصل 121"]'::jsonb, 1, 'الفصل 119 من دستور 2011 ينص على: «يعتبر كل مشتبه فيه أو متهم بارتكاب جريمة بريئا، إلى أن تثبت إدانته بمقرر قضائي مكتسب لقوة الشيء المقضي به.»', 'دستور 2011، الفصل 119', true),
  ('const-art-120', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «لكل شخص الحق في محاكمة عادلة، وفي حكم يصدر داخل أجل معقول»؟', '["الفصل 119", "الفصل 120", "الفصل 121", "الفصل 122"]'::jsonb, 1, 'الفصل 120 من دستور 2011 ينص على: «لكل شخص الحق في محاكمة عادلة، وفي حكم يصدر داخل أجل معقول. حقوق الدفاع مضمونة أمام جميع المحاكم.»', 'دستور 2011، الفصل 120', true),
  ('const-art-121', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يكون التقاضي مجانيا في الحالات المنصوص عليها قانونا لمن لا يتوفر على موارد كافية للتقاضي»؟', '["الفصل 120", "الفصل 121", "الفصل 122", "الفصل 123"]'::jsonb, 1, 'الفصل 121 من دستور 2011 ينص على: «يكون التقاضي مجانيا في الحالات المنصوص عليها قانونا لمن لا يتوفر على موارد كافية للتقاضي.»', 'دستور 2011، الفصل 121', true),
  ('const-art-122', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يحق لكل من تضرر من خطأ قضائي الحصول على تعويض تتحمله الدولة»؟', '["الفصل 121", "الفصل 122", "الفصل 123", "الفصل 124"]'::jsonb, 1, 'الفصل 122 من دستور 2011 ينص على: «يحق لكل من تضرر من خطأ قضائي الحصول على تعويض تتحمله الدولة.»', 'دستور 2011، الفصل 122', true),
  ('const-art-123', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تكون الجلسات علنية ما عدا في الحالات التي يقرر فيها القانون خلاف ذلك»؟', '["الفصل 122", "الفصل 123", "الفصل 124", "الفصل 125"]'::jsonb, 1, 'الفصل 123 من دستور 2011 ينص على: «تكون الجلسات علنية ما عدا في الحالات التي يقرر فيها القانون خلاف ذلك.»', 'دستور 2011، الفصل 123', true),
  ('const-art-124', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تصدر الأحكام وتنفذ باسم الملك وطبقا للقانون»؟', '["الفصل 123", "الفصل 124", "الفصل 125", "الفصل 126"]'::jsonb, 1, 'الفصل 124 من دستور 2011 ينص على: «تصدر الأحكام وتنفذ باسم الملك وطبقا للقانون.»', 'دستور 2011، الفصل 124', true),
  ('const-art-125', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تكون الأحكام معللة وتصدر في جلسة علنية، وفق الشروط المنصوص عليها في القانون»؟', '["الفصل 124", "الفصل 125", "الفصل 126", "الفصل 127"]'::jsonb, 1, 'الفصل 125 من دستور 2011 ينص على: «تكون الأحكام معللة وتصدر في جلسة علنية، وفق الشروط المنصوص عليها في القانون.»', 'دستور 2011، الفصل 125', true),
  ('const-art-126', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «الأحكام النهائية الصادرة عن القضاء ملزمة للجميع»؟', '["الفصل 125", "الفصل 126", "الفصل 127", "الفصل 128"]'::jsonb, 1, 'الفصل 126 من دستور 2011 ينص على: «الأحكام النهائية الصادرة عن القضاء ملزمة للجميع. يجب على السلطات العمومية تقديم المساعدة اللازمة أثناء المحاكمة، إذا صدر الأمر إليها بذلك، ويجب عليها المساعدة على تنفيذ الأحكام.»', 'دستور 2011، الفصل 126', true),
  ('const-art-127', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تُحدث المحاكم العادية والمتخصصة بمقتضى القانون»؟', '["الفصل 126", "الفصل 127", "الفصل 128", "الفصل 129"]'::jsonb, 1, 'الفصل 127 من دستور 2011 ينص على: «تُحدث المحاكم العادية والمتخصصة بمقتضى القانون. لا يمكن إحداث محاكم استثنائية.»', 'دستور 2011، الفصل 127', true),
  ('const-art-128', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تعمل الشرطة القضائية تحت سلطة النيابة العامة وقضاة التحقيق، في كل ما يتعلق بالأبحاث والتحريات الضرورية في شأن الجرائم وضبط مرتكبيها ولإثبات الحقيقة»؟', '["الفصل 127", "الفصل 128", "الفصل 129", "الفصل 130"]'::jsonb, 1, 'الفصل 128 من دستور 2011 ينص على: «تعمل الشرطة القضائية تحت سلطة النيابة العامة وقضاة التحقيق، في كل ما يتعلق بالأبحاث والتحريات الضرورية في شأن الجرائم وضبط مرتكبيها ولإثبات الحقيقة. الباب الثامن: المحكمة الدستورية»', 'دستور 2011، الفصل 128', true),
  ('const-art-129', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تُحدث محكمة دستورية»؟', '["الفصل 128", "الفصل 129", "الفصل 130", "الفصل 131"]'::jsonb, 1, 'الفصل 129 من دستور 2011 ينص على: «تُحدث محكمة دستورية.»', 'دستور 2011، الفصل 129', true),
  ('const-art-130', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تتألف المحكمة الدستورية من اثني عشر عضوا، يعينون لمدة تسع سنوات غير قابلة للتجديد، ستة أعضاء يعينهم الملك، من بينهم عضو يقترحه الأمين العام للمجلس العلمي الأعلى، وستة أعضاء يُنتخب نصفهم من قبل مجلس النواب، وينتخب النصف الآخر من قبل مجلس المستشارين من بين»؟', '["الفصل 129", "الفصل 130", "الفصل 131", "الفصل 132"]'::jsonb, 1, 'الفصل 130 من دستور 2011 ينص على: «تتألف المحكمة الدستورية من اثني عشر عضوا، يعينون لمدة تسع سنوات غير قابلة للتجديد، ستة أعضاء يعينهم الملك، من بينهم عضو يقترحه الأمين العام للمجلس العلمي الأعلى، وستة أعضاء يُنتخب نصفهم من قبل مجلس النواب، وينتخب النصف الآخر من قبل مجلس المستشارين من بين المترشحين الذين يقدمهم مكتب كل مجلس، وذلك بعد التصويت بالاقتراع السري وبأغلبية ثلثي الأعضاء الذين يتألف منهم كل مجلس. إذا تعذر على المجلسين أو على أحدهما انتخاب هؤلاء الأعضاء، داخل الأجل القانوني للتجديد، تمارس المحكمة اختصاصاتها، وتصدر قراراتها، وفق نصاب لا يحتسب فيه الأعضاء الذين لم يقع بعد انتخابهم. يتم كل ثلاث سنوات تجديد ثلث كل فئة من أعضاء المحكمة الدستورية. يعين الملك رئيس المحكمة الدستورية من بين الأعضاء الذين تتألف منهم. يختار أعضاء المحكمة الدستورية من بين الشخصيات المتوفرة على تكوين عال في مجال القانون، وعلى كفاءة قضائية أو فقهية أو إدارية، والذين مارسوا مهنتهم لمدة تفوق خمس عشرة سنة، والمشهود لهم بالتجرد والنزاهة.»', 'دستور 2011، الفصل 130', true),
  ('const-art-131', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يحدد قانون تنظيمي قواعد تنظيم المحكمة الدستورية وسيرها والإجراءات المتبعة أمامها، ووضعية أعضائها»؟', '["الفصل 130", "الفصل 131", "الفصل 132", "الفصل 133"]'::jsonb, 1, 'الفصل 131 من دستور 2011 ينص على: «يحدد قانون تنظيمي قواعد تنظيم المحكمة الدستورية وسيرها والإجراءات المتبعة أمامها، ووضعية أعضائها. يحدد القانون التنظيمي أيضا المهام التي لا يجوز الجمع بينها وبين عضوية المحكمة الدستورية، خاصة ما يتعلق منها بالمهن الحرة، وطريقة إجراء التجديدين الأولين لثلث أعضائها، وكيفيات تعيين من يحل محل أعضائها الذين استحال عليهم القيام بمهامهم، أو استقالوا أو توفوا أثناء مدة عضويتهم.»', 'دستور 2011، الفصل 131', true),
  ('const-art-132', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تمارس المحكمة الدستورية الاختصاصات المسندة إليها بفصول الدستور، وبأحكام القوانين التنظيمية، وتبت بالإضافة إلى ذلك في صحة انتخاب أعضاء البرلمان وعمليات الاستفتاء»؟', '["الفصل 131", "الفصل 132", "الفصل 133", "الفصل 134"]'::jsonb, 1, 'الفصل 132 من دستور 2011 ينص على: «تمارس المحكمة الدستورية الاختصاصات المسندة إليها بفصول الدستور، وبأحكام القوانين التنظيمية، وتبت بالإضافة إلى ذلك في صحة انتخاب أعضاء البرلمان وعمليات الاستفتاء. تحال إلى المحكمة الدستورية القوانين التنظيمية قبل إصدار الأمر بتنفيذها، والأنظمة الداخلية لكل من مجلس النواب ومجلس المستشارين قبل الشروع في تطبيقها لتبت في مطابقتها للدستور. يمكن للملك، وكذا لكل من رئيس الحكومة، أو رئيس مجلس النواب، أو رئيس مجلس المستشارين، أو خمس أعضاء مجلس النواب، أو أربعين عضوا من أعضاء مجلس المستشارين أن يحيلوا القوانين، قبل إصدار الأمر بتنفيذها، إلى المحكمة الدستورية، لتبت في مطابقتها للدستور. تبت المحكمة الدستورية في الحالات المنصوص عليها في الفقرتين الثانية والثالثة من هذا الفصل داخل أجل شهر من تاريخ الإحالة. غير أن هذا الأجل يخفض في حالة الاستعجال إلى ثمانية أيام، بطلب من الحكومة. تؤدي الإحالة إلى المحكمة الدستورية في هذه الحالات، إلى وقف سريان أجل إصدار الأمر بالتنفيذ. تبت المحكمة الدستورية في الطعون المتعلقة بانتخاب أعضاء البرلمان، داخل أجل سنة، ابتداء من تاريخ انقضاء أجل تقديم الطعون إليها. غير أن للمحكمة تجاوز هذا الأجل بموجب قرار معلل، إذا استوجب ذلك عدد الطعون المرفوعة إليها، أو استلزم ذلك الطعن المقدم إليها.»', 'دستور 2011، الفصل 132', true),
  ('const-art-133', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تختص المحكمة الدستورية بالنظر في كل دفع متعلق بعدم دستورية قانون، أثير أثناء النظر في قضية، وذلك إذا دفع أحد الأطراف بأن القانون، الذي سيطبق في النزاع، يمس بالحقوق وبالحريات التي يضمنها الدستور»؟', '["الفصل 132", "الفصل 133", "الفصل 134", "الفصل 135"]'::jsonb, 1, 'الفصل 133 من دستور 2011 ينص على: «تختص المحكمة الدستورية بالنظر في كل دفع متعلق بعدم دستورية قانون، أثير أثناء النظر في قضية، وذلك إذا دفع أحد الأطراف بأن القانون، الذي سيطبق في النزاع، يمس بالحقوق وبالحريات التي يضمنها الدستور. يحدد قانون تنظيمي شروط وإجراءات تطبيق هذا الفصل.»', 'دستور 2011، الفصل 133', true),
  ('const-art-134', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «لا يمكن إصدار الأمر بتنفيذ مقتضى تم التصريح بعدم دستوريته على أساس الفصل 132 من هذا الدستور، ولا تطبيقه، وينسخ كل مقتضى تم التصريح بعدم دستوريته على أساس الفصل 133 من الدستور، ابتداء من التاريخ الذي حددته المحكمة الدستورية في قرارها»؟', '["الفصل 133", "الفصل 134", "الفصل 135", "الفصل 136"]'::jsonb, 1, 'الفصل 134 من دستور 2011 ينص على: «لا يمكن إصدار الأمر بتنفيذ مقتضى تم التصريح بعدم دستوريته على أساس الفصل 132 من هذا الدستور، ولا تطبيقه، وينسخ كل مقتضى تم التصريح بعدم دستوريته على أساس الفصل 133 من الدستور، ابتداء من التاريخ الذي حددته المحكمة الدستورية في قرارها. لا تقبل قرارات المحكمة الدستورية أي طريق من طرق الطعن، وتلزم كل السلطات العامة وجميع الجهات الإدارية والقضائية. الباب التاسع: الجهات والجماعات الترابية الأخرى»', 'دستور 2011، الفصل 134', true),
  ('const-art-135', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «الجماعات الترابية للمملكة هي الجهات والعمالات والأقاليم والجماعات»؟', '["الفصل 134", "الفصل 135", "الفصل 136", "الفصل 137"]'::jsonb, 1, 'الفصل 135 من دستور 2011 ينص على: «الجماعات الترابية للمملكة هي الجهات والعمالات والأقاليم والجماعات. الجماعات الترابية أشخاص اعتبارية، خاضعة للقانون العام، تسير شؤونها بكيفية ديمقراطية. تنتخب مجالس الجهات والجماعات بالاقتراع العام المباشر. تحدث كل جماعة ترابية أخرى بالقانون، ويمكن أن تحل عند الاقتضاء، محل جماعة ترابية أو أكثر، من تلك المنصوص عليها في الفقرة الأولى من هذا الفصل.»', 'دستور 2011، الفصل 135', true),
  ('const-art-136', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يرتكز التنظيم الجهوي والترابي على مبادئ التدبير الحر، وعلى التعاون والتضامن؛ ويؤمن مشاركة السكان المعنيين في تدبير شؤونهم، والرفع من مساهمتهم في التنمية البشرية المندمجة والمستدامة»؟', '["الفصل 135", "الفصل 136", "الفصل 137", "الفصل 138"]'::jsonb, 1, 'الفصل 136 من دستور 2011 ينص على: «يرتكز التنظيم الجهوي والترابي على مبادئ التدبير الحر، وعلى التعاون والتضامن؛ ويؤمن مشاركة السكان المعنيين في تدبير شؤونهم، والرفع من مساهمتهم في التنمية البشرية المندمجة والمستدامة.»', 'دستور 2011، الفصل 136', true),
  ('const-art-137', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تساهم الجهات والجماعات الترابية الأخرى في تفعيل السياسة العامة للدولة، وفي إعداد السياسات الترابية، من خلال ممثليها في مجلس المستشارين»؟', '["الفصل 136", "الفصل 137", "الفصل 138", "الفصل 139"]'::jsonb, 1, 'الفصل 137 من دستور 2011 ينص على: «تساهم الجهات والجماعات الترابية الأخرى في تفعيل السياسة العامة للدولة، وفي إعداد السياسات الترابية، من خلال ممثليها في مجلس المستشارين.»', 'دستور 2011، الفصل 137', true),
  ('const-art-138', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يقوم رؤساء مجالس الجهات، ورؤساء مجالس الجماعات الترابية الأخرى، بتنفيذ مداولات هذه المجالس ومقرراتها»؟', '["الفصل 137", "الفصل 138", "الفصل 139", "الفصل 140"]'::jsonb, 1, 'الفصل 138 من دستور 2011 ينص على: «يقوم رؤساء مجالس الجهات، ورؤساء مجالس الجماعات الترابية الأخرى، بتنفيذ مداولات هذه المجالس ومقرراتها.»', 'دستور 2011، الفصل 138', true),
  ('const-art-139', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تضع مجالس الجهات، والجماعات الترابية الأخرى، آليات تشاركية للحوار والتشاور، لتيسير مساهمة المواطنات والمواطنين والجمعيات في إعداد برامج التنمية وتتبعها»؟', '["الفصل 138", "الفصل 139", "الفصل 140", "الفصل 141"]'::jsonb, 1, 'الفصل 139 من دستور 2011 ينص على: «تضع مجالس الجهات، والجماعات الترابية الأخرى، آليات تشاركية للحوار والتشاور، لتيسير مساهمة المواطنات والمواطنين والجمعيات في إعداد برامج التنمية وتتبعها. يُمكن للمواطنات والمواطنين والجمعيات تقديم عرائض، الهدف منها مطالبة المجلس بإدراج نقطة تدخل في اختصاصه ضمن جدول أعماله.»', 'دستور 2011، الفصل 139', true),
  ('const-art-140', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «للجماعات الترابية، وبناء على مبدأ التفريع، اختصاصات ذاتية واختصاصات مشتركة مع الدولة واختصاصات منقولة إليها من هذه الأخيرة»؟', '["الفصل 139", "الفصل 140", "الفصل 141", "الفصل 142"]'::jsonb, 1, 'الفصل 140 من دستور 2011 ينص على: «للجماعات الترابية، وبناء على مبدأ التفريع، اختصاصات ذاتية واختصاصات مشتركة مع الدولة واختصاصات منقولة إليها من هذه الأخيرة. تتوفر الجهات والجماعات الترابية الأخرى، في مجالات اختصاصاتها، وداخل دائرتها الترابية، على سلطة تنظيمية لممارسة صلاحياتها.»', 'دستور 2011، الفصل 140', true),
  ('const-art-141', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تتوفر الجهات والجماعات الترابية الأخرى، على موارد مالية ذاتية، وموارد مالية مرصودة من قبل الدولة»؟', '["الفصل 140", "الفصل 141", "الفصل 142", "الفصل 143"]'::jsonb, 1, 'الفصل 141 من دستور 2011 ينص على: «تتوفر الجهات والجماعات الترابية الأخرى، على موارد مالية ذاتية، وموارد مالية مرصودة من قبل الدولة. كل اختصاص تنقله الدولة إلى الجهات والجماعات الترابية الأخرى يكون مقترنا بتحويل الموارد المطابقة له.»', 'دستور 2011، الفصل 141', true),
  ('const-art-142', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يُحدث لفترة معينة ولفائدة الجهات صندوق للتأهيل الاجتماعي، يهدف إلى سد العجز في مجالات التنمية البشرية، والبنيات التحتية الأساسية والتجهيزات»؟', '["الفصل 141", "الفصل 142", "الفصل 143", "الفصل 144"]'::jsonb, 1, 'الفصل 142 من دستور 2011 ينص على: «يُحدث لفترة معينة ولفائدة الجهات صندوق للتأهيل الاجتماعي، يهدف إلى سد العجز في مجالات التنمية البشرية، والبنيات التحتية الأساسية والتجهيزات. يُحدث أيضا صندوق للتضامن بين الجهات، بهدف التوزيع المتكافئ للموارد، قصد التقليص من التفاوتات بينها.»', 'دستور 2011، الفصل 142', true),
  ('const-art-143', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «لا يجوز لأي جماعة ترابية أن تمارس وصايتها على جماعة أخرى»؟', '["الفصل 142", "الفصل 143", "الفصل 144", "الفصل 145"]'::jsonb, 1, 'الفصل 143 من دستور 2011 ينص على: «لا يجوز لأي جماعة ترابية أن تمارس وصايتها على جماعة أخرى. تتبوأ الجهة، تحت إشراف رئيس مجلسها، مكانة الصدارة بالنسبة للجماعات الترابية الأخرى، في عمليات إعداد وتتبع برامج التنمية الجهوية، والتصاميم الجهوية لإعداد التراب، في نطاق احترام الاختصاصات الذاتية لهذه الجماعات الترابية. كلما تعلق الأمر بإنجاز مشروع يتطلب تعاون عدة جماعات ترابية، فإن هذه الأخيرة تتفق على كيفيات تعاونها.»', 'دستور 2011، الفصل 143', true),
  ('const-art-144', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يمكن للجماعات الترابية تأسيس مجموعات فيما بينها، من أجل التعاضد في الوسائل والبرامج»؟', '["الفصل 143", "الفصل 144", "الفصل 145", "الفصل 146"]'::jsonb, 1, 'الفصل 144 من دستور 2011 ينص على: «يمكن للجماعات الترابية تأسيس مجموعات فيما بينها، من أجل التعاضد في الوسائل والبرامج.»', 'دستور 2011، الفصل 144', true),
  ('const-art-145', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يمثل ولاة الجهات وعمال الأقاليم والعمالات، السلطة المركزية في الجماعات الترابية»؟', '["الفصل 144", "الفصل 145", "الفصل 146", "الفصل 147"]'::jsonb, 1, 'الفصل 145 من دستور 2011 ينص على: «يمثل ولاة الجهات وعمال الأقاليم والعمالات، السلطة المركزية في الجماعات الترابية. يعمل الولاة والعمال، باسم الحكومة، على تأمين تطبيق القانون، وتنفيذ النصوص التنظيمية للحكومة ومقرراتها، كما يمارسون المراقبة الإدارية. يساعد الولاة والعمال رؤساء الجماعات الترابية، وخاصة رؤساء المجالس الجهوية، على تنفيذ المخططات والبرامج التنموية. يقوم الولاة والعمال، تحت سلطة الوزراء المعنيين، بتنسيق أنشطة المصالح اللاممركزة للإدارة المركزية، ويسهرون على حسن سيرها.»', 'دستور 2011، الفصل 145', true),
  ('const-art-146', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تحدد بقانون تنظيمي بصفة خاصة: شروط تدبير الجهات والجماعات الترابية الأخرى لشؤونها بكيفية ديمقراطية، وعدد أعضاء مجالسها، والقواعد المتعلقة بأهلية الترشيح، وحالات التنافي، وحالات منع الجمع بين الانتدابات، وكذا النظام الانتخابي، وأحكام تحسين تمثيلية النساء داخل»؟', '["الفصل 145", "الفصل 146", "الفصل 147", "الفصل 148"]'::jsonb, 1, 'الفصل 146 من دستور 2011 ينص على: «تحدد بقانون تنظيمي بصفة خاصة: شروط تدبير الجهات والجماعات الترابية الأخرى لشؤونها بكيفية ديمقراطية، وعدد أعضاء مجالسها، والقواعد المتعلقة بأهلية الترشيح، وحالات التنافي، وحالات منع الجمع بين الانتدابات، وكذا النظام الانتخابي، وأحكام تحسين تمثيلية النساء داخل المجالس المذكورة؛ شروط تنفيذ رؤساء مجالس الجهات ورؤساء مجالس الجماعات الترابية الأخرى لمداولات هذه المجالس ومقرراتها، طبقا للفصل 138؛ شروط تقديم العرائض المنصوص عليها في الفصل 139، من قبل المواطنات والمواطنين والجمعيات؛ الاختصاصات الذاتية لفائدة الجهات والجماعات الترابية الأخرى، والاختصاصات المشتركة بينها وبين الدولة والاختصاصات المنقولة إليها من هذه الأخيرة طبقا للفصل 140؛ النظام المالي للجهات والجماعات الترابية الأخرى؛ مصدر الموارد المالية للجهات وللجماعات الترابية الأخرى، المنصوص عليها في الفصل 141؛ موارد وكيفيات تسيير كل من صندوق التأهيل الاجتماعي وصندوق التضامن بين الجهات المنصوص عليهما في الفصل 142؛ شروط وكيفيات تأسيس المجموعات المشار إليها في الفصل 144؛ المقتضيات الهادفة إلى تشجيع تنمية التعاون بين الجماعات، وكذا الآليات الرامية إلى ضمان تكييف تطور التنظيم الترابي في هذا الاتجاه؛ قواعد الحكامة المتعلقة بحسن تطبيق مبدإ التدبير الحر، وكذا مراقبة تدبير الصناديق والبرامج وتقييم الأعمال وإجراءات المحاسبة. الباب العاشر: المجلس الأعلى للحسابات»', 'دستور 2011، الفصل 146', true),
  ('const-art-147', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «المجلس الأعلى للحسابات هو الهيأة العليا لمراقبة المالية العمومية بالمملكة، ويضمن الدستور استقلاله»؟', '["الفصل 146", "الفصل 147", "الفصل 148", "الفصل 149"]'::jsonb, 1, 'الفصل 147 من دستور 2011 ينص على: «المجلس الأعلى للحسابات هو الهيأة العليا لمراقبة المالية العمومية بالمملكة، ويضمن الدستور استقلاله. يمارس المجلس الأعلى للحسابات مهمة تدعيم وحماية مبادئ وقيم الحكامة الجيدة والشفافية والمحاسبة، بالنسبة للدولة والأجهزة العمومية. يتولى المجلس الأعلى للحسابات ممارسة المراقبة العليا على تنفيذ قوانين المالية. ويتحقق من سلامة العمليات المتعلقة بمداخيل ومصاريف الأجهزة الخاضعة لمراقبته بمقتضى القانون، ويقيم كيفية تدبيرها لشؤونها، ويتخذ، عند الاقتضاء، عقوبات عن كل إخلال بالقواعد السارية على العمليات المذكورة. تُناط بالمجلس الأعلى للحسابات مهمة مراقبة وتتبع التصريح بالممتلكات، وتدقيق حسابات الأحزاب السياسية، وفحص النفقات المتعلقة بالعمليات الانتخابية.»', 'دستور 2011، الفصل 147', true),
  ('const-art-148', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يقدم المجلس الأعلى للحسابات مساعدته للبرلمان في المجالات المتعلقة بمراقبة المالية العامة؛ ويجيب عن الأسئلة والاستشارات المرتبطة بوظائف البرلمان في التشريع والمراقبة والتقييم المتعلقة بالمالية العامة»؟', '["الفصل 147", "الفصل 148", "الفصل 149", "الفصل 150"]'::jsonb, 1, 'الفصل 148 من دستور 2011 ينص على: «يقدم المجلس الأعلى للحسابات مساعدته للبرلمان في المجالات المتعلقة بمراقبة المالية العامة؛ ويجيب عن الأسئلة والاستشارات المرتبطة بوظائف البرلمان في التشريع والمراقبة والتقييم المتعلقة بالمالية العامة. يقدم المجلس الأعلى للحسابات مساعدته للهيئات القضائية. يقدم المجلس الأعلى للحسابات مساعدته للحكومة، في الميادين التي تدخل في نطاق اختصاصاته بمقتضى القانون. ينشر المجلس الأعلى للحسابات جميع أعماله، بما فيها التقارير الخاصة والمقررات القضائية. يرفع المجلس الأعلى للحسابات للملك تقريرا سنويا، يتضمن بيانا عن جميع أعماله، ويوجهه أيضا إلى رئيس الحكومة، وإلى رئيسي مجلسي البرلمان، وينشر بالجريدة الرسمية للمملكة. يُقدم الرئيس الأول للمجلس عرضا عن أعمال المجلس الأعلى للحسابات أمام البرلمان، ويكون متبوعا بمناقشة.»', 'دستور 2011، الفصل 148', true),
  ('const-art-149', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تتولى المجالس الجهوية للحسابات مراقبة حسابات الجهات والجماعات الترابية الأخرى وهيئاتها، وكيفية قيامها بتدبير شؤونها»؟', '["الفصل 148", "الفصل 149", "الفصل 150", "الفصل 151"]'::jsonb, 1, 'الفصل 149 من دستور 2011 ينص على: «تتولى المجالس الجهوية للحسابات مراقبة حسابات الجهات والجماعات الترابية الأخرى وهيئاتها، وكيفية قيامها بتدبير شؤونها. وتعاقب عند الاقتضاء، عن كل إخلال بالقواعد السارية على العمليات المذكورة.»', 'دستور 2011، الفصل 149', true),
  ('const-art-150', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يحدد القانون اختصاصات المجلس الأعلى للحسابات والمجالس الجهوية للحسابات، وقواعد تنظيمها، وكيفيات تسييرها»؟', '["الفصل 149", "الفصل 150", "الفصل 151", "الفصل 152"]'::jsonb, 1, 'الفصل 150 من دستور 2011 ينص على: «يحدد القانون اختصاصات المجلس الأعلى للحسابات والمجالس الجهوية للحسابات، وقواعد تنظيمها، وكيفيات تسييرها. الباب الحادي عشر: المجلس الاقتصادي والاجتماعي والبيئي»', 'دستور 2011، الفصل 150', true),
  ('const-art-151', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يحدث مجلس اقتصادي واجتماعي وبيئي»؟', '["الفصل 150", "الفصل 151", "الفصل 152", "الفصل 153"]'::jsonb, 1, 'الفصل 151 من دستور 2011 ينص على: «يحدث مجلس اقتصادي واجتماعي وبيئي.»', 'دستور 2011، الفصل 151', true),
  ('const-art-152', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «للحكومة ولمجلس النواب ولمجلس المستشارين أن يستشيروا المجلس الاقتصادي والاجتماعي والبيئي في جميع القضايا، التي لها طابع اقتصادي واجتماعي وبيئي»؟', '["الفصل 151", "الفصل 152", "الفصل 153", "الفصل 154"]'::jsonb, 1, 'الفصل 152 من دستور 2011 ينص على: «للحكومة ولمجلس النواب ولمجلس المستشارين أن يستشيروا المجلس الاقتصادي والاجتماعي والبيئي في جميع القضايا، التي لها طابع اقتصادي واجتماعي وبيئي. يدلي المجلس برأيه في التوجهات العامة للاقتصاد الوطني والتنمية المستدامة.»', 'دستور 2011، الفصل 152', true),
  ('const-art-153', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يحدد قانون تنظيمي تأليف المجلس الاقتصادي والاجتماعي والبيئي، وتنظيمه، وصلاحياته، وكيفيات تسييره»؟', '["الفصل 152", "الفصل 153", "الفصل 154", "الفصل 155"]'::jsonb, 1, 'الفصل 153 من دستور 2011 ينص على: «يحدد قانون تنظيمي تأليف المجلس الاقتصادي والاجتماعي والبيئي، وتنظيمه، وصلاحياته، وكيفيات تسييره. الباب الثاني عشر: الحكامة الجيدة مبادئ عامة»', 'دستور 2011، الفصل 153', true),
  ('const-art-154', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يتم تنظيم المرافق العمومية على أساس المساواة بين المواطنات والمواطنين في الولوج إليها، والإنصاف في تغطية التراب الوطني، والاستمرارية في أداء الخدمات»؟', '["الفصل 153", "الفصل 154", "الفصل 155", "الفصل 156"]'::jsonb, 1, 'الفصل 154 من دستور 2011 ينص على: «يتم تنظيم المرافق العمومية على أساس المساواة بين المواطنات والمواطنين في الولوج إليها، والإنصاف في تغطية التراب الوطني، والاستمرارية في أداء الخدمات. تخضع المرافق العمومية لمعايير الجودة والشفافية والمحاسبة والمسؤولية، وتخضع في تسييرها للمبادئ والقيم الديمقراطية التي أقرها الدستور.»', 'دستور 2011، الفصل 154', true),
  ('const-art-155', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يمارس أعوان المرافق العمومية وظائفهم وفق مبادئ احترام القانون والحياد والشفافية والنزاهة والمصلحة العامة»؟', '["الفصل 154", "الفصل 155", "الفصل 156", "الفصل 157"]'::jsonb, 1, 'الفصل 155 من دستور 2011 ينص على: «يمارس أعوان المرافق العمومية وظائفهم وفق مبادئ احترام القانون والحياد والشفافية والنزاهة والمصلحة العامة.»', 'دستور 2011، الفصل 155', true),
  ('const-art-156', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تتلقى المرافق العمومية ملاحظات مرتفقيها، واقتراحاتهم وتظلماتهم، وتؤمن تتبعها»؟', '["الفصل 155", "الفصل 156", "الفصل 157", "الفصل 158"]'::jsonb, 1, 'الفصل 156 من دستور 2011 ينص على: «تتلقى المرافق العمومية ملاحظات مرتفقيها، واقتراحاتهم وتظلماتهم، وتؤمن تتبعها. تقدم المرافق العمومية الحساب عن تدبيرها للأموال العمومية، طبقا للقوانين الجاري بها العمل، وتخضع في هذا الشأن للمراقبة والتقييم.»', 'دستور 2011، الفصل 156', true),
  ('const-art-157', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يحدد ميثاق للمرافق العمومية قواعد الحكامة الجيدة المتعلقة بتسيير الإدارات العمومية والجهات والجماعات الترابية الأخرى والأجهزة العمومية»؟', '["الفصل 156", "الفصل 157", "الفصل 158", "الفصل 159"]'::jsonb, 1, 'الفصل 157 من دستور 2011 ينص على: «يحدد ميثاق للمرافق العمومية قواعد الحكامة الجيدة المتعلقة بتسيير الإدارات العمومية والجهات والجماعات الترابية الأخرى والأجهزة العمومية.»', 'دستور 2011، الفصل 157', true),
  ('const-art-158', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يجب على كل شخص، منتخبا كان أو معينا، يمارس مسؤولية عمومية، أن يقدم، طبقا للكيفيات المحددة في القانون، تصريحا كتابيا بالممتلكات والأصول التي في حيازته، بصفة مباشرة أو غير مباشرة، بمجرد تسلمه لمهامه، وخلال ممارستها، وعند انتهائها»؟', '["الفصل 157", "الفصل 158", "الفصل 159", "الفصل 160"]'::jsonb, 1, 'الفصل 158 من دستور 2011 ينص على: «يجب على كل شخص، منتخبا كان أو معينا، يمارس مسؤولية عمومية، أن يقدم، طبقا للكيفيات المحددة في القانون، تصريحا كتابيا بالممتلكات والأصول التي في حيازته، بصفة مباشرة أو غير مباشرة، بمجرد تسلمه لمهامه، وخلال ممارستها، وعند انتهائها.»', 'دستور 2011، الفصل 158', true),
  ('const-art-159', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تكون الهيئات المكلفة بالحكامة الجيدة مستقلة؛ وتستفيد من دعم أجهزة الدولة؛ ويمكن للقانون أن يُحدث عند الضرورة، علاوة على المؤسسات والهيئات المذكورة بعده، هيئات أخرى للضبط والحكامة الجيدة»؟', '["الفصل 158", "الفصل 159", "الفصل 160", "الفصل 161"]'::jsonb, 1, 'الفصل 159 من دستور 2011 ينص على: «تكون الهيئات المكلفة بالحكامة الجيدة مستقلة؛ وتستفيد من دعم أجهزة الدولة؛ ويمكن للقانون أن يُحدث عند الضرورة، علاوة على المؤسسات والهيئات المذكورة بعده، هيئات أخرى للضبط والحكامة الجيدة.»', 'دستور 2011، الفصل 159', true),
  ('const-art-160', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «على المؤسسات والهيئات المشار إليها في الفصول 161 إلى 170 من هذا الدستور تقديم تقرير عن أعمالها، مرة واحدة في السنة على الأقل، الذي يكون موضوع مناقشة من قبل البرلمان»؟', '["الفصل 159", "الفصل 160", "الفصل 161", "الفصل 162"]'::jsonb, 1, 'الفصل 160 من دستور 2011 ينص على: «على المؤسسات والهيئات المشار إليها في الفصول 161 إلى 170 من هذا الدستور تقديم تقرير عن أعمالها، مرة واحدة في السنة على الأقل، الذي يكون موضوع مناقشة من قبل البرلمان. مؤسسات وهيئات حماية الحقوق والحريات والحكامة الجيدة والتنمية البشرية والمستدامة والديمقراطية التشاركية — هيئات حماية حقوق الإنسان والنهوض بها»', 'دستور 2011، الفصل 160', true),
  ('const-art-161', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «المجلس الوطني لحقوق الإنسان مؤسسة وطنية تعددية ومستقلة، تتولى النظر في جميع القضايا المتعلقة بالدفاع عن حقوق الإنسان والحريات وحمايتها، وبضمان ممارستها الكاملة، والنهوض بها وبصيانة كرامة وحقوق وحريات المواطنات والمواطنين، أفرادا وجماعات، وذلك في نطاق الحرص»؟', '["الفصل 160", "الفصل 161", "الفصل 162", "الفصل 163"]'::jsonb, 1, 'الفصل 161 من دستور 2011 ينص على: «المجلس الوطني لحقوق الإنسان مؤسسة وطنية تعددية ومستقلة، تتولى النظر في جميع القضايا المتعلقة بالدفاع عن حقوق الإنسان والحريات وحمايتها، وبضمان ممارستها الكاملة، والنهوض بها وبصيانة كرامة وحقوق وحريات المواطنات والمواطنين، أفرادا وجماعات، وذلك في نطاق الحرص التام على احترام المرجعيات الوطنية والكونية في هذا المجال.»', 'دستور 2011، الفصل 161', true),
  ('const-art-162', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «الوسيط مؤسسة وطنية مستقلة ومتخصصة، مهمتها الدفاع عن الحقوق في نطاق العلاقات بين الإدارة والمرتفقين، والإسهام في ترسيخ سيادة القانون، وإشاعة مبادئ العدل والإنصاف، وقيم التخليق والشفافية في تدبير الإدارات والمؤسسات العمومية والجماعات الترابية والهيئات التي»؟', '["الفصل 161", "الفصل 162", "الفصل 163", "الفصل 164"]'::jsonb, 1, 'الفصل 162 من دستور 2011 ينص على: «الوسيط مؤسسة وطنية مستقلة ومتخصصة، مهمتها الدفاع عن الحقوق في نطاق العلاقات بين الإدارة والمرتفقين، والإسهام في ترسيخ سيادة القانون، وإشاعة مبادئ العدل والإنصاف، وقيم التخليق والشفافية في تدبير الإدارات والمؤسسات العمومية والجماعات الترابية والهيئات التي تمارس صلاحيات السلطة العمومية.»', 'دستور 2011، الفصل 162', true),
  ('const-art-163', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يتولى مجلس الجالية المغربية بالخارج، على الخصوص، إبداء آرائه حول توجهات السياسات العمومية التي تمكن المغاربة المقيمين بالخارج من تأمين الحفاظ على علاقات متينة مع هويتهم المغربية، وضمان حقوقهم وصيانة مصالحهم، وكذا المساهمة في التنمية البشرية والمستدامة في»؟', '["الفصل 162", "الفصل 163", "الفصل 164", "الفصل 165"]'::jsonb, 1, 'الفصل 163 من دستور 2011 ينص على: «يتولى مجلس الجالية المغربية بالخارج، على الخصوص، إبداء آرائه حول توجهات السياسات العمومية التي تمكن المغاربة المقيمين بالخارج من تأمين الحفاظ على علاقات متينة مع هويتهم المغربية، وضمان حقوقهم وصيانة مصالحهم، وكذا المساهمة في التنمية البشرية والمستدامة في وطنهم المغرب وتقدمه.»', 'دستور 2011، الفصل 163', true),
  ('const-art-164', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تسهر الهيأة المكلفة بالمناصفة ومحاربة جميع أشكال التمييز، المحدثة بموجب الفصل 19 من هذا الدستور، بصفة خاصة، على احترام الحقوق والحريات المنصوص عليها في الفصل المذكور، مع مراعاة الاختصاصات المسندة للمجلس الوطني لحقوق الإنسان»؟', '["الفصل 163", "الفصل 164", "الفصل 165", "الفصل 166"]'::jsonb, 1, 'الفصل 164 من دستور 2011 ينص على: «تسهر الهيأة المكلفة بالمناصفة ومحاربة جميع أشكال التمييز، المحدثة بموجب الفصل 19 من هذا الدستور، بصفة خاصة، على احترام الحقوق والحريات المنصوص عليها في الفصل المذكور، مع مراعاة الاختصاصات المسندة للمجلس الوطني لحقوق الإنسان. هيئات الحكامة الجيدة والتقنين»', 'دستور 2011، الفصل 164', true),
  ('const-art-165', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تتولى الهيأة العليا للاتصال السمعي البصري السهر على احترام التعبير التعددي لتيارات الرأي والفكر، والحق في المعلومة في الميدان السمعي البصري، وذلك في إطار احترام القيم الحضارية الأساسية وقوانين المملكة»؟', '["الفصل 164", "الفصل 165", "الفصل 166", "الفصل 167"]'::jsonb, 1, 'الفصل 165 من دستور 2011 ينص على: «تتولى الهيأة العليا للاتصال السمعي البصري السهر على احترام التعبير التعددي لتيارات الرأي والفكر، والحق في المعلومة في الميدان السمعي البصري، وذلك في إطار احترام القيم الحضارية الأساسية وقوانين المملكة.»', 'دستور 2011، الفصل 165', true),
  ('const-art-166', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «مجلس المنافسة هيأة مستقلة، مكلفة في إطار تنظيم منافسة حرة ومشروعة بضمان الشفافية والإنصاف في العلاقات الاقتصادية، خاصة من خلال تحليل وضبط وضعية المنافسة في الأسواق، ومراقبة الممارسات المنافية لها والممارسات التجارية غير المشروعة وعمليات التركيز الاقتصادي»؟', '["الفصل 165", "الفصل 166", "الفصل 167", "الفصل 168"]'::jsonb, 1, 'الفصل 166 من دستور 2011 ينص على: «مجلس المنافسة هيأة مستقلة، مكلفة في إطار تنظيم منافسة حرة ومشروعة بضمان الشفافية والإنصاف في العلاقات الاقتصادية، خاصة من خلال تحليل وضبط وضعية المنافسة في الأسواق، ومراقبة الممارسات المنافية لها والممارسات التجارية غير المشروعة وعمليات التركيز الاقتصادي والاحتكار.»', 'دستور 2011، الفصل 166', true),
  ('const-art-167', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تتولى الهيأة الوطنية للنزاهة والوقاية من الرشوة ومحاربتها، المحدثة بموجب الفصل 36، على الخصوص، مهام المبادرة والتنسيق والإشراف وضمان تتبع تنفيذ سياسات محاربة الفساد، وتلقي ونشر المعلومات في هذا المجال، والمساهمة في تخليق الحياة العامة، وترسيخ مبادئ الحكامة»؟', '["الفصل 166", "الفصل 167", "الفصل 168", "الفصل 169"]'::jsonb, 1, 'الفصل 167 من دستور 2011 ينص على: «تتولى الهيأة الوطنية للنزاهة والوقاية من الرشوة ومحاربتها، المحدثة بموجب الفصل 36، على الخصوص، مهام المبادرة والتنسيق والإشراف وضمان تتبع تنفيذ سياسات محاربة الفساد، وتلقي ونشر المعلومات في هذا المجال، والمساهمة في تخليق الحياة العامة، وترسيخ مبادئ الحكامة الجيدة، وثقافة المرفق العام، وقيم المواطنة المسؤولة. هيئات النهوض بالتنمية البشرية والمستدامة والديمقراطية التشاركية»', 'دستور 2011، الفصل 167', true),
  ('const-art-168', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يحدث مجلس أعلى للتربية والتكوين والبحث العلمي»؟', '["الفصل 167", "الفصل 168", "الفصل 169", "الفصل 170"]'::jsonb, 1, 'الفصل 168 من دستور 2011 ينص على: «يحدث مجلس أعلى للتربية والتكوين والبحث العلمي. المجلس هيأة استشارية، مهمتها إبداء الآراء حول كل السياسات العمومية، والقضايا الوطنية التي تهم التربية والتكوين والبحث العلمي، وكذا حول أهداف المرافق العمومية المكلفة بهذه الميادين وسيرها. كما يساهم في تقييم السياسات والبرامج العمومية في هذا المجال.»', 'دستور 2011، الفصل 168', true),
  ('const-art-169', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يتولى المجلس الاستشاري للأسرة والطفولة، المحدث بموجب الفصل 32 من هذا الدستور، مهمة تأمين تتبع وضعية الأسرة والطفولة، وإبداء آراء حول المخططات الوطنية المتعلقة بهذه الميادين، وتنشيط النقاش العمومي حول السياسة العمومية في مجال الأسرة، وضمان تتبع وإنجاز البرامج»؟', '["الفصل 168", "الفصل 169", "الفصل 170", "الفصل 171"]'::jsonb, 1, 'الفصل 169 من دستور 2011 ينص على: «يتولى المجلس الاستشاري للأسرة والطفولة، المحدث بموجب الفصل 32 من هذا الدستور، مهمة تأمين تتبع وضعية الأسرة والطفولة، وإبداء آراء حول المخططات الوطنية المتعلقة بهذه الميادين، وتنشيط النقاش العمومي حول السياسة العمومية في مجال الأسرة، وضمان تتبع وإنجاز البرامج الوطنية، المقدمة من قبل مختلف القطاعات، والهياكل والهيئات المختصة.»', 'دستور 2011، الفصل 169', true),
  ('const-art-170', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يعتبر المجلس الاستشاري للشباب والعمل الجمعوي، المحدث بموجب الفصل 33 من هذا الدستور، هيأة استشارية في ميادين حماية الشباب والنهوض بتطوير الحياة الجمعوية»؟', '["الفصل 169", "الفصل 170", "الفصل 171", "الفصل 172"]'::jsonb, 1, 'الفصل 170 من دستور 2011 ينص على: «يعتبر المجلس الاستشاري للشباب والعمل الجمعوي، المحدث بموجب الفصل 33 من هذا الدستور، هيأة استشارية في ميادين حماية الشباب والنهوض بتطوير الحياة الجمعوية. وهو مكلف بدراسة وتتبع المسائل التي تهم هذه الميادين، وتقديم اقتراحات حول كل موضوع اقتصادي واجتماعي وثقافي، يهم مباشرة النهوض بأوضاع الشباب والعمل الجمعوي، وتنمية طاقاتهم الإبداعية، وتحفيزهم على الانخراط في الحياة الوطنية، بروح المواطنة المسؤولة.»', 'دستور 2011، الفصل 170', true),
  ('const-art-171', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يحدد بقوانين تأليف وصلاحيات وتنظيم وقواعد سير المؤسسات والهيئات المنصوص عليها في الفصول 161 إلى 170 من هذا الدستور، وكذا حالات التنافي عند الاقتضاء»؟', '["الفصل 170", "الفصل 171", "الفصل 172", "الفصل 173"]'::jsonb, 1, 'الفصل 171 من دستور 2011 ينص على: «يحدد بقوانين تأليف وصلاحيات وتنظيم وقواعد سير المؤسسات والهيئات المنصوص عليها في الفصول 161 إلى 170 من هذا الدستور، وكذا حالات التنافي عند الاقتضاء. الباب الثالث عشر: مراجعة الدستور»', 'دستور 2011، الفصل 171', true),
  ('const-art-172', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «للملك ولرئيس الحكومة ولمجلس النواب ولمجلس المستشارين، حق اتخاذ المبادرة قصد مراجعة الدستور»؟', '["الفصل 171", "الفصل 172", "الفصل 173", "الفصل 174"]'::jsonb, 1, 'الفصل 172 من دستور 2011 ينص على: «للملك ولرئيس الحكومة ولمجلس النواب ولمجلس المستشارين، حق اتخاذ المبادرة قصد مراجعة الدستور. للملك أن يعرض مباشرة على الاستفتاء، المشروع الذي اتخذ المبادرة بشأنه.»', 'دستور 2011، الفصل 172', true),
  ('const-art-173', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «لا تصح الموافقة على مقترح مراجعة الدستور الذي يتقدم به عضو أو أكثر من أعضاء أحد مجلسي البرلمان، إلا بتصويت أغلبية ثلثي الأعضاء الذين يتألف منهم المجلس»؟', '["الفصل 172", "الفصل 173", "الفصل 174", "الفصل 175"]'::jsonb, 1, 'الفصل 173 من دستور 2011 ينص على: «لا تصح الموافقة على مقترح مراجعة الدستور الذي يتقدم به عضو أو أكثر من أعضاء أحد مجلسي البرلمان، إلا بتصويت أغلبية ثلثي الأعضاء الذين يتألف منهم المجلس. يُحال المقترح إلى المجلس الآخر، الذي يوافق عليه بنفس أغلبية ثلثي الأعضاء الذين يتألف منهم. يُعرض المقترح الذي يتقدم به رئيس الحكومة على المجلس الوزاري، بعد التداول بشأنه في مجلس الحكومة.»', 'دستور 2011، الفصل 173', true),
  ('const-art-174', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تُعرض مشاريع ومقترحات مراجعة الدستور، بمقتضى ظهير، على الشعب قصد الاستفتاء»؟', '["الفصل 173", "الفصل 174", "الفصل 175", "الفصل 176"]'::jsonb, 1, 'الفصل 174 من دستور 2011 ينص على: «تُعرض مشاريع ومقترحات مراجعة الدستور، بمقتضى ظهير، على الشعب قصد الاستفتاء. تكون المراجعة نهائية بعد إقرارها بالاستفتاء. للملك، بعد استشارة رئيس المحكمة الدستورية، أن يعرض بظهير، على البرلمان، مشروع مراجعة بعض مقتضيات الدستور. ويصادق البرلمان، المنعقد، بدعوة من الملك، في اجتماع مشترك لمجلسيه، على مشروع هذه المراجعة، بأغلبية ثلثي الأعضاء الذين يتألف منهم. يحدد النظام الداخلي لمجلس النواب كيفيات تطبيق هذا المقتضى. تراقب المحكمة الدستورية صحة إجراءات هذه المراجعة، وتعلن نتيجتها.»', 'دستور 2011، الفصل 174', true),
  ('const-art-175', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «لا يمكن أن تتناول المراجعة الأحكام المتعلقة بالدين الإسلامي، وبالنظام الملكي للدولة، وبالاختيار الديمقراطي للأمة، وبالمكتسبات في مجال الحريات والحقوق الأساسية المنصوص عليها في هذا الدستور»؟', '["الفصل 174", "الفصل 175", "الفصل 176", "الفصل 177"]'::jsonb, 1, 'الفصل 175 من دستور 2011 ينص على: «لا يمكن أن تتناول المراجعة الأحكام المتعلقة بالدين الإسلامي، وبالنظام الملكي للدولة، وبالاختيار الديمقراطي للأمة، وبالمكتسبات في مجال الحريات والحقوق الأساسية المنصوص عليها في هذا الدستور. الباب الرابع عشر: أحكام انتقالية وختامية»', 'دستور 2011، الفصل 175', true),
  ('const-art-176', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «إلى حين انتخاب مجلسي البرلمان، المنصوص عليهما في هذا الدستور، يستمر المجلسان القائمان حاليا في ممارسة صلاحياتهما، ليقوما على وجه الخصوص، بإقرار القوانين اللازمة لتنصيب مجلسي البرلمان الجديدين، وذلك دون إخلال بالأحكام المنصوص عليها في الفصل 51 من هذا الدستور»؟', '["الفصل 175", "الفصل 176", "الفصل 177", "الفصل 178"]'::jsonb, 1, 'الفصل 176 من دستور 2011 ينص على: «إلى حين انتخاب مجلسي البرلمان، المنصوص عليهما في هذا الدستور، يستمر المجلسان القائمان حاليا في ممارسة صلاحياتهما، ليقوما على وجه الخصوص، بإقرار القوانين اللازمة لتنصيب مجلسي البرلمان الجديدين، وذلك دون إخلال بالأحكام المنصوص عليها في الفصل 51 من هذا الدستور.»', 'دستور 2011، الفصل 176', true),
  ('const-art-177', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يستمر المجلس الدستوري القائم حاليا في ممارسة صلاحياته، إلى أن يتم تنصيب المحكمة الدستورية المنصوص عليها في هذا الدستور»؟', '["الفصل 176", "الفصل 177", "الفصل 178", "الفصل 179"]'::jsonb, 1, 'الفصل 177 من دستور 2011 ينص على: «يستمر المجلس الدستوري القائم حاليا في ممارسة صلاحياته، إلى أن يتم تنصيب المحكمة الدستورية المنصوص عليها في هذا الدستور.»', 'دستور 2011، الفصل 177', true),
  ('const-art-178', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «يستمر المجلس الأعلى للقضاء في ممارسة صلاحياته، إلى أن يتم تنصيب المجلس الأعلى للسلطة القضائية، المنصوص عليه في هذا الدستور»؟', '["الفصل 177", "الفصل 178", "الفصل 179", "الفصل 180"]'::jsonb, 1, 'الفصل 178 من دستور 2011 ينص على: «يستمر المجلس الأعلى للقضاء في ممارسة صلاحياته، إلى أن يتم تنصيب المجلس الأعلى للسلطة القضائية، المنصوص عليه في هذا الدستور.»', 'دستور 2011، الفصل 178', true),
  ('const-art-179', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «تظل النصوص المتعلقة بالمؤسسات والهيئات المذكورة في الباب الثاني عشر من هذا الدستور، وكذا تلك المتعلقة بالمجلس الاقتصادي والاجتماعي وبالمجلس الأعلى للتعليم، سارية المفعول، إلى حين تعويضها، طبقا لمقتضيات هذا الدستور»؟', '["الفصل 178", "الفصل 179", "الفصل 180", "الفصل 4"]'::jsonb, 1, 'الفصل 179 من دستور 2011 ينص على: «تظل النصوص المتعلقة بالمؤسسات والهيئات المذكورة في الباب الثاني عشر من هذا الدستور، وكذا تلك المتعلقة بالمجلس الاقتصادي والاجتماعي وبالمجلس الأعلى للتعليم، سارية المفعول، إلى حين تعويضها، طبقا لمقتضيات هذا الدستور.»', 'دستور 2011، الفصل 179', true),
  ('const-art-180', 'general', 'constitution-2011', 'general', 'medium', 'أي فصل من دستور 2011 ينص على: «مع مراعاة المقتضيات الانتقالية الواردة في هذا الباب، يُنسخ نص الدستور المراجع الصادر بتنفيذه الظهير الشريف رقم 1.96.157 المؤرخ في 23 من جمادى الأولى 1417 (7 أكتوبر 1996)»؟', '["الفصل 179", "الفصل 180", "الفصل 4", "الفصل 5"]'::jsonb, 1, 'الفصل 180 من دستور 2011 ينص على: «مع مراعاة المقتضيات الانتقالية الواردة في هذا الباب، يُنسخ نص الدستور المراجع الصادر بتنفيذه الظهير الشريف رقم 1.96.157 المؤرخ في 23 من جمادى الأولى 1417 (7 أكتوبر 1996). الفهرس الباب العنوان — الدستور (التصدير) الباب الأول أحكام عامة (الفصول 1–18) الباب الثاني الحريات والحقوق الأساسية (الفصول 19–40) الباب الثالث الملكية (الفصول 41–59) الباب الرابع السلطة التشريعية (الفصول 60–86): تنظيم البرلمان، سلطات البرلمان، ممارسة السلطة التشريعية الباب الخامس السلطة التنفيذية (الفصول 87–94) الباب السادس العلاقات بين السلط (الفصول 95–106) الباب السابع السلطة القضائية (الفصول 107–128) الباب الثامن المحكمة الدستورية (الفصول 129–134) الباب التاسع الجهات والجماعات الترابية الأخرى (الفصول 135–146) الباب العاشر المجلس الأعلى للحسابات (الفصول 147–150) الباب الحادي عشر المجلس الاقتصادي والاجتماعي والبيئي (الفصول 151–153) الباب الثاني عشر الحكامة الجيدة (الفصول 154–171) الباب الثالث عشر مراجعة الدستور (الفصول 172–175) الباب الرابع عشر أحكام انتقالية وختامية (الفصول 176–180)»', 'دستور 2011، الفصل 180', true)
INSERT INTO public.help_qa
  (question, answer, keywords, source_url, source_title, published)
VALUES
  ('ماذا ينص الفصل 1 من دستور 2011؟', 'نظام الحكم بالمغرب نظام ملكية دستورية، ديمقراطية برلمانية واجتماعية. يقوم النظام الدستوري للمملكة على أساس فصل السلط، وتوازنها وتعاونها، والديمقراطية المواطنة والتشاركية، وعلى مبادئ الحكامة الجيدة، وربط المسؤولية بالمحاسبة. تستند الأمة في حياتها العامة على ثوابت جامعة، تتمثل في الدين الإسلامي السمح، والوحدة الوطنية متعددة الروافد، والملكية الدستورية، والاختيار الديمقراطي. التنظيم الترابي للمملكة تنظيم لا مركزي، يقوم على الجهوية المتقدمة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 1', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 2 من دستور 2011؟', 'السيادة للأمة، تمارسها مباشرة بالاستفتاء، وبصفة غير مباشرة بواسطة ممثليها. تختار الأمة ممثليها في المؤسسات المنتخبة بالاقتراع الحر والنزيه والمنتظم.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 2', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 3 من دستور 2011؟', 'الإسلام دين الدولة، والدولة تضمن لكل واحد حرية ممارسة شؤونه الدينية.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 3', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 4 من دستور 2011؟', 'علم المملكة هو اللواء الأحمر الذي تتوسطه نجمة خضراء خماسية الفروع. شعار المملكة: الله، الوطن، الملك.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 4', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 5 من دستور 2011؟', 'تظل العربية اللغة الرسمية للدولة. وتعمل الدولة على حمايتها وتطويرها، وتنمية استعمالها. تعد الأمازيغية أيضا لغة رسمية للدولة، باعتبارها رصيدا مشتركا لجميع المغاربة بدون استثناء. يحدد قانون تنظيمي مراحل تفعيل الطابع الرسمي للأمازيغية، وكيفيات إدماجها في مجال التعليم، وفي مجالات الحياة العامة ذات الأولوية، وذلك لكي تتمكن من القيام مستقبلا بوظيفتها، بصفتها لغة رسمية. تعمل الدولة على صيانة الحسانية، باعتبارها جزءا لا يتجزأ من الهوية الثقافية المغربية الموحدة، وعلى حماية اللهجات والتعبيرات الثقافية المستعملة في المغرب، وتسهر على انسجام السياسة اللغوية والثقافية الوطنية، وعلى تعلم وإتقان اللغات الأجنبية الأكثر تداولا في العالم؛ باعتبارها وسائل للتواصل والانخراط والتفاعل مع مجتمع المعرفة، والانفتاح على مختلف الثقافات، وعلى حضارة العصر. يُحدَث مجلس وطني للغات والثقافة المغربية، مهمته، على وجه الخصوص، حماية وتنمية اللغتين العربية والأمازيغية، ومختلف التعبيرات الثقافية المغربية باعتبارها تراثا أصيلا وإبداعا معاصرا. ويضم كل المؤسسات المعنية بهذه المجالات. ويحدد قانون تنظيمي صلاحياته وتركيبته وكيفيات سيره.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 5', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 6 من دستور 2011؟', 'القانون هو أسمى تعبير عن إرادة الأمة. والجميع، أشخاصا ذاتيين أو اعتباريين، بما فيهم السلطات العمومية، متساوون أمامه، وملزمون بالامتثال له. تعمل السلطات العمومية على توفير الظروف التي تمكن من تعميم الطابع الفعلي لحرية المواطنات والمواطنين، والمساواة بينهم، ومن مشاركتهم في الحياة السياسية والاقتصادية والثقافية والاجتماعية. تعتبر دستورية القواعد القانونية، وتراتبيتها، ووجوب نشرها، مبادئ ملزمة. ليس للقانون أثر رجعي.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 6', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 7 من دستور 2011؟', 'تعمل الأحزاب السياسية على تأطير المواطنات والمواطنين وتكوينهم السياسي، وتعزيز انخراطهم في الحياة الوطنية، وفي تدبير الشأن العام، وتساهم في التعبير عن إرادة الناخبين، والمشاركة في ممارسة السلطة، على أساس التعددية والتناوب، بالوسائل الديمقراطية، وفي نطاق المؤسسات الدستورية. تُؤسس الأحزاب وتُمارس أنشطتها بحرية، في نطاق احترام الدستور والقانون. نظام الحزب الوحيد نظام غير مشروع. لا يجوز أن تؤسس الأحزاب السياسية على أساس ديني أو لغوي أو عرقي أو جهوي، وبصفة عامة، على أي أساس من التمييز أو المخالفة لحقوق الإنسان. ولا يجوز أن يكون هدفها المساس بالدين الإسلامي، أو بالنظام الملكي، أو المبادئ الدستورية، أو الأسس الديمقراطية، أو الوحدة الوطنية أو الترابية للمملكة. يجب أن يكون تنظيم الأحزاب السياسية وتسييرها مطابقا للمبادئ الديمقراطية. يحدد قانون تنظيمي، في إطار المبادئ المشار إليها في هذا الفصل، القواعد المتعلقة، بصفة خاصة، بتأسيس الأحزاب السياسية، وأنشطتها ومعايير تخويلها الدعم المالي للدولة، وكذا كيفيات مراقبة تمويلها.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 7', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 8 من دستور 2011؟', 'تساهم المنظمات النقابية للأُجراء، والغرف المهنية، والمنظمات المهنية للمشغلين، في الدفاع عن الحقوق والمصالح الاجتماعية والاقتصادية للفئات التي تمثلها، وفي النهوض بها. ويتم تأسيسها وممارسة أنشطتها بحرية، في نطاق احترام الدستور والقانون. يجب أن تكون هياكل هذه المنظمات وتسييرها مطابقة للمبادئ الديمقراطية. تعمل السلطات العمومية على تشجيع المفاوضة الجماعية، وعلى إبرام اتفاقيات الشغل الجماعية، وفق الشروط التي ينص عليها القانون. يحدد القانون، بصفة خاصة، القواعد المتعلقة بتأسيس المنظمات النقابية وأنشطتها، وكذا معايير تخويلها الدعم المالي للدولة، وكيفيات مراقبة تمويلها.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 8', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 9 من دستور 2011؟', 'لا يمكن حل الأحزاب السياسية والمنظمات النقابية أو توقيفها من لدن السلطات العمومية، إلا بمقتضى مقرر قضائي.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 9', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 10 من دستور 2011؟', 'يضمن الدستور للمعارضة البرلمانية مكانة تخولها حقوقا، من شأنها تمكينها من النهوض بمهامها، على الوجه الأكمل، في العمل البرلماني والحياة السياسية. ويضمن الدستور، بصفة خاصة، للمعارضة الحقوق التالية: حرية الرأي والتعبير والاجتماع؛ حيزا زمنيا في وسائل الإعلام العمومية يتناسب مع تمثيليتها؛ الاستفادة من التمويل العمومي وفق مقتضيات القانون؛ المشاركة الفعلية في مسطرة التشريع، لا سيما عن طريق تسجيل مقترحات قوانين بجدول أعمال مجلسي البرلمان؛ المشاركة الفعلية في مراقبة العمل الحكومي، لا سيما عن طريق ملتمس الرقابة، ومساءلة الحكومة، والأسئلة الشفوية الموجهة للحكومة، واللجان النيابية لتقصي الحقائق؛ المساهمة في اقتراح المترشحين وفي انتخاب أعضاء المحكمة الدستورية؛ تمثيلية ملائمة في الأنشطة الداخلية لمجلسي البرلمان؛ رئاسة اللجنة المكلفة بالتشريع بمجلس النواب؛ التوفر على وسائل ملائمة للنهوض بمهامها المؤسسية؛ المساهمة الفاعلة في الدبلوماسية البرلمانية، للدفاع عن القضايا العادلة للوطن ومصالحه الحيوية؛ المساهمة في تأطير وتمثيل المواطنات والمواطنين، من خلال الأحزاب المكونة لها، طبقا لأحكام الفصل 7 من هذا الدستور؛ ممارسة السلطة عن طريق التناوب الديمقراطي، محليا وجهويا ووطنيا، في نطاق أحكام الدستور. يجب على فرق المعارضة المساهمة في العمل البرلماني بكيفية فعالة وبناءة. تحدد كيفيات ممارسة فرق المعارضة لهذه الحقوق، حسب الحالة، بموجب قوانين تنظيمية أو قوانين أو بمقتضى النظام الداخلي لكل مجلس من مجلسي البرلمان.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 10', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 11 من دستور 2011؟', 'الانتخابات الحرة والنزيهة والشفافة هي أساس مشروعية التمثيل الديمقراطي. السلطات العمومية ملزمة بالحياد التام إزاء المترشحين، وبعدم التمييز بينهم. يحدد القانون القواعد التي تضمن الاستفادة، على نحو منصف، من وسائل الإعلام العمومية، والممارسة الكاملة للحريات والحقوق الأساسية، المرتبطة بالحمالات الانتخابية، وبعمليات التصويت. وتسهر السلطات المختصة بتنظيم الانتخابات على تطبيقها. يحدد القانون شروط وكيفيات الملاحظة المستقلة والمحايدة للانتخابات، طبقا للمعايير المتعارف عليها دوليا. كل شخص خالف المقتضيات والقواعد المتعلقة بنزاهة وصدق وشفافية العمليات الانتخابية، يعاقب على ذلك بمقتضى القانون. تتخذ السلطات العمومية الوسائل الكفيلة بالنهوض بمشاركة المواطنات والمواطنين في الانتخابات.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 11', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 12 من دستور 2011؟', 'تُؤسس جمعيات المجتمع المدني والمنظمات غير الحكومية وتمارس أنشطتها بحرية، في نطاق احترام الدستور والقانون. لا يمكن حل هذه الجمعيات والمنظمات أو توقيفها من لدن السلطات العمومية، إلا بمقتضى مقرر قضائي. تُساهم الجمعيات المهتمة بقضايا الشأن العام، والمنظمات غير الحكومية، في إطار الديمقراطية التشاركية، في إعداد قرارات ومشاريع لدى المؤسسات المنتخبة والسلطات العمومية، وكذا في تفعيلها وتقييمها. وعلى هذه المؤسسات والسلطات تنظيم هذه المشاركة، طبق شروط وكيفيات يحددها القانون. يجب أن يكون تنظيم الجمعيات والمنظمات غير الحكومية وتسييرها مطابقا للمبادئ الديمقراطية.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 12', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 13 من دستور 2011؟', 'تعمل السلطات العمومية على إحداث هيئات للتشاور، قصد إشراك مختلف الفاعلين الاجتماعيين، في إعداد السياسات العمومية وتفعيلها وتنفيذها وتقييمها.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 13', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 14 من دستور 2011؟', 'للمواطنات والمواطنين، ضمن شروط وكيفيات يحددها قانون تنظيمي، الحق في تقديم ملتمسات في مجال التشريع.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 14', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 15 من دستور 2011؟', 'للمواطنات والمواطنين الحق في تقديم عرائض إلى السلطات العمومية. ويحدد قانون تنظيمي شروط وكيفيات ممارسة هذا الحق.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 15', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 16 من دستور 2011؟', 'تعمل المملكة المغربية على حماية الحقوق والمصالح المشروعة للمواطنات والمواطنين المغاربة المقيمين في الخارج، في إطار احترام القانون الدولي والقوانين الجاري بها العمل في بلدان الاستقبال. كما تحرص على الحفاظ على الوشائج الإنسانية معهم، ولا سيما الثقافية منها، وتعمل على تنميتها وصيانة هويتهم الوطنية. تسهر الدولة على تقوية مساهمتهم في تنمية وطنهم المغرب، وكذا على تمتين أواصر الصداقة والتعاون مع حكومات ومجتمعات البلدان المقيمين بها أو التي يعتبرون من مواطنيها.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 16', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 17 من دستور 2011؟', 'يتمتع المغاربة المقيمون في الخارج بحقوق المواطنة كاملة، بما فيها حق التصويت والترشيح في الانتخابات. ويمكنهم تقديم ترشيحاتهم للانتخابات على مستوى اللوائح والدوائر الانتخابية، المحلية والجهوية والوطنية. ويحدد القانون المعايير الخاصة بالأهلية للانتخاب وحالات التنافي. كما يحدد شروط وكيفيات الممارسة الفعلية لحق التصويت وحق الترشيح، انطلاقا من بلدان الإقامة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 17', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 18 من دستور 2011؟', 'تعمل السلطات العمومية على ضمان أوسع مشاركة ممكنة للمغاربة المقيمين في الخارج، في المؤسسات الاستشارية، وهيئات الحكامة الجيدة، التي يحدثها الدستور أو القانون. الباب الثاني: الحريات والحقوق الأساسية', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 18', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 19 من دستور 2011؟', 'يتمتع الرجل والمرأة، على قدم المساواة، بالحقوق والحريات المدنية والسياسية والاقتصادية والاجتماعية والثقافية والبيئية، الواردة في هذا الباب من الدستور، وفي مقتضياته الأخرى، وكذا في الاتفاقيات والمواثيق الدولية، كما صادق عليها المغرب، وكل ذلك في نطاق أحكام الدستور وثوابت المملكة وقوانينها. تسعى الدولة إلى تحقيق مبدأ المناصفة بين الرجال والنساء. وتُحدث لهذه الغاية، هيئة للمناصفة ومكافحة كل أشكال التمييز.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 19', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 20 من دستور 2011؟', 'الحق في الحياة هو أول الحقوق لكل إنسان. ويحمي القانون هذا الحق.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 20', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 21 من دستور 2011؟', 'لكل فرد الحق في سلامة شخصه وأقربائه، وحماية ممتلكاته. تضمن السلطات العمومية سلامة السكان، وسلامة التراب الوطني، في إطار احترام الحريات والحقوق الأساسية المكفولة للجميع.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 21', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 22 من دستور 2011؟', 'لا يجوز المس بالسلامة الجسدية أو المعنوية لأي شخص، في أي ظرف، ومن قبل أي جهة كانت، خاصة أو عامة. لا يجوز لأحد أن يعامل الغير، تحت أي ذريعة، معاملة قاسية أو لا إنسانية أو مهينة أو حاطة بالكرامة الإنسانية. ممارسة التعذيب بكافة أشكاله، ومن قبل أي أحد، جريمة يعاقب عليها القانون.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 22', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 23 من دستور 2011؟', 'لا يجوز إلقاء القبض على أي شخص أو اعتقاله أو متابعته أو إدانته، إلا في الحالات وطبقا للإجراءات التي ينص عليها القانون. الاعتقال التعسفي أو السري والاختفاء القسري، من أخطر الجرائم، وتعرض مقترفيها لأقسى العقوبات. يجب إخبار كل شخص تم اعتقاله، على الفور وبكيفية يفهمها، بدواعي اعتقاله وبحقوقه، ومن بينها حقه في التزام الصمت. ويحق له الاستفادة، في أقرب وقت ممكن، من مساعدة قانونية، ومن إمكانية الاتصال بأقربائه، طبقا للقانون. قرينة البراءة والحق في محاكمة عادلة مضمونان. يتمتع كل شخص معتقل بحقوق أساسية، وبظروف اعتقال إنسانية. ويمكنه أن يستفيد من برامج للتكوين وإعادة الإدماج. يُحظَر كل تحريض على العنصرية أو الكراهية أو العنف. يُعاقب القانون على جريمة الإبادة وغيرها من الجرائم ضد الإنسانية، وجرائم الحرب، وكافة الانتهاكات الجسيمة والممنهجة لحقوق الإنسان.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 23', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 24 من دستور 2011؟', 'لكل شخص الحق في حماية حياته الخاصة. لا تنتهك حرمة المنزل. ولا يمكن القيام بأي تفتيش إلا وفق الشروط والإجراءات التي ينص عليها القانون. لا تنتهك سرية الاتصالات الشخصية، كيفما كان شكلها. ولا يمكن الترخيص بالاطلاع على مضمونها أو نشرها، كلا أو بعضا، أو باستعمالها ضد أي كان، إلا بأمر قضائي، ووفق الشروط والكيفيات التي ينص عليها القانون. حرية التنقل عبر التراب الوطني والاستقرار فيه، والخروج منه، والعودة إليه، مضمونة للجميع وفق القانون.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 24', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 25 من دستور 2011؟', 'حرية الفكر والرأي والتعبير مكفولة بكل أشكالها. حرية الإبداع والنشر والعرض في مجالات الأدب والفن والبحث العلمي والتقني مضمونة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 25', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 26 من دستور 2011؟', 'تدعم السلطات العمومية بالوسائل الملائمة، تنمية الإبداع الثقافي والفني، والبحث العلمي والتقني والنهوض بالرياضة. كما تسعى لتطوير تلك المجالات وتنظيمها، بكيفية مستقلة، وعلى أسس ديمقراطية ومهنية مضبوطة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 26', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 27 من دستور 2011؟', 'للمواطنات والمواطنين حق الحصول على المعلومات، الموجودة في حوزة الإدارة العمومية، والمؤسسات المنتخبة، والهيئات المكلفة بمهام المرفق العام. لا يمكن تقييد الحق في المعلومة إلا بمقتضى القانون، بهدف حماية كل ما يتعلق بالدفاع الوطني، وحماية أمن الدولة الداخلي والخارجي، والحياة الخاصة للأفراد، وكذا الوقاية من المس بالحريات والحقوق الأساسية المنصوص عليها في هذا الدستور، وحماية مصادر المعلومات والمجالات التي يحددها القانون بدقة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 27', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 28 من دستور 2011؟', 'حرية الصحافة مضمونة، ولا يمكن تقييدها بأي شكل من أشكال الرقابة القبلية. للجميع الحق في التعبير، ونشر الأخبار والأفكار والآراء، بكل حرية، ومن غير قيد، عدا ما ينص عليه القانون صراحة. تشجع السلطات العمومية على تنظيم قطاع الصحافة، بكيفية مستقلة، وعلى أسس ديمقراطية، وعلى وضع القواعد القانونية والأخلاقية المتعلقة به. يحدد القانون قواعد تنظيم وسائل الإعلام العمومية ومراقبتها. ويضمن الاستفادة من هذه الوسائل، مع احترام التعددية اللغوية والثقافية والسياسية للمجتمع المغربي. وتسهر الهيئة العليا للاتصال السمعي البصري على احترام هذه التعددية، وفق أحكام الفصل 165 من هذا الدستور.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 28', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 29 من دستور 2011؟', 'حريات الاجتماع والتجمهر والتظاهر السلمي، وتأسيس الجمعيات، والانتماء النقابي والسياسي مضمونة. ويحدد القانون شروط ممارسة هذه الحريات. حق الإضراب مضمون. ويحدد قانون تنظيمي شروط وكيفيات ممارسته.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 29', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 30 من دستور 2011؟', 'لكل مواطنة ومواطن، الحق في التصويت، وفي الترشح للانتخابات، شرط بلوغ سن الرشد القانونية، والتمتع بالحقوق المدنية والسياسية. وينص القانون على مقتضيات من شأنها تشجيع تكافؤ الفرص بين النساء والرجال في ولوج الوظائف الانتخابية. التصويت حق شخصي وواجب وطني. يتمتع الأجانب بالحريات الأساسية المعترف بها للمواطنات والمواطنين المغاربة، وفق القانون. ويمكن للأجانب المقيمين بالمغرب المشاركة في الانتخابات المحلية، بمقتضى القانون أو تطبيقا لاتفاقيات دولية أو ممارسات المعاملة بالمثل. يحدد القانون شروط تسليم الأشخاص المتابعين أو المدانين لدول أجنبية، وكذا شروط منح حق اللجوء.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 30', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 31 من دستور 2011؟', 'تعمل الدولة والمؤسسات العمومية والجماعات الترابية، على تعبئة كل الوسائل المتاحة، لتيسير أسباب استفادة المواطنات والمواطنين، على قدم المساواة، من الحق في: العلاج والعناية الصحية؛ الحماية الاجتماعية والتغطية الصحية، والتضامن التعاضدي أو المنظم من لدن الدولة؛ الحصول على تعليم عصري ميسر الولوج وذي جودة؛ التنشئة على التشبث بالهوية المغربية، والثوابت الوطنية الراسخة؛ التكوين المهني والاستفادة من التربية البدنية والفنية؛ السكن اللائق؛ الشغل والدعم من طرف السلطات العمومية في البحث عن منصب شغل، أو في التشغيل الذاتي؛ ولوج الوظائف العمومية حسب الاستحقاق؛ الحصول على الماء والعيش في بيئة سليمة؛ التنمية المستدامة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 31', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 32 من دستور 2011؟', 'الأسرة القائمة على علاقة الزواج الشرعي هي الخلية الأساسية للمجتمع. تعمل الدولة على ضمان الحماية الحقوقية والاجتماعية والاقتصادية للأسرة، بمقتضى القانون، بما يضمن وحدتها واستقرارها والمحافظة عليها. تسعى الدولة لتوفير الحماية القانونية، والاعتبار الاجتماعي والمعنوي لجميع الأطفال، بكيفية متساوية، بصرف النظر عن وضعيتهم العائلية. التعليم الأساسي حق للطفل وواجب على الأسرة والدولة. يحدث مجلس استشاري للأسرة والطفولة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 32', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 33 من دستور 2011؟', 'على السلطات العمومية اتخاذ التدابير الملائمة لتحقيق ما يلي: توسيع وتعميم مشاركة الشباب في التنمية الاجتماعية والاقتصادية والثقافية والسياسية للبلاد؛ مساعدة الشباب على الاندماج في الحياة النشيطة والجمعوية، وتقديم المساعدة لأولئك الذين تعترضهم صعوبة في التكيف المدرسي أو الاجتماعي أو المهني؛ تيسير ولوج الشباب للثقافة والعلم والتكنولوجيا، والفن والرياضة والأنشطة الترفيهية، مع توفير الظروف المواتية لتفتق طاقاتهم الخلاقة والإبداعية في كل هذه المجالات. يُحدث مجلس استشاري للشباب والعمل الجمعوي، من أجل تحقيق هذه الأهداف.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 33', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 34 من دستور 2011؟', 'تقوم السلطات العمومية بوضع وتفعيل سياسات موجهة إلى الأشخاص والفئات من ذوي الاحتياجات الخاصة. ولهذا الغرض، تسهر خصوصا على ما يلي: معالجة الأوضاع الهشة لفئات من النساء والأمهات، وللأطفال والأشخاص المسنين والوقاية منها؛ إعادة تأهيل الأشخاص الذين يعانون من إعاقة جسدية، أو حسية حركية، أو عقلية، وإدماجهم في الحياة الاجتماعية والمدنية، وتيسير تمتعهم بالحقوق والحريات المعترف بها للجميع.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 34', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 35 من دستور 2011؟', 'يضمن القانون حق الملكية. ويمكن الحد من نطاقها وممارستها بموجب القانون، إذا اقتضت ذلك متطلبات التنمية الاقتصادية والاجتماعية للبلاد. ولا يمكن نزع الملكية إلا في الحالات ووفق الإجراءات التي ينص عليها القانون. تضمن الدولة حرية المبادرة والمقاولة، والتنافس الحر. كما تعمل على تحقيق تنمية بشرية مستدامة، من شأنها تعزيز العدالة الاجتماعية، والحفاظ على الثروات الطبيعية الوطنية، وعلى حقوق الأجيال القادمة. تسهر الدولة على ضمان تكافؤ الفرص للجميع، والرعاية الخاصة للفئات الاجتماعية الأقل حظا.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 35', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 36 من دستور 2011؟', 'يعاقب القانون على المخالفات المتعلقة بحالات تنازع المصالح، وعلى استغلال التسريبات المخلة بالتنافس النزيه، وكل مخالفة ذات طابع مالي. على السلطات العمومية الوقاية، طبقا للقانون، من كل أشكال الانحراف المرتبطة بنشاط الإدارات والهيئات العمومية، وباستعمال الأموال الموجودة تحت تصرفها، وبإبرام الصفقات العمومية وتدبيرها، والزجر عن هذه الانحرافات. يعاقب القانون على الشطط في استغلال مواقع النفوذ والامتياز، ووضعيات الاحتكار والهيمنة، وباقي الممارسات المخالفة لمبادئ المنافسة الحرة والمشروعة في العلاقات الاقتصادية. تحدث هيئة وطنية للنزاهة والوقاية من الرشوة ومحاربتها.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 36', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 37 من دستور 2011؟', 'على جميع المواطنات والمواطنين احترام الدستور والتقيد بالقانون. ويتعين عليهم ممارسة الحقوق والحريات التي يكفلها الدستور بروح المسؤولية والمواطنة الملتزمة، التي تتلازم فيها ممارسة الحقوق بالنهوض بأداء الواجبات.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 37', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 38 من دستور 2011؟', 'يُساهم كل المواطنات والمواطنين في الدفاع عن الوطن ووحدته الترابية تجاه أي عدوان أو تهديد.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 38', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 39 من دستور 2011؟', 'على الجميع أن يتحمل، كل على قدر استطاعته، التكاليف العمومية، التي للقانون وحده إحداثها وتوزيعها، وفق الإجراءات المنصوص عليها في هذا الدستور.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 39', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 40 من دستور 2011؟', 'على الجميع أن يتحمل، بصفة تضامنية، وبشكل يتناسب مع الوسائل التي يتوفرون عليها، التكاليف التي تتطلبها تنمية البلاد، وكذا تلك الناتجة عن الأعباء الناجمة عن الآفات والكوارث الطبيعية التي تصيب البلاد. الباب الثالث: الملكية', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 40', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 41 من دستور 2011؟', 'الملك، أمير المؤمنين وحامي حمى الملة والدين، والضامن لحرية ممارسة الشؤون الدينية. يرأس الملك، أمير المؤمنين، المجلس العلمي الأعلى، الذي يتولى دراسة القضايا التي يعرضها عليه. ويعتبر المجلس الجهة الوحيدة المؤهلة لإصدار الفتاوى التي تعتمد رسميا، في شأن المسائل المحالة إليه، استنادا إلى مبادئ وأحكام الدين الإسلامي الحنيف، ومقاصده السمحة. تحدد اختصاصات المجلس وتأليفه وكيفيات سيره بظهير. يمارس الملك الصلاحيات الدينية المتعلقة بإمارة المؤمنين، والمخولة له حصريا، بمقتضى هذا الفصل، بواسطة ظهائر.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 41', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 42 من دستور 2011؟', 'الملك رئيس الدولة، وممثلها الأسمى، ورمز وحدة الأمة، وضامن دوام الدولة واستمرارها، والحكم الأسمى بين مؤسساتها، يسهر على احترام الدستور، وحسن سير المؤسسات الدستورية، وعلى صيانة الاختيار الديمقراطي، وحقوق وحريات المواطنات والمواطنين والجماعات، وعلى احترام التعهدات الدولية للمملكة. الملك هو ضامن استقلال البلاد وحوزة المملكة في دائرة حدودها الحقة. يمارس الملك هذه المهام، بمقتضى ظهائر، من خلال السلطات المخولة له صراحة بنص الدستور. توقع الظهائر بالعطف من قبل رئيس الحكومة، ماعدا تلك المنصوص عليها في الفصول 41 و44 (الفقرة الثانية) و47 (الفقرتان الأولى والسادسة) و51 و57 و59 و130 (الفقرتان الأولى والرابعة) و174.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 42', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 43 من دستور 2011؟', 'إن عرش المغرب وحقوقه الدستورية تنتقل بالوراثة إلى الولد الذكر الأكبر سنا من ذرية جلالة الملك محمد السادس، ثم إلى ابنه الأكبر سنا وهكذا ما تعاقبوا، ما عدا إذا عين الملك قيد حياته خلفا له ولدا آخر من أبنائه غير الولد الأكبر سنا، فإن لم يكن ولد ذكر من ذرية الملك، فالمُلك ينتقل إلى أقرب أقربائه من جهة الذكور، ثم إلى ابنه طبق الترتيب والشروط السابقة الذكر.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 43', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 44 من دستور 2011؟', 'يعتبر الملك غير بالغ سن الرشد قبل نهاية السنة الثامنة عشرة من عمره. وإلى أن يبلغ سن الرشد، يمارس مجلس الوصاية اختصاصات العرش وحقوقه الدستورية، باستثناء ما يتعلق منها بمراجعة الدستور. ويعمل مجلس الوصاية كهيئة استشارية بجانب الملك حتى يدرك تمام السنة العشرين من عمره. يرأس مجلس الوصاية رئيس المحكمة الدستورية، ويتركب، بالإضافة إلى رئيسه، من رئيس الحكومة، ورئيس مجلس النواب، ورئيس مجلس المستشارين، والرئيس المنتدب للمجلس الأعلى للسلطة القضائية، والأمين العام للمجلس العلمي الأعلى، وعشر شخصيات يعينهم الملك بمحض اختياره. قواعد سير مجلس الوصاية تحدد بقانون تنظيمي.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 44', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 45 من دستور 2011؟', 'للملك قائمة مدنية.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 45', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 46 من دستور 2011؟', 'شخص الملك لا تنتهك حرمته، وللملك واجب التوقير والاحترام.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 46', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 47 من دستور 2011؟', 'يعين الملك رئيس الحكومة من الحزب السياسي الذي تصدر انتخابات أعضاء مجلس النواب، وعلى أساس نتائجها. ويعين أعضاء الحكومة باقتراح من رئيسها. للملك، بمبادرة منه، بعد استشارة رئيس الحكومة، أن يعفي عضوا أو أكثر من أعضاء الحكومة من مهامهم. ولرئيس الحكومة أن يطلب من الملك إعفاء عضو أو أكثر، من أعضاء الحكومة. ولرئيس الحكومة أن يطلب من الملك إعفاء عضو أو أكثر، من أعضاء الحكومة، بناء على استقالتهم الفردية أو الجماعية. يترتب عن استقالة رئيس الحكومة إعفاء الحكومة بكاملها من لدن الملك. تواصل الحكومة المنتهية مهامها تصريف الأمور الجارية إلى غاية تشكيل الحكومة الجديدة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 47', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 48 من دستور 2011؟', 'يرأس الملك المجلس الوزاري، الذي يتألف من رئيس الحكومة والوزراء. ينعقد المجلس الوزاري بمبادرة من الملك، أو بطلب من رئيس الحكومة. للملك أن يفوض لرئيس الحكومة، بناء على جدول أعمال محدد، رئاسة مجلس وزاري.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 48', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 49 من دستور 2011؟', 'يتداول المجلس الوزاري في القضايا والنصوص التالية: التوجهات الاستراتيجية لسياسة الدولة؛ مشاريع مراجعة الدستور؛ مشاريع القوانين التنظيمية؛ التوجهات العامة لمشروع قانون المالية؛ مشاريع القوانين - الإطار المشار إليها في الفصل 71 (الفقرة الثانية) من هذا الدستور؛ مشروع قانون العفو العام؛ مشاريع النصوص المتعلقة بالمجال العسكري؛ إعلان حالة الحصار؛ إشهار الحرب؛ مشروع المرسوم المشار إليه في الفصل 104 من هذا الدستور؛ التعيين باقتراح من رئيس الحكومة، وبمبادرة من الوزير المعني، في الوظائف المدنية التالية: والي بنك المغرب، والسفراء والولاة والعمال، والمسؤولين عن الإدارات المكلفة بالأمن الداخلي، والمسؤولين عن المؤسسات والمقاولات العمومية الاستراتيجية. وتحدد بقانون تنظيمي لائحة هذه المؤسسات والمقاولات الاستراتيجية.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 49', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 50 من دستور 2011؟', 'يصدر الملك الأمر بتنفيذ القانون خلال الثلاثين يوما التالية لإحالته إلى الحكومة بعد تمام الموافقة عليه. ينشر القانون الذي صدر الأمر بتنفيذه، بالجريدة الرسمية للمملكة، خلال أجل أقصاه شهر ابتداء من تاريخ ظهير إصداره.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 50', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 51 من دستور 2011؟', 'للملك حق حل مجلسي البرلمان أو أحدهما بظهير، طبق الشروط المبينة في الفصول 96 و97 و98.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 51', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 52 من دستور 2011؟', 'للملك أن يخاطب الأمة والبرلمان، ويتلى خطابه أمام كلا المجلسين، ولا يمكن أن يكون مضمونه موضوع أي نقاش داخلهما.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 52', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 53 من دستور 2011؟', 'الملك هو القائد الأعلى للقوات المسلحة الملكية. وله حق التعيين في الوظائف العسكرية، كما له أن يفوض لغيره ممارسة هذا الحق.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 53', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 54 من دستور 2011؟', 'يُحدث مجلس أعلى للأمن، بصفته هيئة للتشاور بشأن استراتيجيات الأمن الداخلي والخارجي للبلاد، وتدبير حالات الأزمات، والسهر أيضا على مأسسة ضوابط الحكامة الأمنية الجيدة. يرأس الملك هذا المجلس، وله أن يفوض لرئيس الحكومة صلاحية رئاسة اجتماع لهذا المجلس، على أساس جدول أعمال محدد. يضم المجلس الأعلى للأمن في تركيبته، علاوة على رئيس الحكومة، ورئيس مجلس النواب، ورئيس مجلس المستشارين، والرئيس المنتدب للمجلس الأعلى للسلطة القضائية، الوزراء المكلفين بالداخلية، والشؤون الخارجية، والعدل، وإدارة الدفاع الوطني، وكذا المسؤولين عن الإدارات الأمنية، وضباط سامين بالقوات المسلحة الملكية، وكل شخصية أخرى يُعتبر حضورها مفيدا لأشغال المجلس. ويحدد نظام داخلي للمجلس قواعد تنظيمه وتسييره.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 54', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 55 من دستور 2011؟', 'يعتمد الملك السفراء لدى الدول الأجنبية والمنظمات الدولية، ولديه يُعتمد السفراء وممثلو المنظمات الدولية. يوقع الملك على المعاهدات ويصادق عليها، غير أنه لا يصادق على معاهدات السلم أو الاتحاد، أو التي تهم رسم الحدود، ومعاهدات التجارة، أو تلك التي يترتب عليها تكاليف تلزم مالية الدولة، أو يستلزم تطبيقها اتخاذ تدابير تشريعية، أو تتعلق بحقوق وحريات المواطنات والمواطنين، العامة أو الخاصة، إلا بعد الموافقة عليها بقانون. للملك أن يعرض على البرلمان كل معاهدة أو اتفاقية أخرى قبل المصادقة عليها. إذا صرحت المحكمة الدستورية، إثر إحالة الملك، أو رئيس الحكومة، أو رئيس مجلس النواب، أو رئيس مجلس المستشارين، أو سدس أعضاء المجلس الأول، أو ربع أعضاء المجلس الثاني، الأمر إليها، أن التزاما دوليا يتضمن بندا يخالف الدستور، فإن المصادقة على هذا الالتزام لا تقع إلا بعد مراجعة الدستور.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 55', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 56 من دستور 2011؟', 'يرأس الملك المجلس الأعلى للسلطة القضائية.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 56', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 57 من دستور 2011؟', 'يوافق الملك بظهير على تعيين القضاة من قبل المجلس الأعلى للسلطة القضائية.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 57', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 58 من دستور 2011؟', 'يمارس الملك حق العفو.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 58', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 59 من دستور 2011؟', 'إذا كانت حوزة التراب الوطني مهددة، أو وقع من الأحداث ما يعرقل السير العادي للمؤسسات الدستورية، أمكن للملك أن يُعلن حالة الاستثناء بظهير، بعد استشارة كل من رئيس الحكومة، ورئيس مجلس النواب، ورئيس مجلس المستشارين، ورئيس المحكمة الدستورية، وتوجيه خطاب إلى الأمة. ويُخول الملك بذلك صلاحية اتخاذ الإجراءات التي يفرضها الدفاع عن الوحدة الترابية، ويقتضيها الرجوع، في أقرب الآجال، إلى السير العادي للمؤسسات الدستورية. لا يحل البرلمان أثناء ممارسة السلطات الاستثنائية. تبقى الحريات والحقوق الأساسية المنصوص عليها في هذا الدستور مضمونة. تُرفع حالة الاستثناء بمجرد انتفاء الأسباب التي دعت إليها، وباتخاذ الإجراءات الشكلية المقررة لإعلانها. الباب الرابع: السلطة التشريعية تنظيم البرلمان', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 59', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 60 من دستور 2011؟', 'يتكون البرلمان من مجلسين، مجلس النواب ومجلس المستشارين؛ ويستمد أعضاؤه نيابتهم من الأمة، وحقهم في التصويت حق شخصي لا يمكن تفويضه. المعارضة مكون أساسي في المجلسين، وتشارك في وظيفتي التشريع والمراقبة، طبقا لما هو منصوص عليه خاصة في هذا الباب.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 60', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 61 من دستور 2011؟', 'يجرد من صفة عضو في أحد المجلسين، كل من تخلى عن انتمائه السياسي الذي ترشح باسمه للانتخابات، أو عن الفريق أو المجموعة البرلمانية التي ينتمي إليها. وتصرح المحكمة الدستورية بشغور المقعد، بناء على إحالة من رئيس المجلس الذي يعنيه الأمر، وذلك وفق أحكام النظام الداخلي للمجلس المعني، الذي يحدد أيضا آجال ومسطرة الإحالة على المحكمة الدستورية.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 61', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 62 من دستور 2011؟', 'ينتخب أعضاء مجلس النواب بالاقتراع العام المباشر لمدة خمس سنوات، وتنتهي عضويتهم عند افتتاح دورة أكتوبر من السنة الخامسة التي تلي انتخاب المجلس. يبين قانون تنظيمي عدد أعضاء مجلس النواب، ونظام انتخابهم، ومبادئ التقسيم الانتخابي، وشروط القابلية للانتخاب، وحالات التنافي، وقواعد الحد من الجمع بين الانتدابات، ونظام المنازعات الانتخابية. يُنتخب رئيس مجلس النواب وأعضاء المكتب، ورؤساء اللجان الدائمة ومكاتبها، في مستهل الفترة النيابية، ثم في سنتها الثالثة عند دورة أبريل لما تبقى من الفترة المذكورة. يُنتخب أعضاء المكتب على أساس التمثيل النسبي لكل فريق.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 62', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 63 من دستور 2011؟', 'يتكون مجلس المستشارين من 90 عضوا على الأقل، و120 عضوا على الأكثر، ينتخبون بالاقتراع العام غير المباشر، لمدة ست سنوات، على أساس التوزيع التالي: ثلاثة أخماس الأعضاء يمثلون الجماعات الترابية، يتوزعون بين جهات المملكة بالتناسب مع عدد سكانها، ومع مراعاة الإنصاف بين الجهات. ينتخب المجلس الجهوي على مستوى كل جهة، من بين أعضائه، الثلث المخصص للجهة من هذا العدد. وينتخب الثلثان المتبقيان من قبل هيئة ناخبة تتكون على مستوى الجهة، من أعضاء المجالس الجماعية ومجالس العمالات والأقاليم؛ خمسان من الأعضاء تنتخبهم، في كل جهة، هيئات ناخبة تتألف من المنتخبين في الغرف المهنية، وفي المنظمات المهنية للمشغلين الأكثر تمثيلية، وأعضاء تنتخبهم على الصعيد الوطني، هيئة ناخبة مكونة من ممثلي المأجورين. ويبين قانون تنظيمي عدد أعضاء مجلس المستشارين، ونظام انتخابهم، وعدد الأعضاء الذين تنتخبهم كل هيأة ناخبة، وتوزيع المقاعد على الجهات، وشروط القابلية للانتخاب، وحالات التنافي، وقواعد الحد من الجمع بين الانتدابات، ونظام المنازعات الانتخابية. يُنتخب رئيس مجلس المستشارين وأعضاء المكتب، ورؤساء اللجان الدائمة ومكاتبها، في مستهل الفترة النيابية، ثم عند انتصاف الولاية التشريعية للمجلس. ينتخب أعضاء المكتب على أساس التمثيل النسبي لكل فريق.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 63', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 64 من دستور 2011؟', 'لا يمكن متابعة أي عضو من أعضاء البرلمان، ولا البحث عنه، ولا إلقاء القبض عليه، ولا اعتقاله، ولا محاكمته بمناسبة إبدائه لرأي أو قيامه بتصويت خلال مزاولته لمهامه، ما عدا إذا كان الرأي المعبر عنه يجادل في النظام الملكي أو الدين الإسلامي، أو يتضمن ما يخل بالاحترام الواجب للملك.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 64', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 65 من دستور 2011؟', 'يعقد البرلمان جلساته أثناء دورتين في السنة، ويرأس الملك افتتاح الدورة الأولى، التي تبتدئ يوم الجمعة الثانية من شهر أكتوبر، وتُفتتح الدورة الثانية يوم الجمعة الثانية من شهر أبريل. إذا استمرت جلسات البرلمان أربعة أشهر على الأقل في كل دورة، جاز ختم الدورة بمرسوم.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 65', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 66 من دستور 2011؟', 'يمكن جمع البرلمان في دورة استثنائية، إما بمرسوم، أو بطلب من ثلث أعضاء مجلس النواب، أو بأغلبية أعضاء مجلس المستشارين. تعقد دورة البرلمان الاستثنائية على أساس جدول أعمال محدد، وعندما تتم المناقشة في القضايا التي يتضمنها جدول الأعمال، تُختم الدورة بمرسوم.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 66', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 67 من دستور 2011؟', 'للوزراء أن يحضروا جلسات كلا المجلسين واجتماعات لجانهما، ويمكنهم أن يستعينوا بمندوبين يعينونهم لهذا الغرض. علاوة على اللجان الدائمة المشار إليها في الفقرة السابقة، يجوز أن تشكل بمبادرة من الملك، أو بطلب من ثلث أعضاء مجلس النواب، أو ثلث أعضاء مجلس المستشارين، لجان نيابية لتقصي الحقائق، يُناط بها جمع المعلومات المتعلقة بوقائع معينة، أو بتدبير المصالح أو المؤسسات والمقاولات العمومية، وإطلاع المجلس الذي شكلها على نتائج أعمالها. ولا يجوز تكوين لجان لتقصي الحقائق في وقائع تكون موضوع متابعات قضائية، ما دامت هذه المتابعات جارية؛ وتنتهي مهمة كل لجنة لتقصي الحقائق، سبق تكوينها، فور فتح تحقيق قضائي في الوقائع التي اقتضت تشكيلها. لجان تقصي الحقائق مؤقتة بطبيعتها، وتنتهي أعمالها بإيداع تقريرها لدى مكتب المجلس المعني، وعند الاقتضاء، بإحالته إلى القضاء من قبل رئيس هذا المجلس. تخصص جلسة عمومية داخل المجلس المعني لمناقشة تقارير لجان تقصي الحقائق. يحدد قانون تنظيمي طريقة تسيير هذه اللجان.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 67', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 68 من دستور 2011؟', 'جلسات مجلسي البرلمان عمومية، وينشر محضر مناقشات الجلسات العامة برمته في الجريدة الرسمية للبرلمان. لكل من المجلسين أن يعقد اجتماعات سرية، بطلب من رئيس الحكومة، أو بطلب من ثلث أعضائه. جلسات لجان البرلمان سرية، ويحدد النظام الداخلي لمجلسي البرلمان الحالات والضوابط التي يمكن أن تنعقد فيها اللجان بصفة علنية. يعقد البرلمان جلسات مشتركة بمجلسيه، وعلى وجه الخصوص، في الحالات التالية: افتتاح الملك للدورة التشريعية في الجمعة الثانية من شهر أكتوبر، والاستماع إلى الخطب الملكية الموجهة للبرلمان؛ المصادقة على مراجعة الدستور وفق أحكام الفصل 174؛ الاستماع إلى التصريحات التي يقدمها رئيس الحكومة؛ عرض مشروع قانون المالية السنوي؛ الاستماع إلى خطب رؤساء الدول والحكومات الأجنبية. كما يمكن لرئيس الحكومة أن يطلب من رئيسي مجلسي النواب والمستشارين عقد اجتماعات مشتركة للبرلمان، للاستماع إلى بيانات تتعلق بقضايا تكتسي طابعا وطنيا هاما. تنعقد الاجتماعات المشتركة برئاسة رئيس مجلس النواب، ويحدد النظام الداخلي للمجلسين كيفيات وضوابط انعقادها. علاوة على الجلسات المشتركة، يمكن للجان الدائمة للبرلمان، أن تعقد اجتماعات مشتركة للاستماع إلى بيانات تتعلق بقضايا تكتسي طابعا وطنيا هاما، وذلك وفق ضوابط يحددها النظامان الداخليان للمجلسين.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 68', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 69 من دستور 2011؟', 'يضع كل من المجلسين نظامه الداخلي ويقره بالتصويت، إلا أنه لا يجوز العمل به إلا بعد أن تصرح المحكمة الدستورية بمطابقته لأحكام هذا الدستور. يتعين على المجلسين، في وضعهما لنظاميهما الداخليين، مراعاة تناسقهما وتكاملهما، ضمانا لنجاعة العمل البرلماني. يحدد النظام الداخلي بصفة خاصة: قواعد تأليف وتسيير الفرق والمجموعات البرلمانية والانتساب إليها، والحقوق الخاصة المعترف بها لفرق المعارضة؛ واجبات الأعضاء في المشاركة الفعلية في أعمال اللجان والجلسات العامة، والجزاءات المطبقة في حالة الغياب؛ عدد اللجان الدائمة واختصاصها وتنظيمها، مع تخصيص رئاسة لجنة أو لجنتين للمعارضة، على الأقل، مع مراعاة مقتضيات الفصل 10 من هذا الدستور. سلطات البرلمان', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 69', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 70 من دستور 2011؟', 'يمارس البرلمان السلطة التشريعية. يصوت البرلمان على القوانين، ويراقب عمل الحكومة، ويقيم السياسات العمومية. للقانون أن يأذن للحكومة أن تتخذ في ظرف من الزمن محدود، ولغاية معينة، بمقتضى مراسيم تدابير يختص القانون عادة باتخاذها، ويجري العمل بهذه المراسيم بمجرد نشرها. غير أنه يجب عرضها على البرلمان بقصد المصادقة، عند انتهاء الأجل الذي حدده قانون الإذن بإصدارها، ويبطل قانون الإذن إذا ما وقع حل مجلسي البرلمان أو أحدهما.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 70', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 71 من دستور 2011؟', 'يختص القانون، بالإضافة إلى المواد المسندة إليه صراحة بفصول أخرى من الدستور، بالتشريع في الميادين التالية: الحقوق والحريات الأساسية المنصوص عليها في التصدير، وفي فصول أخرى من هذا الدستور؛ نظام الأسرة والحالة المدنية؛ مبادئ وقواعد المنظومة الصحية؛ نظام الوسائط السمعية البصرية والصحافة بمختلف أشكالها؛ العفو العام؛ الجنسية ووضعية الأجانب؛ تحديد الجرائم والعقوبات الجارية عليها؛ التنظيم القضائي وإحداث أصناف جديدة من المحاكم؛ المسطرة المدنية والمسطرة الجنائية؛ نظام السجون؛ النظام الأساسي العام للوظيفة العمومية؛ الضمانات الأساسية الممنوحة للموظفين المدنيين والعسكريين؛ نظام مصالح وقوات حفظ الأمن؛ نظام الجماعات الترابية ومبادئ تحديد دوائرها الترابية؛ النظام الانتخابي للجماعات الترابية ومبادئ تقطيع الدوائر الانتخابية؛ النظام الضريبي، ووعاء الضرائب، ومقدارها وطرق تحصيلها؛ النظام القانوني لإصدار العملة ونظام البنك المركزي؛ نظام الجمارك؛ نظام الالتزامات المدنية والتجارية، وقانون الشركات والتعاونيات؛ الحقوق العينية وأنظمة الملكية العقارية العمومية والخاصة والجماعية؛ نظام النقل؛ علاقات الشغل، والضمان الاجتماعي، وحوادث الشغل، والأمراض المهنية؛ نظام الأبناك وشركات التأمين والتعاضديات؛ نظام تكنولوجيا المعلومات والاتصالات؛ التعمير وإعداد التراب؛ القواعد المتعلقة بتدبير البيئة وحماية الموارد الطبيعية والتنمية المستدامة؛ نظام المياه والغابات والصيد؛ تحديد التوجهات والتنظيم العام لميادين التعليم والبحث العلمي والتكوين المهني؛ إحداث المؤسسات العمومية وكل شخص اعتباري من أشخاص القانون العام؛ تأميم المنشآت ونظام الخوصصة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 71', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 71 من دستور 2011؟ (الجزء 2)', 'للبرلمان، بالإضافة إلى الميادين المشار إليها في الفقرة السابقة، صلاحية التصويت على قوانين تضع إطارا للأهداف الأساسية لنشاط الدولة، في الميادين الاقتصادية والاجتماعية والبيئية والثقافية.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 71', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 72 من دستور 2011؟', 'يختص المجال التنظيمي بالمواد التي لا يشملها اختصاص القانون.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 72', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 73 من دستور 2011؟', 'يمكن تغيير النصوص التشريعية من حيث الشكل بمرسوم، بعد موافقة المحكمة الدستورية، إذا كان مضمونها يدخل في مجال من المجالات التي تمارس فيها السلطة التنظيمية اختصاصها.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 73', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 74 من دستور 2011؟', 'يمكن الإعلان لمدة ثلاثين يوما عن حالة الحصار، بمقتضى ظهير يوقعه بالعطف رئيس الحكومة، ولا يمكن تمديد هذا الأجل إلا بالقانون.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 74', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 75 من دستور 2011؟', 'يصدر قانون المالية، الذي يودع بالأسبقية لدى مجلس النواب، بالتصويت من قبل البرلمان، وذلك طبق الشروط المنصوص عليها في قانون تنظيمي؛ ويحدد هذا القانون التنظيمي طبيعة المعلومات والوثائق والمعطيات الضرورية لتعزيز المناقشة البرلمانية حول مشروع قانون المالية. يصوت البرلمان مرة واحدة على نفقات التجهيز التي يتطلبها، في مجال التنمية، إنجاز المخططات التنموية الاستراتيجية، والبرامج متعددة السنوات، التي تعدها الحكومة وتطلع عليها البرلمان، وعندما يوافق على تلك النفقات، يستمر مفعول الموافقة تلقائيا على النفقات طيلة مدة هذه المخططات والبرامج، وللحكومة وحدها الصلاحية لتقديم مشاريع قوانين ترمي إلى تغيير ما تمت الموافقة عليه في الإطار المذكور. إذا لم يتم في نهاية السنة المالية التصويت على قانون المالية أو لم يصدر الأمر بتنفيذه، بسبب إحالته إلى المحكمة الدستورية، تطبيقا للفصل 132 من الدستور، فإن الحكومة تفتح بمرسوم الاعتمادات اللازمة لسير المرافق العمومية، والقيام بالمهام المنوطة بها، على أساس ما هو مقترح في الميزانية المعروضة على الموافقة. ويسترسل العمل، في هذه الحالة، باستخلاص المداخيل طبقا للمقتضيات التشريعية والتنظيمية الجارية عليها، باستثناء المداخيل المقترح إلغاؤها في مشروع قانون المالية؛ أما المداخيل التي ينص المشروع المذكور على تخفيض مقدارها، فتُستخلص على أساس المقدار الجديد المقترح.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 75', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 76 من دستور 2011؟', 'تعرض الحكومة سنويا على البرلمان، قانون التصفية المتعلق بتنفيذ قانون المالية، خلال السنة الثانية التي تلي سنة تنفيذ هذا القانون. ويتضمن قانون التصفية حصيلة ميزانيات التجهيز التي انتهت مدة نفاذها.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 76', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 77 من دستور 2011؟', 'يسهر البرلمان والحكومة على الحفاظ على توازن مالية الدولة. وللحكومة أن ترفض، بعد بيان الأسباب، المقترحات والتعديلات التي يتقدم بها أعضاء البرلمان، إذا كان قبولها يؤدي بالنسبة لقانون المالية إلى تخفيض الموارد العمومية، أو إلى إحداث تكليف عمومي، أو الزيادة في تكليف موجود. ممارسة السلطة التشريعية', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 77', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 78 من دستور 2011؟', 'لرئيس الحكومة ولأعضاء البرلمان على السواء حق التقدم باقتراح القوانين. تودع مشاريع القوانين بالأسبقية لدى مكتب مجلس النواب، غير أن مشاريع القوانين المتعلقة، على وجه الخصوص، بالجماعات الترابية وبالتنمية الجهوية، وبالقضايا الاجتماعية، تودع بالأسبقية لدى مكتب مجلس المستشارين.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 78', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 79 من دستور 2011؟', 'للحكومة أن تدفع بعدم قبول كل مقترح أو تعديل لا يدخل في مجال القانون. كل خلاف في هذا الشأن تبت فيه المحكمة الدستورية، في أجل ثمانية أيام، بطلب من أحد رئيسي المجلسين، أو من رئيس الحكومة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 79', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 80 من دستور 2011؟', 'تحال مشاريع ومقترحات القوانين لأجل النظر فيها على اللجان التي يستمر عملها خلال الفترات الفاصلة بين الدورات.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 80', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 81 من دستور 2011؟', 'يمكن للحكومة أن تصدر، خلال الفترة الفاصلة بين الدورات، وباتفاق مع اللجان التي يعنيها الأمر في كلا المجلسين، مراسيم قوانين، يجب عرضها بقصد المصادقة عليها من طرف البرلمان، خلال دورته العادية الموالية. يودع مشروع المرسوم بقانون لدى مكتب مجلس النواب، وتناقشه بالتتابع اللجان المعنية في كلا المجلسين بغية التوصل داخل أجل ستة أيام، إلى قرار مشترك بينهما في شأنه. وإذا لم يحصل هذا الاتفاق، فإن القرار يرجع إلى اللجنة المعنية في مجلس النواب.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 81', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 82 من دستور 2011؟', 'يضع مكتب كل من مجلسي البرلمان جدول أعماله. ويتضمن هذا الجدول مشاريع القوانين ومقترحات القوانين، بالأسبقية ووفق الترتيب الذي تحدده الحكومة. يخصص يوم واحد على الأقل في الشهر لدراسة مقترحات القوانين، ومن بينها تلك المقدمة من قبل المعارضة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 82', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 83 من دستور 2011؟', 'لأعضاء مجلسي البرلمان وللحكومة حق التعديل. وللحكومة، بعد افتتاح المناقشة، أن تعارض في بحث كل تعديل لم يُعرض من قبل على اللجنة التي يعنيها الأمر. يبت المجلس المعروض عليه النص، بتصويت واحد، في النص المتناقش فيه، كله أو بعضه إذا ما طلبت الحكومة ذلك، مع الاقتصار على التعديلات المقترحة أو المقبولة من قبلها. وبإمكان المجلس المعني بالأمر أن يعترض على هذه المسطرة بأغلبية أعضائه.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 83', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 84 من دستور 2011؟', 'يتداول مجلسا البرلمان بالتتابع في كل مشروع أو مقترح قانون، بغية التوصل إلى المصادقة على نص واحد؛ ويتداول مجلس النواب بالأسبقية، وعلى التوالي، في مشاريع القوانين، وفي مقترحات القوانين التي قدمت بمبادرة من أعضائه، ويتداول مجلس المستشارين بدوره بالأسبقية، وعلى التوالي، في مشاريع القوانين، وكذا في مقترحات القوانين التي هي من مبادرة أعضائه؛ ويتداول كل مجلس في النص الذي صوت عليه المجلس الآخر في الصيغة التي أحيل بها إليه. ويعود لمجلس النواب التصويت النهائي على النص الذي تم البت فيه، ولا يقع هذا التصويت إلا بالأغلبية المطلقة لأعضائه الحاضرين، إذا تعلق الأمر بنص يخص الجماعات الترابية، والمجالات ذات الصلة بالتنمية الجهوية والشؤون الاجتماعية.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 84', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 85 من دستور 2011؟', 'لا يتم التداول في مشاريع ومقترحات القوانين التنظيمية من قبل مجلس النواب، إلا بعد مضي عشرة أيام على وضعها لدى مكتبه، ووفق المسطرة المشار إليها في الفصل 84، وتتم المصادقة عليها نهائيا بالأغلبية المطلقة للأعضاء الحاضرين من المجلس المذكور؛ غير أنه إذا تعلق الأمر بمشروع أو بمقترح قانون تنظيمي يخص مجلس المستشارين أو الجماعات الترابية، فإن التصويت يتم بأغلبية أعضاء مجلس النواب. يجب أن يتم إقرار القوانين التنظيمية المتعلقة بمجلس المستشارين، باتفاق بين مجلسي البرلمان، على نص موحد. لا يمكن إصدار الأمر بتنفيذ القوانين التنظيمية، إلا بعد أن تصرح المحكمة الدستورية بمطابقتها للدستور.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 85', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 86 من دستور 2011؟', 'تعرض مشاريع القوانين التنظيمية المنصوص عليها في هذا الدستور وجوبا قصد المصادقة عليها من قبل البرلمان، في أجل لا يتعدى مدة الولاية التشريعية الأولى التي تلي صدور الأمر بتنفيذ هذا الدستور. الباب الخامس: السلطة التنفيذية', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 86', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 87 من دستور 2011؟', 'تتألف الحكومة من رئيس الحكومة والوزراء، ويمكن أن تضم كتابا للدولة. يُحدد قانون تنظيمي، خاصة، القواعد المتعلقة بتنظيم وتسيير أشغال الحكومة والوضع القانوني لأعضائها. ويحدد هذا القانون التنظيمي أيضا حالات التنافي مع الوظيفة الحكومية، وقواعد الحد من الجمع بين المناصب، والقواعد الخاصة بتصريف الحكومة المنتهية مهامها للأمور الجارية.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 87', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 88 من دستور 2011؟', 'بعد تعيين الملك لأعضاء الحكومة، يتقدم رئيس الحكومة أمام مجلسي البرلمان مجتمعين، ويعرض البرنامج الذي يعتزم تطبيقه. ويجب أن يتضمن هذا البرنامج الخطوط الرئيسية للعمل الذي تنوي الحكومة القيام به في مختلف مجالات النشاط الوطني، وبالأخص في ميادين السياسة الاقتصادية والاجتماعية والبيئية والثقافية والخارجية. يكون البرنامج المشار إليه أعلاه، موضوع مناقشة أمام كلا المجلسين، يعقبها تصويت في مجلس النواب. تعتبر الحكومة منصبة بعد حصولها على ثقة مجلس النواب، المعبر عنها بتصويت الأغلبية المطلقة للأعضاء الذين يتألف منهم، لصالح البرنامج الحكومي.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 88', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 89 من دستور 2011؟', 'تمارس الحكومة السلطة التنفيذية. تعمل الحكومة، تحت سلطة رئيسها، على تنفيذ البرنامج الحكومي وعلى ضمان تنفيذ القوانين. والإدارة موضوعة تحت تصرفها، كما تمارس الإشراف والوصاية على المؤسسات والمقاولات العمومية.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 89', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 90 من دستور 2011؟', 'يمارس رئيس الحكومة السلطة التنظيمية، ويمكن أن يفوض بعض سلطه إلى الوزراء. تحمل المقررات التنظيمية الصادرة عن رئيس الحكومة التوقيع بالعطف من لدن الوزراء المكلفين بتنفيذها.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 90', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 91 من دستور 2011؟', 'يعين رئيس الحكومة في الوظائف المدنية في الإدارات العمومية، وفي الوظائف السامية في المؤسسات والمقاولات العمومية، دون إخلال بأحكام الفصل 49 من هذا الدستور. يمكن لرئيس الحكومة تفويض هذه السلطة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 91', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 92 من دستور 2011؟', 'يتداول مجلس الحكومة، تحت رئاسة رئيس الحكومة، في القضايا والنصوص التالية: السياسة العامة للدولة قبل عرضها على المجلس الوزاري؛ السياسات العمومية؛ السياسات القطاعية؛ طلب الثقة من مجلس النواب، قصد مواصلة الحكومة تحمل مسؤوليتها؛ القضايا الراهنة المرتبطة بحقوق الإنسان وبالنظام العام؛ مشاريع القوانين، ومن بينها مشروع قانون المالية، قبل إيداعها بمكتب مجلس النواب، دون إخلال بالأحكام الواردة في الفصل 49 من هذا الدستور؛ مراسيم القوانين؛ مشاريع المراسيم التنظيمية؛ مشاريع المراسيم المشار إليها في الفصول 65 (الفقرة الثانية) و66 و70 (الفقرة الثالثة) من هذا الدستور؛ المعاهدات والاتفاقيات الدولية قبل عرضها على المجلس الوزاري؛ تعيين الكتاب العامين، ومديري الإدارات المركزية بالإدارات العمومية، ورؤساء الجامعات والعمداء، ومديري المدارس والمؤسسات العليا. وللقانون التنظيمي المشار إليه في الفصل 49 من هذا الدستور، أن يتمم لائحة الوظائف التي يتم التعيين فيها في مجلس الحكومة. ويحدد هذا القانون التنظيمي، على وجه الخصوص، مبادئ ومعايير التعيين في هذه الوظائف، لا سيما منها مبادئ تكافؤ الفرص والاستحقاق والكفاءة والشفافية. يطلع رئيس الحكومة الملك على خلاصات مداولات مجلس الحكومة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 92', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 93 من دستور 2011؟', 'الوزراء مسؤولون عن تنفيذ السياسة الحكومية كل في القطاع المكلف به، وفي إطار التضامن الحكومي. يقوم الوزراء بأداء المهام المسندة إليهم من قبل رئيس الحكومة، ويطلعون مجلس الحكومة على ذلك. يمكن للوزراء أن يفوضوا جزءا من اختصاصاتهم إلى كتاب الدولة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 93', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 94 من دستور 2011؟', 'أعضاء الحكومة مسؤولون جنائيا أمام محاكم المملكة، عما يرتكبون من جنايات وجنح، أثناء ممارستهم لمهامهم. يُحدد القانون المسطرة المتعلقة بهذه المسؤولية. الباب السادس: العلاقات بين السلط العلاقة بين الملك والسلطة التشريعية', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 94', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 95 من دستور 2011؟', 'للملك أن يطلب من كلا مجلسي البرلمان أن يقرأ قراءة جديدة كل مشروع أو مقترح قانون. تُطلب القراءة الجديدة بخطاب، ولا يمكن أن ترفض هذه القراءة الجديدة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 95', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 96 من دستور 2011؟', 'للملك، بعد استشارة رئيس المحكمة الدستورية وإخبار رئيس الحكومة ورئيس مجلس النواب، ورئيس مجلس المستشارين، أن يحل بظهير المجلسين معا أو أحدهما. يقع الحل بعد خطاب يوجهه الملك إلى الأمة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 96', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 97 من دستور 2011؟', 'يتم انتخاب البرلمان الجديد أو المجلس الجديد في ظرف شهرين على الأكثر بعد تاريخ الحل.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 97', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 98 من دستور 2011؟', 'إذا وقع حل أحد المجلسين، فلا يمكن حل المجلس الذي يليه إلا بعد مضي سنة على انتخابه، ما عدا في حالة تعذر توفر أغلبية حكومية داخل مجلس النواب الجديد.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 98', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 99 من دستور 2011؟', 'يتم اتخاذ قرار إشهار الحرب داخل المجلس الوزاري، طبقا للفصل 49 من هذا الدستور، وبعد إحاطة البرلمان علما بذلك من لدن الملك. العلاقات بين السلطتين التشريعية والتنفيذية', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 99', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 100 من دستور 2011؟', 'تُخصص بالأسبقية جلسة في كل أسبوع لأسئلة أعضاء مجلسي البرلمان وأجوبة الحكومة. تُدلي الحكومة بجوابها خلال العشرين يوما الموالية لإحالة السؤال إليها. تُقدم الأجوبة على الأسئلة المتعلقة بالسياسة العامة من قبل رئيس الحكومة، وتخصص لهذه الأسئلة جلسة واحدة كل شهر، وتُقدم الأجوبة عنها أمام المجلس الذي يعنيه الأمر خلال الثلاثين يوما الموالية لإحالة الأسئلة إلى رئيس الحكومة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 100', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 101 من دستور 2011؟', 'يعرض رئيس الحكومة أمام البرلمان الحصيلة المرحلية لعمل الحكومة، إما بمبادرة منه، أو بطلب من ثلث أعضاء مجلس النواب، أو من أغلبية أعضاء مجلس المستشارين. تُخصص جلسة سنوية من قبل البرلمان لمناقشة السياسات العمومية وتقييمها.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 101', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 102 من دستور 2011؟', 'يمكن للجان المعنية في كلا المجلسين أن تطلب الاستماع إلى مسؤولي الإدارات والمؤسسات والمقاولات العمومية، بحضور الوزراء المعنيين، وتحت مسؤوليتهم.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 102', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 103 من دستور 2011؟', 'يمكن لرئيس الحكومة أن يربط، لدى مجلس النواب، مواصلة الحكومة تحمل مسؤوليتها بتصويت يمنح الثقة بشأن تصريح يدلي به في موضوع السياسة العامة، أو بشأن نص يطلب الموافقة عليه. لا يمكن سحب الثقة من الحكومة، أو رفض النص، إلا بالأغلبية المطلقة للأعضاء الذين يتألف منهم مجلس النواب. لا يقع التصويت إلا بعد مضي ثلاثة أيام كاملة على تاريخ طرح مسألة الثقة. يؤدي سحب الثقة إلى استقالة الحكومة استقالة جماعية.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 103', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 104 من دستور 2011؟', 'يمكن لرئيس الحكومة حل مجلس النواب، بعد استشارة الملك ورئيس المجلس، ورئيس المحكمة الدستورية، بمرسوم يتخذ في مجلس وزاري. يقدم رئيس الحكومة أمام مجلس النواب تصريحا يتضمن، بصفة خاصة، دوافع قرار الحل وأهدافه.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 104', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 105 من دستور 2011؟', 'لمجلس النواب أن يعارض في مواصلة الحكومة تحمل مسؤوليتها، بالتصويت على ملتمس للرقابة؛ ولا يقبل هذا الملتمس إلا إذا وقعه على الأقل خُمس الأعضاء الذين يتألف منهم المجلس. لا تصح الموافقة على ملتمس الرقابة من قبل مجلس النواب، إلا بتصويت الأغلبية المطلقة للأعضاء الذين يتألف منهم. لا يقع التصويت إلا بعد مضي ثلاثة أيام كاملة على إيداع الملتمس؛ وتؤدي الموافقة على ملتمس الرقابة إلى استقالة الحكومة استقالة جماعية. إذا وقعت موافقة مجلس النواب على ملتمس الرقابة، فلا يقبل بعد ذلك تقديم أي ملتمس رقابة أمامه، طيلة سنة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 105', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 106 من دستور 2011؟', 'لمجلس المستشارين أن يُسائل الحكومة بواسطة ملتمس يوقعه على الأقل خُمس أعضائه؛ ولا يقع التصويت عليه، بعد مضي ثلاثة أيام كاملة على إيداعه، إلا بالأغلبية المطلقة لأعضاء هذا المجلس. يبعث رئيس مجلس المستشارين، على الفور، بنص ملتمس المساءلة إلى رئيس الحكومة؛ ولهذا الأخير أجل ستة أيام ليعرض أمام هذا المجلس جواب الحكومة، يتلوه نقاش لا يعقبه تصويت. الباب السابع: السلطة القضائية استقلال القضاء', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 106', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 107 من دستور 2011؟', 'السلطة القضائية مستقلة عن السلطة التشريعية وعن السلطة التنفيذية. الملك هو الضامن لاستقلال السلطة القضائية.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 107', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 108 من دستور 2011؟', 'لا يعزل قضاة الأحكام ولا ينقلون إلا بمقتضى القانون.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 108', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 109 من دستور 2011؟', 'يمنع كل تدخل في القضايا المعروضة على القضاء؛ ولا يتلقى القاضي بشأن مهمته القضائية أي أوامر أو تعليمات، ولا يخضع لأي ضغط. يجب على القاضي، كلما اعتبر أن استقلاله مهدد، أن يحيل الأمر إلى المجلس الأعلى للسلطة القضائية. يعد كل إخلال من القاضي بواجب الاستقلال والتجرد خطأ مهنيا جسيما، بصرف النظر عن المتابعات القضائية المحتملة. يعاقب القانون كل من حاول التأثير على القاضي بكيفية غير مشروعة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 109', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 110 من دستور 2011؟', 'لا يلزم قضاة الأحكام إلا بتطبيق القانون. ولا تصدر أحكام القضاء إلا على أساس التطبيق العادل للقانون. يجب على قضاة النيابة العامة تطبيق القانون. كما يتعين عليهم الالتزام بالتعليمات الكتابية القانونية الصادرة عن السلطة التي يتبعون لها.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 110', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 111 من دستور 2011؟', 'للقضاة الحق في حرية التعبير، بما يتلاءم مع واجب التحفظ والأخلاقيات القضائية. يمكن للقضاة الانخراط في جمعيات، أو إنشاء جمعيات مهنية، مع احترام واجبات التجرد واستقلال القضاء، وطبقا للشروط المنصوص عليها في القانون. يُمنع على القضاة الانخراط في الأحزاب السياسية والمنظمات النقابية.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 111', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 112 من دستور 2011؟', 'يُحدد النظام الأساسي للقضاة بقانون تنظيمي. المجلس الأعلى للسلطة القضائية', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 112', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 113 من دستور 2011؟', 'يسهر المجلس الأعلى للسلطة القضائية على تطبيق الضمانات الممنوحة للقضاة، ولا سيما فيما يخص استقلالهم وتعيينهم وترقيتهم وتقاعدهم وتأديبهم. يضع المجلس الأعلى للسلطة القضائية، بمبادرة منه، تقارير حول وضعية القضاء ومنظومة العدالة، ويُصدر التوصيات الملائمة بشأنها. يُصدر المجلس الأعلى للسلطة القضائية، بطلب من الملك أو الحكومة أو البرلمان، آراء مفصلة حول كل مسألة تتعلق بالعدالة مع مراعاة مبدإ فصل السلط.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 113', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 114 من دستور 2011؟', 'تكون المقررات المتعلقة بالوضعيات الفردية، الصادرة عن المجلس الأعلى للسلطة القضائية قابلة للطعن بسبب الشطط في استعمال السلطة، أمام أعلى هيئة قضائية إدارية بالمملكة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 114', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 115 من دستور 2011؟', 'يرأس الملك المجلس الأعلى للسلطة القضائية، ويتألف هذا المجلس من: الرئيس الأول لمحكمة النقض، رئيسا منتدبا؛ الوكيل العام للملك لدى محكمة النقض؛ رئيس الغرفة الأولى بمحكمة النقض؛ أربعة ممثلين لقضاة محاكم الاستئناف، ينتخبهم هؤلاء القضاة من بينهم؛ ستة ممثلين لقضاة محاكم أول درجة، ينتخبهم هؤلاء القضاة من بينهم؛ ويجب ضمان تمثيلية النساء القاضيات من بين الأعضاء العشرة المنتخبين، بما يتناسب مع حضورهن داخل السلك القضائي؛ الوسيط؛ رئيس المجلس الوطني لحقوق الإنسان؛ خمس شخصيات يعينها الملك، مشهود لها بالكفاءة والتجرد والنزاهة، والعطاء المتميز في سبيل استقلال القضاء وسيادة القانون؛ من بينهم عضو يقترحه الأمين العام للمجلس العلمي الأعلى.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 115', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 116 من دستور 2011؟', 'يعقد المجلس الأعلى للسلطة القضائية دورتين في السنة على الأقل. يتوفر المجلس الأعلى للسلطة القضائية على الاستقلال الإداري والمالي. يساعد المجلس الأعلى للسلطة القضائية، في المادة التأديبية، قضاة مفتشون من ذوي الخبرة. يُحدد بقانون تنظيمي انتخاب وتنظيم وسير المجلس الأعلى للسلطة القضائية، والمعايير المتعلقة بتدبير الوضعية المهنية للقضاة، ومسطرة التأديب. يراعي المجلس الأعلى للسلطة القضائية، في القضايا التي تهم قضاة النيابة العامة، تقارير التقييم المقدمة من قبل السلطة التي يتبعون لها. حقوق المتقاضين وقواعد سير العدالة', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 116', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 117 من دستور 2011؟', 'يتولى القاضي حماية حقوق الأشخاص والجماعات وحرياتهم وأمنهم القضائي، وتطبيق القانون.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 117', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 118 من دستور 2011؟', 'حق التقاضي مضمون لكل شخص للدفاع عن حقوقه وعن مصالحه التي يحميها القانون. كل قرار اتخذ في المجال الإداري، سواء كان تنظيميا أو فرديا، يُمكن الطعن فيه أمام الهيئة القضائية الإدارية المختصة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 118', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 119 من دستور 2011؟', 'يعتبر كل مشتبه فيه أو متهم بارتكاب جريمة بريئا، إلى أن تثبت إدانته بمقرر قضائي مكتسب لقوة الشيء المقضي به.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 119', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 120 من دستور 2011؟', 'لكل شخص الحق في محاكمة عادلة، وفي حكم يصدر داخل أجل معقول. حقوق الدفاع مضمونة أمام جميع المحاكم.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 120', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 121 من دستور 2011؟', 'يكون التقاضي مجانيا في الحالات المنصوص عليها قانونا لمن لا يتوفر على موارد كافية للتقاضي.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 121', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 122 من دستور 2011؟', 'يحق لكل من تضرر من خطأ قضائي الحصول على تعويض تتحمله الدولة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 122', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 123 من دستور 2011؟', 'تكون الجلسات علنية ما عدا في الحالات التي يقرر فيها القانون خلاف ذلك.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 123', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 124 من دستور 2011؟', 'تصدر الأحكام وتنفذ باسم الملك وطبقا للقانون.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 124', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 125 من دستور 2011؟', 'تكون الأحكام معللة وتصدر في جلسة علنية، وفق الشروط المنصوص عليها في القانون.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 125', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 126 من دستور 2011؟', 'الأحكام النهائية الصادرة عن القضاء ملزمة للجميع. يجب على السلطات العمومية تقديم المساعدة اللازمة أثناء المحاكمة، إذا صدر الأمر إليها بذلك، ويجب عليها المساعدة على تنفيذ الأحكام.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 126', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 127 من دستور 2011؟', 'تُحدث المحاكم العادية والمتخصصة بمقتضى القانون. لا يمكن إحداث محاكم استثنائية.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 127', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 128 من دستور 2011؟', 'تعمل الشرطة القضائية تحت سلطة النيابة العامة وقضاة التحقيق، في كل ما يتعلق بالأبحاث والتحريات الضرورية في شأن الجرائم وضبط مرتكبيها ولإثبات الحقيقة. الباب الثامن: المحكمة الدستورية', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 128', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 129 من دستور 2011؟', 'تُحدث محكمة دستورية.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 129', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 130 من دستور 2011؟', 'تتألف المحكمة الدستورية من اثني عشر عضوا، يعينون لمدة تسع سنوات غير قابلة للتجديد، ستة أعضاء يعينهم الملك، من بينهم عضو يقترحه الأمين العام للمجلس العلمي الأعلى، وستة أعضاء يُنتخب نصفهم من قبل مجلس النواب، وينتخب النصف الآخر من قبل مجلس المستشارين من بين المترشحين الذين يقدمهم مكتب كل مجلس، وذلك بعد التصويت بالاقتراع السري وبأغلبية ثلثي الأعضاء الذين يتألف منهم كل مجلس. إذا تعذر على المجلسين أو على أحدهما انتخاب هؤلاء الأعضاء، داخل الأجل القانوني للتجديد، تمارس المحكمة اختصاصاتها، وتصدر قراراتها، وفق نصاب لا يحتسب فيه الأعضاء الذين لم يقع بعد انتخابهم. يتم كل ثلاث سنوات تجديد ثلث كل فئة من أعضاء المحكمة الدستورية. يعين الملك رئيس المحكمة الدستورية من بين الأعضاء الذين تتألف منهم. يختار أعضاء المحكمة الدستورية من بين الشخصيات المتوفرة على تكوين عال في مجال القانون، وعلى كفاءة قضائية أو فقهية أو إدارية، والذين مارسوا مهنتهم لمدة تفوق خمس عشرة سنة، والمشهود لهم بالتجرد والنزاهة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 130', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 131 من دستور 2011؟', 'يحدد قانون تنظيمي قواعد تنظيم المحكمة الدستورية وسيرها والإجراءات المتبعة أمامها، ووضعية أعضائها. يحدد القانون التنظيمي أيضا المهام التي لا يجوز الجمع بينها وبين عضوية المحكمة الدستورية، خاصة ما يتعلق منها بالمهن الحرة، وطريقة إجراء التجديدين الأولين لثلث أعضائها، وكيفيات تعيين من يحل محل أعضائها الذين استحال عليهم القيام بمهامهم، أو استقالوا أو توفوا أثناء مدة عضويتهم.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 131', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 132 من دستور 2011؟', 'تمارس المحكمة الدستورية الاختصاصات المسندة إليها بفصول الدستور، وبأحكام القوانين التنظيمية، وتبت بالإضافة إلى ذلك في صحة انتخاب أعضاء البرلمان وعمليات الاستفتاء. تحال إلى المحكمة الدستورية القوانين التنظيمية قبل إصدار الأمر بتنفيذها، والأنظمة الداخلية لكل من مجلس النواب ومجلس المستشارين قبل الشروع في تطبيقها لتبت في مطابقتها للدستور. يمكن للملك، وكذا لكل من رئيس الحكومة، أو رئيس مجلس النواب، أو رئيس مجلس المستشارين، أو خمس أعضاء مجلس النواب، أو أربعين عضوا من أعضاء مجلس المستشارين أن يحيلوا القوانين، قبل إصدار الأمر بتنفيذها، إلى المحكمة الدستورية، لتبت في مطابقتها للدستور. تبت المحكمة الدستورية في الحالات المنصوص عليها في الفقرتين الثانية والثالثة من هذا الفصل داخل أجل شهر من تاريخ الإحالة. غير أن هذا الأجل يخفض في حالة الاستعجال إلى ثمانية أيام، بطلب من الحكومة. تؤدي الإحالة إلى المحكمة الدستورية في هذه الحالات، إلى وقف سريان أجل إصدار الأمر بالتنفيذ. تبت المحكمة الدستورية في الطعون المتعلقة بانتخاب أعضاء البرلمان، داخل أجل سنة، ابتداء من تاريخ انقضاء أجل تقديم الطعون إليها. غير أن للمحكمة تجاوز هذا الأجل بموجب قرار معلل، إذا استوجب ذلك عدد الطعون المرفوعة إليها، أو استلزم ذلك الطعن المقدم إليها.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 132', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 133 من دستور 2011؟', 'تختص المحكمة الدستورية بالنظر في كل دفع متعلق بعدم دستورية قانون، أثير أثناء النظر في قضية، وذلك إذا دفع أحد الأطراف بأن القانون، الذي سيطبق في النزاع، يمس بالحقوق وبالحريات التي يضمنها الدستور. يحدد قانون تنظيمي شروط وإجراءات تطبيق هذا الفصل.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 133', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 134 من دستور 2011؟', 'لا يمكن إصدار الأمر بتنفيذ مقتضى تم التصريح بعدم دستوريته على أساس الفصل 132 من هذا الدستور، ولا تطبيقه، وينسخ كل مقتضى تم التصريح بعدم دستوريته على أساس الفصل 133 من الدستور، ابتداء من التاريخ الذي حددته المحكمة الدستورية في قرارها. لا تقبل قرارات المحكمة الدستورية أي طريق من طرق الطعن، وتلزم كل السلطات العامة وجميع الجهات الإدارية والقضائية. الباب التاسع: الجهات والجماعات الترابية الأخرى', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 134', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 135 من دستور 2011؟', 'الجماعات الترابية للمملكة هي الجهات والعمالات والأقاليم والجماعات. الجماعات الترابية أشخاص اعتبارية، خاضعة للقانون العام، تسير شؤونها بكيفية ديمقراطية. تنتخب مجالس الجهات والجماعات بالاقتراع العام المباشر. تحدث كل جماعة ترابية أخرى بالقانون، ويمكن أن تحل عند الاقتضاء، محل جماعة ترابية أو أكثر، من تلك المنصوص عليها في الفقرة الأولى من هذا الفصل.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 135', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 136 من دستور 2011؟', 'يرتكز التنظيم الجهوي والترابي على مبادئ التدبير الحر، وعلى التعاون والتضامن؛ ويؤمن مشاركة السكان المعنيين في تدبير شؤونهم، والرفع من مساهمتهم في التنمية البشرية المندمجة والمستدامة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 136', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 137 من دستور 2011؟', 'تساهم الجهات والجماعات الترابية الأخرى في تفعيل السياسة العامة للدولة، وفي إعداد السياسات الترابية، من خلال ممثليها في مجلس المستشارين.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 137', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 138 من دستور 2011؟', 'يقوم رؤساء مجالس الجهات، ورؤساء مجالس الجماعات الترابية الأخرى، بتنفيذ مداولات هذه المجالس ومقرراتها.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 138', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 139 من دستور 2011؟', 'تضع مجالس الجهات، والجماعات الترابية الأخرى، آليات تشاركية للحوار والتشاور، لتيسير مساهمة المواطنات والمواطنين والجمعيات في إعداد برامج التنمية وتتبعها. يُمكن للمواطنات والمواطنين والجمعيات تقديم عرائض، الهدف منها مطالبة المجلس بإدراج نقطة تدخل في اختصاصه ضمن جدول أعماله.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 139', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 140 من دستور 2011؟', 'للجماعات الترابية، وبناء على مبدأ التفريع، اختصاصات ذاتية واختصاصات مشتركة مع الدولة واختصاصات منقولة إليها من هذه الأخيرة. تتوفر الجهات والجماعات الترابية الأخرى، في مجالات اختصاصاتها، وداخل دائرتها الترابية، على سلطة تنظيمية لممارسة صلاحياتها.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 140', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 141 من دستور 2011؟', 'تتوفر الجهات والجماعات الترابية الأخرى، على موارد مالية ذاتية، وموارد مالية مرصودة من قبل الدولة. كل اختصاص تنقله الدولة إلى الجهات والجماعات الترابية الأخرى يكون مقترنا بتحويل الموارد المطابقة له.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 141', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 142 من دستور 2011؟', 'يُحدث لفترة معينة ولفائدة الجهات صندوق للتأهيل الاجتماعي، يهدف إلى سد العجز في مجالات التنمية البشرية، والبنيات التحتية الأساسية والتجهيزات. يُحدث أيضا صندوق للتضامن بين الجهات، بهدف التوزيع المتكافئ للموارد، قصد التقليص من التفاوتات بينها.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 142', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 143 من دستور 2011؟', 'لا يجوز لأي جماعة ترابية أن تمارس وصايتها على جماعة أخرى. تتبوأ الجهة، تحت إشراف رئيس مجلسها، مكانة الصدارة بالنسبة للجماعات الترابية الأخرى، في عمليات إعداد وتتبع برامج التنمية الجهوية، والتصاميم الجهوية لإعداد التراب، في نطاق احترام الاختصاصات الذاتية لهذه الجماعات الترابية. كلما تعلق الأمر بإنجاز مشروع يتطلب تعاون عدة جماعات ترابية، فإن هذه الأخيرة تتفق على كيفيات تعاونها.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 143', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 144 من دستور 2011؟', 'يمكن للجماعات الترابية تأسيس مجموعات فيما بينها، من أجل التعاضد في الوسائل والبرامج.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 144', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 145 من دستور 2011؟', 'يمثل ولاة الجهات وعمال الأقاليم والعمالات، السلطة المركزية في الجماعات الترابية. يعمل الولاة والعمال، باسم الحكومة، على تأمين تطبيق القانون، وتنفيذ النصوص التنظيمية للحكومة ومقرراتها، كما يمارسون المراقبة الإدارية. يساعد الولاة والعمال رؤساء الجماعات الترابية، وخاصة رؤساء المجالس الجهوية، على تنفيذ المخططات والبرامج التنموية. يقوم الولاة والعمال، تحت سلطة الوزراء المعنيين، بتنسيق أنشطة المصالح اللاممركزة للإدارة المركزية، ويسهرون على حسن سيرها.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 145', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 146 من دستور 2011؟', 'تحدد بقانون تنظيمي بصفة خاصة: شروط تدبير الجهات والجماعات الترابية الأخرى لشؤونها بكيفية ديمقراطية، وعدد أعضاء مجالسها، والقواعد المتعلقة بأهلية الترشيح، وحالات التنافي، وحالات منع الجمع بين الانتدابات، وكذا النظام الانتخابي، وأحكام تحسين تمثيلية النساء داخل المجالس المذكورة؛ شروط تنفيذ رؤساء مجالس الجهات ورؤساء مجالس الجماعات الترابية الأخرى لمداولات هذه المجالس ومقرراتها، طبقا للفصل 138؛ شروط تقديم العرائض المنصوص عليها في الفصل 139، من قبل المواطنات والمواطنين والجمعيات؛ الاختصاصات الذاتية لفائدة الجهات والجماعات الترابية الأخرى، والاختصاصات المشتركة بينها وبين الدولة والاختصاصات المنقولة إليها من هذه الأخيرة طبقا للفصل 140؛ النظام المالي للجهات والجماعات الترابية الأخرى؛ مصدر الموارد المالية للجهات وللجماعات الترابية الأخرى، المنصوص عليها في الفصل 141؛ موارد وكيفيات تسيير كل من صندوق التأهيل الاجتماعي وصندوق التضامن بين الجهات المنصوص عليهما في الفصل 142؛ شروط وكيفيات تأسيس المجموعات المشار إليها في الفصل 144؛ المقتضيات الهادفة إلى تشجيع تنمية التعاون بين الجماعات، وكذا الآليات الرامية إلى ضمان تكييف تطور التنظيم الترابي في هذا الاتجاه؛ قواعد الحكامة المتعلقة بحسن تطبيق مبدإ التدبير الحر، وكذا مراقبة تدبير الصناديق والبرامج وتقييم الأعمال وإجراءات المحاسبة. الباب العاشر: المجلس الأعلى للحسابات', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 146', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 147 من دستور 2011؟', 'المجلس الأعلى للحسابات هو الهيأة العليا لمراقبة المالية العمومية بالمملكة، ويضمن الدستور استقلاله. يمارس المجلس الأعلى للحسابات مهمة تدعيم وحماية مبادئ وقيم الحكامة الجيدة والشفافية والمحاسبة، بالنسبة للدولة والأجهزة العمومية. يتولى المجلس الأعلى للحسابات ممارسة المراقبة العليا على تنفيذ قوانين المالية. ويتحقق من سلامة العمليات المتعلقة بمداخيل ومصاريف الأجهزة الخاضعة لمراقبته بمقتضى القانون، ويقيم كيفية تدبيرها لشؤونها، ويتخذ، عند الاقتضاء، عقوبات عن كل إخلال بالقواعد السارية على العمليات المذكورة. تُناط بالمجلس الأعلى للحسابات مهمة مراقبة وتتبع التصريح بالممتلكات، وتدقيق حسابات الأحزاب السياسية، وفحص النفقات المتعلقة بالعمليات الانتخابية.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 147', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 148 من دستور 2011؟', 'يقدم المجلس الأعلى للحسابات مساعدته للبرلمان في المجالات المتعلقة بمراقبة المالية العامة؛ ويجيب عن الأسئلة والاستشارات المرتبطة بوظائف البرلمان في التشريع والمراقبة والتقييم المتعلقة بالمالية العامة. يقدم المجلس الأعلى للحسابات مساعدته للهيئات القضائية. يقدم المجلس الأعلى للحسابات مساعدته للحكومة، في الميادين التي تدخل في نطاق اختصاصاته بمقتضى القانون. ينشر المجلس الأعلى للحسابات جميع أعماله، بما فيها التقارير الخاصة والمقررات القضائية. يرفع المجلس الأعلى للحسابات للملك تقريرا سنويا، يتضمن بيانا عن جميع أعماله، ويوجهه أيضا إلى رئيس الحكومة، وإلى رئيسي مجلسي البرلمان، وينشر بالجريدة الرسمية للمملكة. يُقدم الرئيس الأول للمجلس عرضا عن أعمال المجلس الأعلى للحسابات أمام البرلمان، ويكون متبوعا بمناقشة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 148', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 149 من دستور 2011؟', 'تتولى المجالس الجهوية للحسابات مراقبة حسابات الجهات والجماعات الترابية الأخرى وهيئاتها، وكيفية قيامها بتدبير شؤونها. وتعاقب عند الاقتضاء، عن كل إخلال بالقواعد السارية على العمليات المذكورة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 149', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 150 من دستور 2011؟', 'يحدد القانون اختصاصات المجلس الأعلى للحسابات والمجالس الجهوية للحسابات، وقواعد تنظيمها، وكيفيات تسييرها. الباب الحادي عشر: المجلس الاقتصادي والاجتماعي والبيئي', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 150', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 151 من دستور 2011؟', 'يحدث مجلس اقتصادي واجتماعي وبيئي.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 151', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 152 من دستور 2011؟', 'للحكومة ولمجلس النواب ولمجلس المستشارين أن يستشيروا المجلس الاقتصادي والاجتماعي والبيئي في جميع القضايا، التي لها طابع اقتصادي واجتماعي وبيئي. يدلي المجلس برأيه في التوجهات العامة للاقتصاد الوطني والتنمية المستدامة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 152', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 153 من دستور 2011؟', 'يحدد قانون تنظيمي تأليف المجلس الاقتصادي والاجتماعي والبيئي، وتنظيمه، وصلاحياته، وكيفيات تسييره. الباب الثاني عشر: الحكامة الجيدة مبادئ عامة', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 153', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 154 من دستور 2011؟', 'يتم تنظيم المرافق العمومية على أساس المساواة بين المواطنات والمواطنين في الولوج إليها، والإنصاف في تغطية التراب الوطني، والاستمرارية في أداء الخدمات. تخضع المرافق العمومية لمعايير الجودة والشفافية والمحاسبة والمسؤولية، وتخضع في تسييرها للمبادئ والقيم الديمقراطية التي أقرها الدستور.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 154', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 155 من دستور 2011؟', 'يمارس أعوان المرافق العمومية وظائفهم وفق مبادئ احترام القانون والحياد والشفافية والنزاهة والمصلحة العامة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 155', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 156 من دستور 2011؟', 'تتلقى المرافق العمومية ملاحظات مرتفقيها، واقتراحاتهم وتظلماتهم، وتؤمن تتبعها. تقدم المرافق العمومية الحساب عن تدبيرها للأموال العمومية، طبقا للقوانين الجاري بها العمل، وتخضع في هذا الشأن للمراقبة والتقييم.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 156', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 157 من دستور 2011؟', 'يحدد ميثاق للمرافق العمومية قواعد الحكامة الجيدة المتعلقة بتسيير الإدارات العمومية والجهات والجماعات الترابية الأخرى والأجهزة العمومية.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 157', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 158 من دستور 2011؟', 'يجب على كل شخص، منتخبا كان أو معينا، يمارس مسؤولية عمومية، أن يقدم، طبقا للكيفيات المحددة في القانون، تصريحا كتابيا بالممتلكات والأصول التي في حيازته، بصفة مباشرة أو غير مباشرة، بمجرد تسلمه لمهامه، وخلال ممارستها، وعند انتهائها.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 158', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 159 من دستور 2011؟', 'تكون الهيئات المكلفة بالحكامة الجيدة مستقلة؛ وتستفيد من دعم أجهزة الدولة؛ ويمكن للقانون أن يُحدث عند الضرورة، علاوة على المؤسسات والهيئات المذكورة بعده، هيئات أخرى للضبط والحكامة الجيدة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 159', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 160 من دستور 2011؟', 'على المؤسسات والهيئات المشار إليها في الفصول 161 إلى 170 من هذا الدستور تقديم تقرير عن أعمالها، مرة واحدة في السنة على الأقل، الذي يكون موضوع مناقشة من قبل البرلمان. مؤسسات وهيئات حماية الحقوق والحريات والحكامة الجيدة والتنمية البشرية والمستدامة والديمقراطية التشاركية — هيئات حماية حقوق الإنسان والنهوض بها', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 160', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 161 من دستور 2011؟', 'المجلس الوطني لحقوق الإنسان مؤسسة وطنية تعددية ومستقلة، تتولى النظر في جميع القضايا المتعلقة بالدفاع عن حقوق الإنسان والحريات وحمايتها، وبضمان ممارستها الكاملة، والنهوض بها وبصيانة كرامة وحقوق وحريات المواطنات والمواطنين، أفرادا وجماعات، وذلك في نطاق الحرص التام على احترام المرجعيات الوطنية والكونية في هذا المجال.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 161', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 162 من دستور 2011؟', 'الوسيط مؤسسة وطنية مستقلة ومتخصصة، مهمتها الدفاع عن الحقوق في نطاق العلاقات بين الإدارة والمرتفقين، والإسهام في ترسيخ سيادة القانون، وإشاعة مبادئ العدل والإنصاف، وقيم التخليق والشفافية في تدبير الإدارات والمؤسسات العمومية والجماعات الترابية والهيئات التي تمارس صلاحيات السلطة العمومية.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 162', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 163 من دستور 2011؟', 'يتولى مجلس الجالية المغربية بالخارج، على الخصوص، إبداء آرائه حول توجهات السياسات العمومية التي تمكن المغاربة المقيمين بالخارج من تأمين الحفاظ على علاقات متينة مع هويتهم المغربية، وضمان حقوقهم وصيانة مصالحهم، وكذا المساهمة في التنمية البشرية والمستدامة في وطنهم المغرب وتقدمه.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 163', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 164 من دستور 2011؟', 'تسهر الهيأة المكلفة بالمناصفة ومحاربة جميع أشكال التمييز، المحدثة بموجب الفصل 19 من هذا الدستور، بصفة خاصة، على احترام الحقوق والحريات المنصوص عليها في الفصل المذكور، مع مراعاة الاختصاصات المسندة للمجلس الوطني لحقوق الإنسان. هيئات الحكامة الجيدة والتقنين', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 164', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 165 من دستور 2011؟', 'تتولى الهيأة العليا للاتصال السمعي البصري السهر على احترام التعبير التعددي لتيارات الرأي والفكر، والحق في المعلومة في الميدان السمعي البصري، وذلك في إطار احترام القيم الحضارية الأساسية وقوانين المملكة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 165', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 166 من دستور 2011؟', 'مجلس المنافسة هيأة مستقلة، مكلفة في إطار تنظيم منافسة حرة ومشروعة بضمان الشفافية والإنصاف في العلاقات الاقتصادية، خاصة من خلال تحليل وضبط وضعية المنافسة في الأسواق، ومراقبة الممارسات المنافية لها والممارسات التجارية غير المشروعة وعمليات التركيز الاقتصادي والاحتكار.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 166', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 167 من دستور 2011؟', 'تتولى الهيأة الوطنية للنزاهة والوقاية من الرشوة ومحاربتها، المحدثة بموجب الفصل 36، على الخصوص، مهام المبادرة والتنسيق والإشراف وضمان تتبع تنفيذ سياسات محاربة الفساد، وتلقي ونشر المعلومات في هذا المجال، والمساهمة في تخليق الحياة العامة، وترسيخ مبادئ الحكامة الجيدة، وثقافة المرفق العام، وقيم المواطنة المسؤولة. هيئات النهوض بالتنمية البشرية والمستدامة والديمقراطية التشاركية', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 167', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 168 من دستور 2011؟', 'يحدث مجلس أعلى للتربية والتكوين والبحث العلمي. المجلس هيأة استشارية، مهمتها إبداء الآراء حول كل السياسات العمومية، والقضايا الوطنية التي تهم التربية والتكوين والبحث العلمي، وكذا حول أهداف المرافق العمومية المكلفة بهذه الميادين وسيرها. كما يساهم في تقييم السياسات والبرامج العمومية في هذا المجال.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 168', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 169 من دستور 2011؟', 'يتولى المجلس الاستشاري للأسرة والطفولة، المحدث بموجب الفصل 32 من هذا الدستور، مهمة تأمين تتبع وضعية الأسرة والطفولة، وإبداء آراء حول المخططات الوطنية المتعلقة بهذه الميادين، وتنشيط النقاش العمومي حول السياسة العمومية في مجال الأسرة، وضمان تتبع وإنجاز البرامج الوطنية، المقدمة من قبل مختلف القطاعات، والهياكل والهيئات المختصة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 169', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 170 من دستور 2011؟', 'يعتبر المجلس الاستشاري للشباب والعمل الجمعوي، المحدث بموجب الفصل 33 من هذا الدستور، هيأة استشارية في ميادين حماية الشباب والنهوض بتطوير الحياة الجمعوية. وهو مكلف بدراسة وتتبع المسائل التي تهم هذه الميادين، وتقديم اقتراحات حول كل موضوع اقتصادي واجتماعي وثقافي، يهم مباشرة النهوض بأوضاع الشباب والعمل الجمعوي، وتنمية طاقاتهم الإبداعية، وتحفيزهم على الانخراط في الحياة الوطنية، بروح المواطنة المسؤولة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 170', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 171 من دستور 2011؟', 'يحدد بقوانين تأليف وصلاحيات وتنظيم وقواعد سير المؤسسات والهيئات المنصوص عليها في الفصول 161 إلى 170 من هذا الدستور، وكذا حالات التنافي عند الاقتضاء. الباب الثالث عشر: مراجعة الدستور', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 171', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 172 من دستور 2011؟', 'للملك ولرئيس الحكومة ولمجلس النواب ولمجلس المستشارين، حق اتخاذ المبادرة قصد مراجعة الدستور. للملك أن يعرض مباشرة على الاستفتاء، المشروع الذي اتخذ المبادرة بشأنه.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 172', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 173 من دستور 2011؟', 'لا تصح الموافقة على مقترح مراجعة الدستور الذي يتقدم به عضو أو أكثر من أعضاء أحد مجلسي البرلمان، إلا بتصويت أغلبية ثلثي الأعضاء الذين يتألف منهم المجلس. يُحال المقترح إلى المجلس الآخر، الذي يوافق عليه بنفس أغلبية ثلثي الأعضاء الذين يتألف منهم. يُعرض المقترح الذي يتقدم به رئيس الحكومة على المجلس الوزاري، بعد التداول بشأنه في مجلس الحكومة.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 173', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 174 من دستور 2011؟', 'تُعرض مشاريع ومقترحات مراجعة الدستور، بمقتضى ظهير، على الشعب قصد الاستفتاء. تكون المراجعة نهائية بعد إقرارها بالاستفتاء. للملك، بعد استشارة رئيس المحكمة الدستورية، أن يعرض بظهير، على البرلمان، مشروع مراجعة بعض مقتضيات الدستور. ويصادق البرلمان، المنعقد، بدعوة من الملك، في اجتماع مشترك لمجلسيه، على مشروع هذه المراجعة، بأغلبية ثلثي الأعضاء الذين يتألف منهم. يحدد النظام الداخلي لمجلس النواب كيفيات تطبيق هذا المقتضى. تراقب المحكمة الدستورية صحة إجراءات هذه المراجعة، وتعلن نتيجتها.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 174', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 175 من دستور 2011؟', 'لا يمكن أن تتناول المراجعة الأحكام المتعلقة بالدين الإسلامي، وبالنظام الملكي للدولة، وبالاختيار الديمقراطي للأمة، وبالمكتسبات في مجال الحريات والحقوق الأساسية المنصوص عليها في هذا الدستور. الباب الرابع عشر: أحكام انتقالية وختامية', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 175', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 176 من دستور 2011؟', 'إلى حين انتخاب مجلسي البرلمان، المنصوص عليهما في هذا الدستور، يستمر المجلسان القائمان حاليا في ممارسة صلاحياتهما، ليقوما على وجه الخصوص، بإقرار القوانين اللازمة لتنصيب مجلسي البرلمان الجديدين، وذلك دون إخلال بالأحكام المنصوص عليها في الفصل 51 من هذا الدستور.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 176', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 177 من دستور 2011؟', 'يستمر المجلس الدستوري القائم حاليا في ممارسة صلاحياته، إلى أن يتم تنصيب المحكمة الدستورية المنصوص عليها في هذا الدستور.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 177', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 178 من دستور 2011؟', 'يستمر المجلس الأعلى للقضاء في ممارسة صلاحياته، إلى أن يتم تنصيب المجلس الأعلى للسلطة القضائية، المنصوص عليه في هذا الدستور.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 178', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 179 من دستور 2011؟', 'تظل النصوص المتعلقة بالمؤسسات والهيئات المذكورة في الباب الثاني عشر من هذا الدستور، وكذا تلك المتعلقة بالمجلس الاقتصادي والاجتماعي وبالمجلس الأعلى للتعليم، سارية المفعول، إلى حين تعويضها، طبقا لمقتضيات هذا الدستور.', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 179', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true),
  ('ماذا ينص الفصل 180 من دستور 2011؟', 'مع مراعاة المقتضيات الانتقالية الواردة في هذا الباب، يُنسخ نص الدستور المراجع الصادر بتنفيذه الظهير الشريف رقم 1.96.157 المؤرخ في 23 من جمادى الأولى 1417 (7 أكتوبر 1996). الفهرس الباب العنوان — الدستور (التصدير) الباب الأول أحكام عامة (الفصول 1–18) الباب الثاني الحريات والحقوق الأساسية (الفصول 19–40) الباب الثالث الملكية (الفصول 41–59) الباب الرابع السلطة التشريعية (الفصول 60–86): تنظيم البرلمان، سلطات البرلمان، ممارسة السلطة التشريعية الباب الخامس السلطة التنفيذية (الفصول 87–94) الباب السادس العلاقات بين السلط (الفصول 95–106) الباب السابع السلطة القضائية (الفصول 107–128) الباب الثامن المحكمة الدستورية (الفصول 129–134) الباب التاسع الجهات والجماعات الترابية الأخرى (الفصول 135–146) الباب العاشر المجلس الأعلى للحسابات (الفصول 147–150) الباب الحادي عشر المجلس الاقتصادي والاجتماعي والبيئي (الفصول 151–153) الباب الثاني عشر الحكامة الجيدة (الفصول 154–171) الباب الثالث عشر مراجعة الدستور (الفصول 172–175) الباب الرابع عشر أحكام انتقالية وختامية (الفصول 176–180)', ARRAY['seed:constitution-2011', 'دستور', 'الفصل 180', '2011'], '/pro-tools/references', 'دستور المملكة المغربية (2011)', true);
